INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-7','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Housing Exception Request</strong></p>','','ApplicationHome','Admit;Confirmed','','','','','','','','','','','','Request Housing Exception (UGTR)','','UGTRRequestHousingException','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-8','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(68, 68, 68);">Missing documents can also be mailed to:</span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Unofficial transcripts may be uploaded through the portal using the Transcript Upload feature to the right. Students must have official transcripts upon arrival to St. Thomas.</span></p>','International','ApplicationHome','Started App;Submitted App;Temporary Hold','','','','','','','','','','','','Submit Missing Docs INTL (UGTR)','','UGTRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-9','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(37, 36, 35);">Contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="font-size: 16px; color: rgb(91, 95, 199); background-color: rgb(255, 255, 255);">admissions counselor</a><span style="font-size: 16px; color: rgb(37, 36, 35);"> with any questions.</span></p>','International','ApplicationHome','Submitted App;Temporary Hold','','','','','','','','','','','','UG Submitted INTL (UGTR)','','UGTRSubmittedINTL','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
