INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-13','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the School of Nursing</strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Mentor Program Application!</strong></p><p style="text-align: center;"><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Mentors:</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Thank you for your interest in serving as a volunteer mentor to pre-licensure student(s) enrolled in the Susan S. Morrison School of Nursing at the University of St. Thomas. To best match our students to mentors, please submit the following application.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Please note: All mentors for this program must be a licensed RN.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Mentees (Current Students):</strong></p><p><span style="font-size: 16px;">Thank you for your interest in connecting with a professional RN and volunteer mentor with the Susan S. Morrison School of Nursing at the University of St. Thomas. To best match you with an available mentor, please submit the following application. </span></p><p><br></p><p><em style="font-size: 16px;">Please use your St. Thomas (non-vanity) email address for your application: </em><a href="mailto:username@stthomas.edu" target="_blank" style="font-size: 16px;"><em>username@stthomas.edu</em></a><em style="font-size: 16px;">. Ex: </em><a href="mailto:xxxx0001@stthomas.edu" target="_blank" style="font-size: 16px;"><em>xxxx0001@stthomas.edu</em></a><em style="font-size: 16px;">.</em></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','','','','','Welcome (SONMENTOR)','','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-20');
