INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-15','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Student Success Director</strong></p><p><span style="color: rgb(0, 0, 0);">Jessica Nelson</span></p><p><a href="mailto:jessica.nelson@stthomas.edu" target="_blank">jessica.nelson@stthomas.edu</a></p><p><br></p><p>Please don&#39;t hesitate to reach out with a question. </p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement','','','','','','','','','','','','','Director Contact Info (SONMENTOR)','','','','2.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-20');
