INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-19','Active','','','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Fall Transfer Timeline</strong></p>','','ApplicationHome','Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Committee','','','','','','','Fall 2024','','','','','Admissions Decisions Dates-NoSlide (UGTR)','','UGTRAdmissionsDecisionsDates','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-20','Active','','','','','','ApplicationHome','Admit','','','','','','','Spring 2025;Fall 2025','','','','','Admit Confetti Message with BUTTON (UGFR)','','UGFRAdmitConfettiMessagewithButton','<div class="animation"><center>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-21','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p><br></p><p><span style="font-size: 16px;">Thanks for all your hard work getting everything in.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Now you’re probably wondering when you’ll hear back from us with a decision. Check the Admissions Decision Timeline information.</span></p><p><br></p><p><span style="font-size: 16px;">Please be advised that if you are admitted, you may still need to submit additional documentation to qualify for your student visa. You can find more details about these requirements on the </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank" style="font-size: 16px;">International Admissions website</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Questions? Contact us at </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px;">international@stthomas.edu</a><span style="font-size: 16px;">. We&#39;d love to hear from you!</span></p>','International','ApplicationHome','Complete App;File Hold','','','','','','','','','','','','Graphic: UG Complete INTL (UGTR)','','UGCompleteINTLUGTR','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-22','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the International Transfer Application!</strong></p><p><br></p><p>Thank you for beginning your application. <span style="color: rgb(68, 68, 68);">Use the Application Portal above to follow the steps to submit your application. For questions, contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a>. You can find more details on the <a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank">International Admissions website</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Application Timelines</strong></p><p><span style="color: rgb(68, 68, 68);">All international student applications are reviewed on a rolling basis. Admission decisions will generally be issued within two weeks of receiving a complete application.</span></p>','International','ApplicationHome','Started App','','','','','','','Spring 2025;Fall 2025;Spring 2026;Fall 2026','','','','','Graphic: UG Started INTL (UGTR)','','GraphicUGStartedNTLUGTR','','2.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-23','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is pending</strong>. </p><p><br></p><p>Please c<span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">ontact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a> for more information.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Pending;File Hold','','','','','','','','','','','','Graphic: UG Pending (UGTR)','','','','3.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-24','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations on your acceptance </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">to the University of St. Thomas!</strong><span style="color: rgb(109, 54, 150); font-size: 20px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Keep an eye on your mailbox because you&#39;ll soon be receiving an enrollment guide that details the next steps of the enrollment process. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Confirming Deposit</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you&#39;ve decided to attend St. Thomas for </span><strong style="color: rgb(33, 33, 33); font-size: 16px;">fall 2025</strong><span style="color: rgb(33, 33, 33); font-size: 16px;">, a $200 deposit reserves your spot in the class. </span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); font-size: 16px;">﻿Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Course Registration</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Fall registration will open for new transfer students in early May. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">On-Campus Housing</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you will be living on campus, you’re required to submit a $200 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. All incoming transfer students with fewer than two semesters of college are required to meet the on-campus residency requirement. More information on this policy and other important housing information can be found on Residence Life&#39;s webpage </span><a href="https://www.stthomas.edu/tr/visit/" target="_blank" style="color: rgb(29, 117, 204); font-size: 16px;"><u>for transfer students.</u></a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Admitted Student Website</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/admitted-students/index.html" target="_blank" style="color: rgb(29, 117, 204); font-size: 16px;"><u>transfer admitted students</u></a><span style="color: rgb(33, 33, 33); font-size: 16px;"> page to claim your St. Thomas account, activate your St. Thomas email address and learn about our deposit refund policies. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Fall 2025','','','','','Graphic: UG Admit Fall (UGTR)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-25','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 15pt;">Congratulations on your acceptance to </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 15pt;">the University of St. Thomas!</strong><span style="color: rgb(109, 54, 150); font-size: 15pt;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px;">We are very pleased to welcome you to our community. You will be receiving an email containing your official admission letter and detailed instructions about your next steps.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">Your </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; background-color: rgb(255, 255, 255);"> </strong><span style="font-size: 16px; background-color: rgb(255, 255, 255);">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Confirming Deposit</strong><span style="font-size: 16px; color: rgb(109, 54, 150);"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px;">fall 2025</strong><span style="font-size: 16px;">, a $200 confirming deposit reserves your spot in the class. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255);">An additional $200 deposit puts you on the list for on-campus housing. To submit your deposit(s) you will need your St. Thomas ID.</span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;"> </span></p><p><span style="background-color: white; font-size: 16px;">Deposits for fall term are refundable until </span><strong style="font-size: 16px;">May 1, 2025</strong><span style="font-size: 16px;">.  </span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Depositing from outside the U.S.? </strong></p><p><span style="background-color: white; font-size: 16px;">If you are submitting your deposit from outside the U.S., </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">please submit your deposit</a><span style="font-size: 16px;"> through </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">Flywire.com</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; background-color: white;">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; background-color: white;">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/international-students/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: white;">documentation of financial support</a><span style="font-size: 16px; background-color: white;">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">Qualify for your I-20 here</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><span style="font-size: 16px;">If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Claim Your St. Thomas online account</strong></p><p><span style="font-size: 16px;">To claim your account, please visit </span><a href="https://accountclaim.stthomas.edu/" target="_blank" style="font-size: 16px;">Account Claim</a><span style="font-size: 16px;">. Be sure to set a strong password and set up two factor authentication using the Microsoft Authenticator App. </span><strong style="font-size: 16px;">Text message authentication WILL NOT work outside of the US.</strong><span style="font-size: 16px;"> Instructions to setting up two factor authentication can be found in the </span><a href="https://services.stthomas.edu/TDClient/1898/ClientPortal/KB/ArticleDet?ID=97640" target="_blank" style="font-size: 16px;">ITS Knowledge Base</a><span style="font-size: 16px;">.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Course Registration</strong><span style="font-size: 16px; color: rgb(109, 54, 150);"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Fall registration will open for new transfer students in early May. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="background-color: white; font-size: 16px;">Also feel free to reach out to one of our </span><a href="https://stthomas.edu/admissions/international-students/student-ambassadors/index.html#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="background-color: white; font-size: 16px;">International Student Ambassadors</a><span style="background-color: white; font-size: 16px;"> to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','Fall 2025','','','','','Graphic: UG Admit INTL (UGTR)','','UGAdmitINTLUGTR','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-26','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p> </p><p>St. Thomas accepts transfer students on a rolling basis for spring semesters. Usually, you’ll hear back from us within 2-3 weeks of submitting all required documents.</p><p> </p><p>Contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor" target="_blank">admissions counselor</a> with questions.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Complete App;Pending;Second Review;Committee','','','','','','','Spring 2025','','','','','Spring: UG Complete (UGTR)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
