INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-37','Active','','','Status: Accepted','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">What&#39;s next? Please complete your Intent to Enroll form to confirm your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Admit','','','','','','','','','','','','Graphic: GR Admit (GSOEd)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-11');
