INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-40','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Contact Undergraduate Admissions</strong></p><p><br></p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6150</p><p><a href="mailto:admissions@stthomas.edu" target="_blank">admissions@stthomas.edu</a></p>','International;U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;Withdrawn;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Committee','','','','','','','','','','','','Contact Admissions (UGTR)','','UGContactAdmissions','<div class="USTlineborder"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-41','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Account</strong></p><p style="text-align: center;"></p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','User Info Logout (UGTR)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-42','Active','','','','','','ApplicationRequirement','','','','','','','','','','','','','Progress Bar (UGTR)','','','','','','','Top','Central Daylight Time (America/Chicago)','Progress Bar','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-43','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete! </strong></p><p><br></p><p>Thank you for your application to Dougherty Family College. We are reviewing your application and will reach out to you soon.</p><p><br></p><p>Questions? Contact your <a href="https://dfc.stthomas.edu/contact-us/index.html" target="_blank">admissions counselor</a>.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Complete App;Second Review','','','','','','','','','','','','Graphic: UG Complete (DFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-44','Active','','','','<p><strong style="color: rgb(109, 54, 150);">Contact Admissions</strong></p><p><br></p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6150</p><p>admissions@stthomas.edu</p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Committee','','','','','','','','','','','','Contact Admissions (DFC)','','UGContactAdmissions','<div class="USTlineborder"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-45','Active','','','','','','ApplicationRequirement','','','','','','','','','','','','','Progress Bar (DFC)','','','','3.0','','','Top','Central Daylight Time (America/Chicago)','Progress Bar','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-46','Active','','','Status: Waitlist','<p style="text-align: center;"></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Deferred Admit','','','','','','','','','','','','Graphic: UG Waitlist (DFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-47','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on being admitted to </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Dougherty Family College!</strong></p><p><br></p><p><span style="font-size: 16px;">We are excited to have you join our community and the incoming class for Fall 2025. There’s a lot of information we’d like to share with you, but below are the most important items to note moving forward.</span></p><p><br></p><p><strong style="background-color: rgb(255, 255, 255); color: rgb(109, 54, 150); font-size: 18px;">Confirming Deposit</strong></p><p><span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);">In order to secure your spot at Dougherty Family College for Fall 2025, you must submit a $50 deposit. </span></p><p><br></p><p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">The 2025 FAFSA application and MN Dream Act are now available. You should apply for financial aid as soon as possible as offers of admission to the Dougherty Family College are conditioned on an applicant&#39;s demonstration that they have sufficiently high financial need to qualify for institutional financial aid. </span></p><p><br></p><p><span style="font-size: 16px;">Please feel free to contact Padra Xiong, Financial Aid Counselor, with questions. She can be reached at (651) 962-8031 or padra.xiong@stthomas.edu.</span></p><p><br></p><p><strong style="font-size: 16px;">All Dougherty Family College students are required to file either the </strong><a href="https://www.stthomas.edu/admissions/undergraduate/financial-aid/fafsa/" target="_blank" style="font-size: 16px;"><strong>FAFSA or MN Dream Act</strong></a><strong style="font-size: 16px;">. </strong><span style="font-size: 16px;">Detailed information pertaining to your financial aid will be mailed to you after we have received your FAFSA or MN Dream Act.</span></p>','','ApplicationHome','Admit','','','','','','','Fall 2025','','','','','Graphic: UG Admit (DFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
