INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-131','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to Graduate Programs in Engineering &amp; Software!</strong></p><p style="text-align: center;"><br></p><p><span style="color: rgb(0, 0, 0); font-size: 14px; background-color: rgb(255, 255, 255);">Thank you for starting an application to Graduate Programs in Engineering &amp; Software! For questions about the application or our programs, please contact our Graduate Admissions team at 651-962-6190 or</span><span style="color: rgb(109, 54, 150); font-size: 14px; background-color: rgb(255, 255, 255);"> gradengine﻿ering@stthomas.edu</span><span style="color: rgb(0, 0, 0); font-size: 14px; background-color: rgb(255, 255, 255);">.</span><span style="color: rgb(0, 0, 0); font-size: 16px; background-color: rgb(255, 255, 255);"> </span></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','','','','','Welcome (GSOE)','','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-14');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-132','Active','Common App','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Contact Undergraduate Admissions</strong></p><p> </p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6150</p><p><a href="mailto:admissions@stthomas.edu?subject=Contact%20Admissions%20" target="_blank">admissions@stthomas.edu</a></p><p> </p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;File Hold;Temporary Hold','','','','','','','','','','','','Contact Admissions w/ Social Links (UGFRCA)','','UGContactAdmissions','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-133','Active','Common App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Scholarships </strong></p><p style="text-align: center;"></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App;Submitted App;Complete App;Admit;Confirmed;File Hold;Committee','','','','','','','Fall 2023','','','','','UG First-Year Scholarship Link (UGFRCA)','','UGFRScholarshipLink','<div class="USTline2"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-134','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150); background-color: rgb(255, 255, 255);">Your application is complete!</strong></p><p><br></p><p><span style="font-size: 16px;">T</span><span style="font-size: 16px; color: rgb(0, 0, 0);">hank you for completing your application. Please check the Admissions Decision Timeline for more information about next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Please be advised that if you are admitted, you may still need to submit additional documentation to qualify for your student visa. You can find more details about these requirements on the </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank" style="font-size: 16px;">International Admissions website</a><span style="font-size: 16px;">. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Questions? Contact us at international@stthomas.edu. </span></p>','International','ApplicationHome','Complete App;File Hold;Second Review;Committee','','','','','','','','','','','','Graphic: UG Complete INTL (UGFR)','','UGCompleteINTLUGFR','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-135','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Welcome to the First-Year Application!</strong></p><p><br></p><p>Thank you for starting your application to the University of St. Thomas. Your admissions portal will guide you on the steps needed to complete your application.</p><p><br></p><p>For questions, you may contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/index.html" target="_blank">admissions counselor</a>.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App','','','','','','','Spring 2025','','','','','Graphic: UG Started App (UGFR)','','','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
