INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-160','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Contact Undergraduate Admissions</strong></p><p><br></p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6150</p><p><a href="mailto:admissions@stthomas.edu?subject=Contact%20Admissions%20" target="_blank">admissions@stthomas.edu</a></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;Withdrawn;File Hold;Temporary Hold','','','','','','','','','','','','Contact Admissions w/ Social Links (UGFR)','','UGContactAdmissions','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-161','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Transcripts</strong></p><p><br></p><p>We will accept unofficial transcripts for your application. Transcripts may be mailed, faxed or emailed using the addresses below:</p><p><br></p><p><strong>Mail:</strong></p><p>University of St. Thomas</p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN 55105-1096</p><p><strong>Email:</strong> <a href="mailto:admissions@stthomas.edu" target="_blank" style="color: rgb(0, 0, 255);">admissions@stthomas.edu</a></p><p><strong>Fax:</strong> (651) 962-6160</p><p><br></p><p>Official transcripts can be sent electronically to the University of St. Thomas through programs such as Parchment or Naviance.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Submitted App','','','','','','','Fall 2024;Spring 2025;Summer 2025;Fall 2025;Spring 2026;Summer 2026;Fall 2026','','','','','Submit Transcripts (UGFR)','','UGFRSubmitTranscripts','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-162','Active','','','','<p><strong style="color: rgb(109, 54, 150);">DFC Application Timeline</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;File Hold;Second Review','','','','','','','Fall 2025','','','','','Timeline Text: UG Submitted (DFC)','','','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-163','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Welcome to the Dougherty Family College Application!</strong></p><p><br></p><p>Thank you for starting your application to Dougherty Family College! We review applications on a rolling basis. Space in our class is limited, so please complete your application as soon as possible. To have a complete application on file, you must submit your high school transcript.</p>','International;U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App','','','','','','','Fall 2025','','','','','Graphic: DFC Started App (DFC)','','','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
