INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-182','Active','','','Status: Accepted','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">What&#39;s next? Please complete your Intent to Enroll form to confirm your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Admit','','','','','','','','','','','','Graphic: GR Admit (GSON)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-183','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the Susan S. Morrison School of Nursing!</strong></p><p style="text-align: center;"><br></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">The MSN application cycle </span><span style="color: rgb(43, 43, 43); background-color: rgb(255, 255, 255);">for fall 2025 will open August 1. Please refer to the following timelines:</span></p><p><br></p><ul><li><span style="background-color: rgb(255, 255, 255); color: rgb(43, 43, 43);">August 1 - October 31: Early Review and Early Admission Notice</span></li><li><span style="background-color: rgb(255, 255, 255); color: rgb(43, 43, 43);">October 31 - January 1: Regular Review</span></li></ul>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','','','','','Welcome (GSON)','','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-184','Active','','','Status: Confirmed','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll. Please watch your email for further communications on next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Confirmed','','','','','','','','','','','','Graphic: GR Confirmed (GLAW)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-13');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-185','Active','Common App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the International First-Year Application! </strong></p><p><br></p><p>Thank you for beginning your application. <span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">Use the Application Portal above to follow the steps to submit your application. For questions, contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a>. You can find more details on the <a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank">International Admissions website</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Application Timelines </strong></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">All international student applications are reviewed on a rolling basis. Admission decisions will generally be issued within two weeks of receiving a complete application. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Missing Documents</strong></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">Please email your missing documents to international@stthomas.edu. </span></p>','International','ApplicationHome','Started App','','','','','','','','','','','','Graphic: UG Started INTL (UGFRCA)','','GraphicUGStartedNTLUGFR','','2.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-186','Active','','','','<p><strong style="background-color: rgb(255, 255, 255); color: rgb(109, 54, 150); font-size: 18px;">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="color: rgb(37, 36, 35); font-size: 16px;">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="color: rgb(91, 95, 199); font-size: 16px; background-color: rgb(255, 255, 255);">admissions counselor</a><span style="color: rgb(37, 36, 35); font-size: 16px;"> is here to help as you navigate the application process. </span></p>','International','ApplicationHome','Submitted App;Temporary Hold','','','','','','','','','','','','UG Submitted INTL (UGFR)','','UGFRSubmittedINTL','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-187','Active','Common App','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150); background-color: rgb(255, 255, 255);">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(37, 36, 35);">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="font-size: 16px; color: rgb(91, 95, 199); background-color: rgb(255, 255, 255);">admissions counselor</a><span style="font-size: 16px; color: rgb(37, 36, 35);"> is here to help as you navigate the application process. Contact them to ask any questions.</span></p>','International','ApplicationHome','Submitted App;Temporary Hold','','','','','','','','','','','','UG Submitted INTL (UGFRCA)','','UGFRSubmittedINTL','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-188','Active','Common App','','','<p><strong style="background-color: rgb(255, 255, 255); color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p><br></p><p><span style="font-size: 16px;">Thanks for all your hard work getting everything in.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Now you’re probably wondering when you’ll hear back from us with a decision. Check the Admissions Decision Timeline information.</span></p><p><br></p><p><span style="font-size: 16px;">Please be advised that if you are admitted, you may still need to submit additional documentation to qualify for your student visa. You can find more details about these requirements on the </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank" style="font-size: 16px;">International Admissions website</a><span style="font-size: 16px;">. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="color: rgb(68, 68, 68); font-size: 16px;">Questions? Contact us at international@stthomas.edu. We&#39;d love to hear from you!</span></p>','International','ApplicationHome','Complete App;File Hold;Second Review;Committee','','','','','','','','','','','','Graphic: UG Complete INTL (UGFRCA)','','UGCompleteINTLUGFR','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-189','Active','Common App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations on your acceptance to the </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">University of St. Thomas!</strong><span style="color: rgb(109, 54, 150);"> </span></p><p style="text-align: center;"><span style="color: rgb(131, 72, 173);"> </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Interested in Enrolling? </strong></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie! </span><span style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">﻿Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0); background-color: rgb(255, 255, 255);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);"> </strong><span style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">is {{Banner_Id}}.</span></p><p><br></p><p><strong style="font-size: 16px;">All students are required to submit a $400 deposit to reserve their place in the class. </strong><span style="font-size: 16px;"> </span></p><p><br></p><p><span style="font-size: 16px;">Since </span><a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank" style="font-size: 16px;">all first-year students are required to live on campus</a><span style="font-size: 16px;">, this deposit also reserves your place in on-campus housing. The date you submit it is one of many factors that determine your housing placement.  </span></p><p><br></p><p><span style="font-size: 16px;">Half ($200) of the deposit will be applied to your housing bill at the beginning of the term. If you’re allowed an exception from our on-campus living requirement, it will instead be applied to your tuition charges. The remaining $200 will be applied to other student fees.  </span></p><p><br></p><p><span style="font-size: 16px;">﻿Deposits for fall term are refundable until </span><strong style="font-size: 16px;">May 1, 2024</strong><span style="font-size: 16px;">.  </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Depositing from outside the U.S.? </strong></p><p><span style="font-size: 16px;">If you are submitting your deposit from </span><strong style="font-size: 16px;">outside</strong><span style="font-size: 16px;"> the U.S., please </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">submit your deposit</a> <span style="font-size: 16px;">through </span><a href="https://flywire.com/" target="_blank" style="font-size: 16px;">Flywire.com</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is necessary to obtain a student visa. Further instructions will be provided after your deposit is received. You will be required to submit </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">documentation of financial support</a><span style="font-size: 16px;">, and in some cases, additional items may be required. </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/admitted-students/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Qualify for your I-20 here</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="font-size: 16px;"> If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><br></p><p><span style="color: rgb(68, 68, 68); font-size: 16px;">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="font-size: 16px;">Also feel free to reach out to one of our </span><a href="https://www.stthomas.edu/oiss/firststeps/ambassadors/#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">International Student Ambassadors</a><span style="font-size: 16px;"> to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','','','','','','Graphic: UG Admit INTL (UGFRCA)','','UGAdmitINTLUGFR','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-190','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(26, 103, 156); background-color: rgb(255, 255, 255);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px; color: rgb(26, 103, 156);">website</a><span style="font-size: 16px;">. </span></p><p><br></p><p><span style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">Missing documents can also be mailed to: </span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas. </span></p>','International','ApplicationHome','Started App;Submitted App;Temporary Hold','','','','','','','','','','','','Submit Missing Docs INTL (UGFR)','','UGFRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-191','Active','Common App','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;">. </span></p><p><br></p><p><span style="font-size: 16px;">Missing documents can also be mailed to: </span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas. </span></p>','International','ApplicationHome','Started App;Submitted App;Temporary Hold','','','','','','','','','','','','Submit Missing Docs INTL (UGFRCA)','','UGFRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-192','Active','Common App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">International Scholarships</strong></p><p style="text-align: center;"></p>','International','ApplicationHome','Started App;Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Committee;Temporary Hold','','','','','','','Fall 2023','','','','','UG Scholarships Link INT Common App (UGFRCA)','','UGScholarshipsLinkINTUGFR','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-193','Active','','','','','','ApplicationRequirement','','','','','','','','','','','','','Progress Bar (GSON)','','','','','','','Top','Central Daylight Time (America/Chicago)','Progress Bar','Application_Control__c-9');
