INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-201','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Contact Admissions</strong></p><p><br></p><p>Office of International Students &amp; Scholars</p><p>Mail 5014</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6650</p><p>international@stthomas.edu</p>','International','ApplicationPortal;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;Withdrawn;File Hold;Second Review;Committee;Temporary Hold','','','','','','','','','','','','Contact INTL (UGFR)','','UGFRContactINTL','<div class="USTlineborder"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-202','Active','Common App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Contact Admissions</strong></p><p><br></p><p>Office of International Students &amp; Scholars</p><p>Mail 5014</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p><p>Phone: (651) 962-6650</p><p>international@stthomas.edu</p>','International','ApplicationPortal;ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;Withdrawn;File Hold;Second Review;Committee;Temporary Hold','','','','','','','','','','','','Contact INTL (UGFRCA)','','UGFRContactINTL','<div class="USTlineborder"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-203','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Housing Exception Request</strong></p>','','ApplicationHome','Admit;Confirmed','','','','','','','Spring 2025;Fall 2025','','','','','Request Housing Exception (UGFR)','','UGFRRequestHousingException','<div class="line"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-204','Active','','','','<p style="text-align: center;"><strong style="color: rgb(131, 72, 173); font-size: 20px;">Attention New Applicants</strong></p><p style="text-align: center;"><br></p><p>Thank you for starting an application to participate in the Susan S. Morrison School of Nursing RN Mentoring Program.</p><p><br></p><p>You will receive an email from the Admission Office. Please ignore it. You will be considered for the mentoring program as soon as your application is complete.</p><p><br></p><p>Once your application is completed we will match you as soon as possible. Typically, we make the most matches in the early fall, however, we do keep the application open for mentors and mentees all year, and we will make connections as soon as possible. Until then, your application will remain on file, and we reach out to confirm availability before finalizing a mentor/mentee pairing.</p><p><br></p><p>If you have questions, please contact <a href="mailto:nursing@stthomas.edu" target="_blank">nursing@stthomas.edu</a> or (651) 962-7800.</p><p><br></p><p>Thanks for your interest in the RN Mentoring Program!</p><p><br></p><p>Sincerely,</p><p>The Susan S. Morrison School of Nursing Team</p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','','','','','Email Notification (SONMENTOR)','','','','0.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-20');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-205','Active','','','Status: Pending','<p><span style="font-size: 16px;">Hello! Thank you for applying for the Susan S. Morrison School of Nursing. You had many wonderful qualifications, and have placed you on the waitlist at this time. </span></p><p><br></p><p><span style="font-size: 16px;">We could pull you from this waitlist up to August 1, 2023, to fill our seats in the program. Please complete any pre-requisites and send your final transcripts as soon as possible.</span></p>','','ApplicationHome','Pending','','','','','','','','','','','','Graphic: GR MSN Waitlist (GSON)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
