INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-216','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Contact Admissions</strong></p><p><br></p><p>Abby Farnham</p><p>Senior Transfer Admissions Counselor</p><p><a href="mailto:abby.farnham@stthomas.edu" target="_blank">abby.farnham@stthomas.edu</a></p><p>Phone: (651) 962-6528</p><p><br></p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN, 55105-1096</p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement;ApplicationHome','Started App;Submitted App;Complete App;Denied;Admit;Confirmed;File Hold;Committee','','','','','','','','','','','','Contact Admissions (UGTRDFC)','','UGFRContactAdmissions','<div class="USTlineborder"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-217','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Thank you for submitting your Transition DFC Application!</strong></p><p><br></p><p>Admissions decisions are being made on a continuous basis. Please check your admissions portal regularly for the latest updates and detailed information regarding your admission status.</p><p><br></p><p>If you have any questions in the meantime, feel free to reach out at any time.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Submitted App','','','','','','','','','','','','Graphic: UG Submitted (UGTRDFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-6');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-218','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Welcome to the Transition DFC Admission Application!</strong></p><p><br></p><p>Congratulations on taking the next step to transitioning to the four-year university. </p><p><br></p><p>Use the Application Portal above to follow the steps to submit your application. For questions, contact <a href="mailto:abby.farnham@stthomas.edu" target="_blank">Abby Farnham</a>, Senior Transfer Admissions Counselor.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App','','','','','','','','','','','','Graphic: UG Started App (UGTRDFC)','','UGFRStarted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-6');
