INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-226','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Bachelor of Science in Nursing Application Instructions</strong></p><p><br></p><p><span style="font-size: 16px;">In order to begin your Bachelor of Science in Nursing (BSN) application, you&#39;ll need to log into your Admissions Portal by following these instructions:</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Previously accessed your Admissions Portal?</strong></p><ol><li><span style="font-size: 16px; color: rgb(10, 10, 10);"> Log into your Admissions Portal using the </span><a href="https://uofstthomasmn.my.site.com/Admissions/ApplicationLogin" target="_blank" style="font-size: 16px;"><strong>application login</strong></a>; <span style="font-size: 16px;">you will need to use the email and password you used to apply to St. Thomas.</span></li><li><span style="font-size: 16px; color: rgb(10, 10, 10);">Once logged into your Admissions Portal, you&#39;ll need to open the </span><a href="/Admissions/ApplicationRegistration?at=UGBSN" target="_blank" style="font-size: 16px;">Bachelor of Nursing (BSN) application</a><span style="font-size: 16px;"> in another window </span><span style="font-size: 16px; color: rgb(10, 10, 10);">to complete your application.</span></li></ol><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Never logged into your Admissions Portal?</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Please use your St. Thomas (non-vanity) email address for your application: username@stthomas.edu.</span><em style="font-size: 16px; color: rgb(0, 0, 0);"> Ex: xxxx0001@stthomas.edu.</em></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','','','','','Welcome (UGBSN)','','','','1.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-227','Active','','','Status: Submitted','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(112, 48, 160);">Thank you for submitting your undergraduate Nursing application.</strong></p><p><br></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">If any additional information is needed to complete your BSN application, the School of Nursing will request it from you. Please contact the School of Nursing at </span><a href="mailto:nursing@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255);">nursing@stthomas.edu</a><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> with any of your BSN application questions.</span></p>','','ApplicationHome','Submitted App;Complete App;File Hold','','','','','','','','','','','','Submitted Graphic: UG View (UGBSN)','','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
