INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-235','Active','Common App','','','<p><strong style="font-size: 18px; color: rgb(131, 72, 173);">Application review complete</strong></p><p><br></p><p>The admissions committee has completed its review of your application. Please contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/index.html" target="_blank">admissions counselor</a> for more information about your admissions decision.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Denied','','','','','','','','','','','','Graphic: UG Denied (UGFRCA)','','UGDeniedUGFR','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
