INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-245','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Office of Graduate Admissions</span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">1000 LaSalle Avenue</span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">TMH 201 Box 5</span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">Minneapolis, MN 55403</span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">Phone: (651) 962-6190</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">gradadmissions@stthomas.edu</a></p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration','','','','','','','','','','','','','Contact GradAdmissions General (SPSSD)','','Contact','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-246','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Application Checklist</strong></p><p><strong style="color: rgb(109, 54, 150); font-size: 18px;"></strong></p>','','ApplicationRequirement','','','','','','','','','','','','','Application Checklist (SPSSD)','','','<style>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-247','Active','','','Status: Accepted','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">What&#39;s next? Please complete your Intent to Enroll form to confirm your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Admit','','','','','','','','','','','','Graphic: GR Admit (SPSSD)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-10');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-248','Active','','','','<p><strong style="font-size: 16px; color: rgb(81, 12, 118);">Congratulations on your acceptance to the University of St. Thomas!</strong></p><p><br></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">We are excited to have you continue your educational journey at St. Thomas. There’s a lot of information we’d like to share with you, but below are the most important items to note moving forward.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">Confirming Deposit</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">To guarantee your place in the class you must submit a $50 confirming deposit, which allows you to register for classes when the time comes.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">On-Campus Housing</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">If you plan to live on campus, you must submit a $50 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. Your enrollment guide provides detailed information on how to complete the enrollment process online.</span></p><p><br></p><p><strong style="font-size: 14px;">Deposits for the fall term are refundable until August 15, 2025.  </strong></p><p><br></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">Your </span><strong style="font-size: 14px; color: rgb(255, 108, 0);">St. Thomas ID</strong><span style="font-size: 14px;"> is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">Scholarship and Financial Aid</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">Watch your mail for information about your St. Thomas scholarship. Students who complete the</span><strong style="font-size: 14px; color: rgb(109, 54, 150);"> </strong><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 14px;">Free Application for Federal Student Aid (FAFSA)</a><span style="font-size: 14px;"> or the </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 14px;">MN Dream Act</a><span style="font-size: 14px;"> will receive a comprehensive financial aid package. If you have any questions or concerns, please contact the Financial Aid Office at (651) 962-6550.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Spring 2025;Fall 2025','','','','','Graphic: UG Pre-Deposit Admit (UGTRDFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-6');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-249','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Excellence Scholarship</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit;Confirmed','','','','','','','Fall 2025','','','','','Excellence Scholarship Link (UGTRDFC)','','','<div class="USTline"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-250','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Featured links:</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Committee','','','','','','','','','','','','Feature Links (UGTR)','','UGTRFeaturedLinks','<div class="lineUST"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-251','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Welcome to the Transfer Application!</strong></p><p><br></p><p>Congratulations on taking your first step to becoming a Tommie. </p><p><br></p><p>Use the Application Portal above to follow the steps to submit your application. For questions, contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank">admissions counselor. </a></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App','','','','','','','Fall 2024','','','','','Graphic: UG Started App (UGTR)','','UGTRStarted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-252','Active','','','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">To complete the application process, you must:</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">Submit college transcripts from ALL schools and institutions you have attempted credits from – including PSEO or dual-enrollment credits and/or your Joint Services Transcript from the military. Unofficial transcripts will be accepted for the admission process, but official transcripts will be required if a student enrolls.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">A high school transcript is only required from transfer students who have completed fewer than 24 transferable college-level semester (36 quarter) credits after graduating from high school or receiving a High School Equivalency Diploma.</span></p><p><span style="color: rgb(0, 0, 0);">﻿</span></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">You may submit your transcripts by using the transcript upload feature located on the right-hand side of this page.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">If you have any questions, your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">admissions counselor</a><span style="font-size: 16px; color: rgb(43, 43, 43);"> is here to help as you navigate the application process.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Submitted App','','','','','','','','','','','','UG Submitted - Pre EDA (UGTR)','','UGTRSubmitted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-253','Active','','','','','','ApplicationHome','Admit','','','','','','','Spring 2025;Fall 2025','','','','','Admit Confetti Message With BUTTON (UGTR)','','','<div class="animation"><center>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-254','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Housing Preference Form</strong></p>','International;U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Fall 2025;Fall 2026','','','','','Housing Widget (UGTR)','','UGTRHousingWidget','<div class="line"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-255','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Saint Paul Seminary School of Divinity </span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">gradtheology@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Divinity (SPSSD)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-256','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Application Checklist</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending;Admit;File Hold;Second Review;Committee','','','','','','','Spring 2025;Fall 2025;Spring 2026;Fall 2026','','','','','Application Checklist for App Page (UGFR)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Application Checklist','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-257','Active','Common App','','Deferred','','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Deferred Admit','','','','','','','Spring 2024','','','','','Deferred Admit (UGFRCA)','','','','','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-8');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-258','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the St. Thomas community!</strong> </p><p><br></p><p><span style="font-size: 16px;">We are so excited to welcome you to campus this spring! </span></p><p><br></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">﻿Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/freshman/admitted-students/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Admitted Students website</a><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> for important upcoming dates and feel free to contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">admissions counselor</a><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> with any questions. </span></p><p><br></p><p><span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);">﻿Your </span><strong style="color: rgb(255, 108, 0); font-size: 16px; background-color: rgb(255, 255, 255);">St. Thomas ID</strong><strong style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);"> </strong><span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">If you completed the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a>,<span style="font-size: 16px;"> you will receive a comprehensive financial aid package. If you have questions about financial aid, reach out to your financial aid advisor or email financialaid@stthomas.edu. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Housing </strong></p><p><span style="font-size: 16px;">Residence Life will reach out to you about housing. All first-year students are required to live on campus, and you can find more details about this policy at the </span><a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank" style="font-size: 16px;">Two-Year On-Campus Living Requirement website</a><span style="font-size: 16px;">. Submitting a housing deposit verifies that you agree to the terms outlined in the Student Residence Agreement. This agreement can be found on the </span><a href="https://www.stthomas.edu/residence-life/" target="_blank" style="font-size: 16px;">Residence Life website</a><span style="font-size: 16px;">.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Orientation, Registration and Placement Assessments</strong></p><p><span style="font-size: 16px;">Academic Counseling will contact you about orientation and registration. You may need to complete placement assessments in some subjects. Placement assessments help make sure you register for the right classes when you begin at St. Thomas. If you have question about the placement assessment process, reach out to academiccounseling@stthomas.edu. </span></p><p><strong style="font-size: 22px; color: rgb(109, 54, 150);"> </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on making your college decision! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">We&#39;re so happy you&#39;ve chosen St. Thomas!</strong></p><p style="text-align: center;"><br></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2025','','','','','Graphic: UG Spring Confirmed FR (UGFR)','','UGConfirmedFRUGFR','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-259','Active','Common App','','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Important Dates for Spring Students</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending;Denied;Admit;Confirmed;File Hold','','','','','','','Spring 2024','','','','','Admissions Spring Dates (UGFRCA)','','AdmissionsSpringDatesUGFR','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-260','Active','Common App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">If you would like to be considered for need-based financial aid, please make sure to complete the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a> <span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);">if you have not yet done so</span><span style="font-size: 16px;">.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Fall 2025 Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Fall 2024','','','','','Enrollment Checklist (UGFRCA)','','EnrollmentChecklistUGFR','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-261','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the International Transfer Application!</strong></p><p><br></p><p>Thank you for beginning your application. <span style="color: rgb(68, 68, 68);">Use the Application Portal above to follow the steps to submit your application. For questions, contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a>. You can find more details on the <a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank">International Admissions website</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Application Timelines</strong></p><p><span style="color: rgb(68, 68, 68);">All international student applications are reviewed on a rolling basis. Admission decisions will generally be issued within two weeks of receiving a complete application.</span></p>','International','ApplicationHome','Started App','','','','','','','','','','','','Graphic: UG Started INTL (UGTRCAM)','','GraphicUGStartedNTLUGTRCAM','','2.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-262','Active','UST App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations on your acceptance </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">to the University of St. Thomas!</strong><span style="color: rgb(109, 54, 150); font-size: 20px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Keep an eye on your mailbox because you&#39;ll soon be receiving an enrollment guide that details the next steps of the enrollment process. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Confirming Deposit</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you&#39;ve decided to attend St. Thomas for </span><strong style="color: rgb(33, 33, 33); font-size: 16px;">fall 2024</strong><span style="color: rgb(33, 33, 33); font-size: 16px;">, a $200 confirming deposit reserves your spot in the class. </span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); font-size: 16px;">﻿Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Course Registration</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Fall registration will open for new transfer students in early May. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">On-Campus Housing</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you will be living on campus, you’re required to submit a $200 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. All incoming transfer students with fewer than two semesters of college are required to meet the on-campus residency requirement. More information on this policy and other important housing information can be found on Residence Life&#39;s webpage </span><a href="https://www.stthomas.edu/tr/visit/" target="_blank" style="color: rgb(29, 117, 204); font-size: 16px;"><u>for transfer students.</u></a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 12pt;">Admitted Student Website</strong><span style="color: rgb(109, 54, 150); font-size: 12pt;"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/admitted-students/index.html" target="_blank" style="color: rgb(29, 117, 204); font-size: 16px;"><u>transfer admitted students</u></a><span style="color: rgb(33, 33, 33); font-size: 16px;"> page to claim your St. Thomas account, activate your St. Thomas email address and learn about our deposit refund policies. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Fall 2024','','','','','Graphic: UG Admit (UGTRCAM)','','','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-263','Active','UST App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 15pt;">Congratulations on your acceptance to </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 15pt;">the University of St. Thomas!</strong><span style="color: rgb(109, 54, 150); font-size: 15pt;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px;">We are very pleased to welcome you to our community. You will be receiving an email containing your official admission letter and detailed instructions about your next steps.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">Your </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; background-color: rgb(255, 255, 255);"> </strong><span style="font-size: 16px; background-color: rgb(255, 255, 255);">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Confirming Deposit</strong><span style="font-size: 16px; color: rgb(109, 54, 150);"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px;">fall 2023</strong><span style="font-size: 16px;">, a $200 confirming deposit reserves your spot in the class. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255);">An additional $200 deposit puts you on the list for on-campus housing. To submit your deposit(s) you will need your St. Thomas ID.</span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;"> </span></p><p><span style="background-color: white; font-size: 16px;">Deposits for fall term are refundable until </span><strong style="font-size: 16px;">May 1, 2023</strong><span style="font-size: 16px;">.  </span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Depositing from outside the U.S.? </strong></p><p><span style="background-color: white; font-size: 16px;">If you are submitting your deposit from outside the U.S., </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">please submit your deposit</a><span style="font-size: 16px;"> through </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">Flywire.com</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; background-color: white;">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; background-color: white;">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/international-students/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: white;">documentation of financial support</a><span style="font-size: 16px; background-color: white;">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">Qualify for your I-20 here</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><span style="font-size: 16px;">If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Course Registration</strong><span style="font-size: 16px; color: rgb(109, 54, 150);"> </span></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Fall registration will open for new transfer students in early May. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="background-color: white; font-size: 16px;">Also feel free to reach out to one of our </span><a href="https://stthomas.edu/admissions/international-students/student-ambassadors/index.html#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="background-color: white; font-size: 16px;">International Student Ambassadors</a><span style="background-color: white; font-size: 16px;"> to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','','','','','','Graphic: UG Admit INTL (UGTRCAM)','','UGAdmitINTLUGTRCAM','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-264','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p><br></p><p>Thank you for all your hard work getting everything in.</p><p> </p><p>St. Thomas accepts transfer students on a rolling basis for both the fall and spring semesters. Usually, you’ll hear back from us within 2-3 weeks of submitting all required documents.</p><p> </p><p>Questions? Contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor" target="_blank">admissions counselor</a>. They’d love to hear from you!</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Complete App;Pending;File Hold;Second Review;Committee','','','','','','','','','','','','Graphic: UG Complete (UGTRCAM)','','UGTRCAMGraphicUGComplete','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
