INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-272','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Welcome to the Transfer Application!</strong></p><p><br></p><p>Now that you have started your application, you’ve taken your first step to becoming a Tommie. We’re pretty excited about that, and we hope you are too!  </p><p><br></p><p>Use the Application Portal above to follow the steps to submit your application. For questions, contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank">admissions counselor. </a></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App','','','','','','','Fall 2024','','','','','Graphic: UG Started App (UGTRCAM)','','UGTRCAMStarted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-273','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="font-size: 16px;">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="font-size: 16px;">admissions counselor</a><span style="font-size: 16px;"> is here to help as you navigate the application process. Contact them to ask any questions.</span></p><p><br></p><p><span style="font-size: 16px;">To complete the application process, you must send high school and college transcripts from all institutions you have attended, and complete the </span><a href="https://www.stthomas.edu/_media-library/_documents/main/stthomas-ens-code-of-conduct-form.pdf" target="_blank" style="font-size: 16px;">Code of Conduct Form</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. You may submit an unofficial transcript by downloading it from your school system and sending it to </span><a href="mailto:admissions@stthomas.edu" target="_blank" style="font-size: 16px;">admissions@stthomas.edu</a><span style="font-size: 16px;"> or your admissions counselor. Official transcripts will be required before the start of the term.</span></p><p><br></p><p><a href="https://www.stthomas.edu/_media-library/_documents/main/stthomas-ens-code-of-conduct-form.pdf" target="_blank" style="font-size: 16px;">Click Here </a><span style="font-size: 16px;">for a copy of the</span><a href="https://www.stthomas.edu/_media-library/_documents/main/stthomas-ens-code-of-conduct-form.pdf" target="_blank" style="font-size: 16px;"> Code of Conduct Form</a><span style="font-size: 16px;">.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Submitted App','','','','','','','','','','','','UG Submitted - Pre EDA (UGTRCAM)','','UGTRCAMSubmitted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-274','Active','UST App','','','<p><strong style="font-size: 18px; color: rgb(131, 72, 173);">Application Review Complete</strong></p><p><br></p><p>The admissions committee has completed its review of your application. Please contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor/index.html" target="_blank">transfer counselor</a> for more information about your admissions decision.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Denied','','','','','','','','','','','','Graphic: UG Denied (UGTRCAM)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
