INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-277','Active','UST App','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">Continue to watch your personal email and St. Thomas email for more information. In the meantime, please don’t hesitate to contact your transfer counselor with any questions you may have.</span></p><p><br></p><p><span style="font-size: 16px;">Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Course Registration</strong></p><p><span style="font-size: 16px;">Fall registration will open for new transfer students in early May. Information will be sent via email from the Academic Counseling office regarding that process.</span></p><p style="text-align: center;"><br></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! We’re so happy you&#39;ve chosen </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">St. Thomas!</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Fall 2024','','','','','Graphic: UG Confirmed (UGTRCAM)','','','<div class="USTLine"></div>
