INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-281','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="color: rgb(68, 68, 68); font-size: 16px;">Missing documents can also be mailed to:</span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas.</span></p>','International','ApplicationHome','Started App;Submitted App;Temporary Hold','','','','','','','','','','','','Submit Missing Docs INTL (UGTRCAM)','','UGTRCAMSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-282','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="color: rgb(37, 36, 35); font-size: 16px;">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="color: rgb(91, 95, 199); font-size: 16px; background-color: rgb(255, 255, 255);">admissions counselor</a><span style="color: rgb(37, 36, 35); font-size: 16px;"> is here to help as you navigate the application process. Contact them to ask any questions.</span></p>','International','ApplicationHome','Submitted App;Temporary Hold','','','','','','','','','','','','UG Submitted INTL (UGTRCAM)','','UGTRCAMSubmittedINTL','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-283','Active','UST App','','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Fall Transfer Timeline</strong></p>','','ApplicationHome','Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Committee','','','','','','','Fall 2024','','','','','Admissions Decisions Dates-NoSlide (UGTRCAM)','','UGTRCAMAdmissionsDecisionsDates','<style>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-284','Active','UST App','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the St. Thomas community!</strong></p><p> </p><p><span style="font-size: 16px;">Now that you’re officially going to be a Tommie, you should join the </span><a href="https://www.facebook.com/groups/476437757778704/?ref=share&amp;mibextid=S66gvF" target="_blank" style="font-size: 16px;">Class of 2027 Facebook page</a><span style="font-size: 16px;"> so you can connect with your future classmates and friends. </span></p><p><br></p><p><span style="font-size: 16px;">Feel free to reach out to one of our </span><a href="https://www.stthomas.edu/oiss/firststeps/ambassadors/#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">International Student Ambassadors</a><span style="font-size: 16px;"> to learn their perspectives of life at St. Thomas. </span></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Claim Your St. Thomas online account</strong></p><p><span style="font-size: 16px;">To claim your account, please visit </span><a href="https://accountclaim.stthomas.edu/" target="_blank" style="font-size: 16px;">Account Claim</a><span style="font-size: 16px;">. Be sure to set a strong password and set up two factor authentication using the Microsoft Authenticator App. </span><strong style="font-size: 16px;">Text message authentication WILL NOT work outside of the US.</strong><span style="font-size: 16px;"> Instructions to setting up two factor authentication can be found in the </span><a href="https://services.stthomas.edu/TDClient/1898/ClientPortal/KB/ArticleDet?ID=97640" target="_blank" style="font-size: 16px;">ITS Knowledge Base</a><span style="font-size: 16px;">.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Request your I-20 immigration document</strong></p><p><span style="font-size: 16px;">After you claim your account, you will need to log into the </span><a href="https://oiss.stthomas.edu/index.cfm?FuseAction=Security.AngLogin" target="_blank" style="font-size: 16px;">OISS Student Portal</a><span style="font-size: 16px;"> with your new St. Thomas login to complete your immigration profile and upload the necessary documents. Once we verify your request, we will issue your I-20. If you are not an F-1 student, please contact us to discuss your situation.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Check your St. Thomas email account daily </strong></p><p><span style="font-size: 16px;">Many important notices will be sent to your St. Thomas account before you arrive. Be sure to regularly check your emails.</span></p><p><br></p><p><span style="font-size: 16px;">In the meantime, contact international@stthomas.edu with any questions.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Wanting to learn more about St. Thomas?</strong></p><p><span style="font-size: 16px;">We are offering a number of </span><a href="https://www.stthomas.edu/admissions/undergraduate/campus-visits/index.html" target="_blank" style="font-size: 16px;">virtual visit</a><span style="font-size: 16px;"> options to bring campus to you!</span></p><p style="text-align: center;"><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Register for classes and sign up for an Orientation session</strong></p><p><br></p><p><span style="font-size: 16px;">If you have not yet done so, reach out to Academic Counseling to register for your classes. You can contact that department by emailing academiccounseling@stthomas.edu. </span></p>','International','ApplicationHome','Confirmed','','','','','','','','','','','','TR Enrollment Checklist INTL (UGTRCAM)','','','<head>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-285','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Spring Transfer Timeline</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Committee','','','','','','','Spring 2024','','','','','Spring - Admissions Decisions Dates-NoSlide (UGTRCAM)','','','<style>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-286','Active','UST App','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on your acceptance </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">to the University of St. Thomas!</strong><span style="font-size: 20px; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Keep an eye on your mailbox because you&#39;ll soon be receiving an enrollment guide that details the next steps of the enrollment process. </span></p><p><br></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Confirming Deposit</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px; color: rgb(33, 33, 33);">spring 2024</strong><span style="font-size: 16px; color: rgb(33, 33, 33);">, a $200 confirming deposit reserves your spot in the class. </span></p><p><br></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">﻿Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Course Registration</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">spring registration will open for incoming transfer students on November 28, 2023. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">On-Campus Housing</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you will be living on campus, you’re required to submit a $200 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. All incoming transfer students with fewer than two semesters of college are required to meet the on-campus residency requirement. More information on this policy and other important housing information can be found on Residence Life&#39;s webpage </span><a href="https://www.stthomas.edu/tr/visit/" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>for transfer students.</u></a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Admitted Student Website</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/admitted-students/index.html" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>transfer admitted students</u></a><span style="font-size: 16px; color: rgb(33, 33, 33);"> page to claim your St. Thomas account, activate your St. Thomas email address, and learn about our deposit refund policies. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit;Deferred Admit','','','','','','','Spring 2023;Spring 2024;Spring 2025','','','','','Spring - UG Admit (UGTRCAM)','','UGTRCAMPreDepositAdmit','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-287','Active','UST App','','','<p><span style="font-size: 16px;">Now that Fall 2023 classes have begun, please contact your admissions counselor if you have questions about enrollment.</span></p>','','ApplicationHome','Admit','','','','','','','Fall 2023','','','','','Graphic: UG Post-Term Start Admit (UGTRCAM)','','UGFRPreDepositAdmit','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-288','Active','UST App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">Continue to watch your personal email and St. Thomas email for more information. In the meantime, please don’t hesitate to contact your transfer counselor with any questions you may have.</span></p><p><br></p><p><span style="font-size: 16px;">Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Course Registration</strong></p><p><span style="font-size: 16px;">Spring registration will open for new transfer students on November 28, 2023. Information will be sent via email from the Academic Counseling office regarding that process.</span></p><p style="text-align: center;"><br></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! We’re so happy you&#39;ve chosen </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">St. Thomas!</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed;Deferred Confirmed','','','','','','','Spring 2024','','','','','Spring - UG TR Confirmed (UGTRCAM)','','','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-289','Active','UST App','','','<p style="text-align: center;"><strong style="font-size: 15pt; color: rgb(109, 54, 150);">Congratulations on your acceptance to </strong></p><p style="text-align: center;"><strong style="font-size: 15pt; color: rgb(109, 54, 150);">the University of St. Thomas!</strong><span style="font-size: 15pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px;">We are very pleased to welcome you to our community. You will be receiving an email containing your official admission letter and detailed instructions about your next steps.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="background-color: rgb(255, 255, 255); font-size: 16px;">Your </span><strong style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="background-color: rgb(255, 255, 255); font-size: 16px;"> </strong><span style="background-color: rgb(255, 255, 255); font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Confirming Deposit</strong><span style="color: rgb(109, 54, 150); font-size: 16px;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px; color: rgb(33, 33, 33);">spring</strong><strong style="font-size: 16px;"> 2024</strong><span style="font-size: 16px;">, a $200 confirming deposit reserves your spot in the class. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255);">An additional $200 deposit puts you on the list for on-campus housing. To submit your deposit(s) you will need your St. Thomas ID.</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);"> </span></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);"> </span></p><p><span style="font-size: 16px; background-color: white;">Deposits for spring term are refundable until </span><strong style="font-size: 16px; background-color: white;">February 2</strong><strong style="font-size: 16px;">, 2024</strong><span style="font-size: 16px;">.  </span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Depositing from outside the U.S.? </strong></p><p><span style="font-size: 16px; background-color: white;">If you are submitting your deposit from outside the U.S., </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">please submit your deposit</a><span style="font-size: 16px;"> through </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">Flywire.com</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; background-color: white;">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; background-color: white;">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/international-students/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: white;">documentation of financial support</a><span style="font-size: 16px; background-color: white;">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">Qualify for your I-20 here</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><span style="font-size: 16px;">If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Course Registration</strong><span style="color: rgb(109, 54, 150); font-size: 16px;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Spring registration will open for new transfer students on November 28, 2023. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="font-size: 16px; background-color: white;">Also feel free to reach out to one of our </span><a href="https://stthomas.edu/admissions/international-students/student-ambassadors/index.html#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="font-size: 16px; background-color: white;">International Student Ambassadors</a><span style="font-size: 16px; background-color: white;"> to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','Spring 2024','','','','','Spring: UG Admit INTL (UGTRCAM)','','UGAdmitINTLUGTRCAM','<div class="USTLine"></div>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-290','Active','UST App','','','','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit;Confirmed','','','','','','','','','','','','Financial Aid Filedrop (UGTRCAM)','','UGFRFinancialAidFiledrop','<p style="color:#5f19a0;" font-size: 200px;><b>Secure Financial Aid Document Upload</b></p> </br>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-291','Active','UST App','','','<p style="text-align: center;"><strong style="font-size: 22px; color: rgb(109, 54, 150);">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="font-size: 22px; color: rgb(109, 54, 150);">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68);"> is {{Banner ID}}</strong><strong style="font-size: 16px;">.</strong><span style="font-size: 16px;"> Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Financial Aid</strong></p><p><span style="font-size: 16px;">If you would like to be considered for need-based financial aid, please make sure to complete the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a> <span style="font-size: 16px;">if you have not yet done so.</span></p><p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Spring Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Enrollment Checklist Spring (UGTRCAM)','','','<head>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-292','Active','UST App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> is {{Banner ID}}</strong><span style="font-size: 16px;">. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; color: rgb(68, 68, 68);">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; color: rgb(68, 68, 68);">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">documentation of financial support</a><span style="font-size: 16px; color: rgb(68, 68, 68);">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/admitted-students/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Qualify for your I-20 here</a><span style="font-size: 16px; color: rgb(68, 68, 68);">.</span></p><p><br></p><p><span style="font-size: 16px;"> If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><br></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px;">international@stthomas.edu</a><span style="font-size: 16px;"> regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','International','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Enrollment Checklist Spring INTL (UGTRCAM)','','','<head>
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-293','Active','Common App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Application Checklist</strong></p>','','ApplicationHome','Started App;Complete App;Pending;Denied;Admit;Confirmed;Withdrawn;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Do Not Contact;Enrolled;Committee;Temporary Hold','','','','','','','','','','','','Application Checklist for App Page - CommonApp(UGTRCAM)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Application Checklist','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-294','Active','Common App','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Your Transfer Common App application is loading</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Thanks for bearing with us while we load in your Transfer Common App application. You will see it the application in your Admissions Home Page shortly. </span></p>','','ApplicationHome','Started App;Submitted App','','','','','','','','','','','','Application is Loading Msg (UGTRCAM)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-295','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p><br></p><p><span style="font-size: 16px;">Thanks for all your hard work getting everything in.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Now you’re probably wondering when you’ll hear back from us with a decision. Check the Admissions Decision Timeline information.</span></p><p><br></p><p><span style="font-size: 16px;">Please be advised that if you are admitted, you may still need to submit additional documentation to qualify for your student visa. You can find more details about these requirements on the </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank" style="font-size: 16px;">International Admissions website</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">Questions? Contact us at </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px;">international@stthomas.edu</a><span style="font-size: 16px;">. We&#39;d love to hear from you!</span></p>','International','ApplicationHome','Complete App;File Hold','','','','','','','','','','','','Graphic: UG Complete INTL (UGTRCAM)','','UGCompleteINTLUGTRCAM','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-296','Active','','','','<p><strong style="color: rgb(131, 72, 173); font-size: 18px;">Initial Application Review Complete</strong></p><p><br></p><p>The admissions committee has completed its initial review of your application. Please contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/index.html" target="_blank">admissions counselor</a> for more information.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','File Hold','','','','','','','','','','','','Graphic: UG File Hold (UGFR)','','UGFRGraphicUGComplete','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-297','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Spring Transfer Timeline</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Deferred Admit;Deferred Confirmed;Committee','','','','','','','Spring 2025','','','','','Spring - Admissions Decisions Dates-NoSlide (UGTR)','','','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-298','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(0, 0, 0);">The Fall 2024 Dougherty Family College Application is now closed. If you are interested in applying for Fall 2025, please start a new application.</strong></p>','','ApplicationHome','Started App;Submitted App;Admit;File Hold','','','','','','','Fall 2024','','','','','Timeline Text: Application Closed (DFC)','','','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-299','Active','','','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Missing Documents</strong></p><p><span style="font-size: 10.5pt; font-family: inherit;">Your application is almost complete, but we are still missing some materials. You can submit your missing documents to </span><a href="mailto:admissons@stthomas.edu" target="_blank" style="font-size: 10.5pt; color: rgb(1, 118, 211); font-family: inherit;">admissions@stthomas.edu</a><span style="font-size: 10.5pt; font-family: inherit;">.</span></p><p><em style="font-size: 10.5pt; font-family: inherit;">Please note:</em><span style="font-size: 10.5pt; font-family: inherit;"> it may take a few weeks for your document(s) to be processed and your portal to reflect that we&#39;ve received it.</span></p><p><br></p><p><span style="color: rgb(0, 0, 0);">{{documents_missing}}</span></p><p><em style="font-family: inherit; background-color: rgb(255, 255, 255); font-size: 10.5pt;">﻿If no items are listed, all application requirements are received.</em></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Submitted App','','','','','','','','','','','','Documents Missing (UGTR)','','','','3.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-300','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on your acceptance </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">to the University of St. Thomas!</strong><span style="font-size: 20px; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Keep an eye on your mailbox for an enrollment guide that details the next steps of the enrollment process. </span></p><p><br></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Confirming Deposit</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you&#39;ve decided to attend St. Thomas for spring 2025, submit a $200 deposit to reserve your spot in the class. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255);">Select &quot;Submit Deposit&quot; above to get started.</span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Course Registration</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Spring registration is now open. Information will be sent via email from our Academic Counseling office. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">On-Campus Housing</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you will be living on campus, you’re required to submit a $200 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. All incoming transfer students with fewer than two semesters of college are required to meet the on-campus residency requirement. More information on this policy and other important housing information can be found on Residence Life&#39;s webpage </span><a href="https://www.stthomas.edu/tr/visit/" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>for transfer students.</u></a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Admitted Student Website</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/admitted-students/index.html" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>transfer admitted students</u></a><span style="font-size: 16px; color: rgb(33, 33, 33);"> page to claim your St. Thomas account, activate your St. Thomas email address and learn about our deposit refund policies. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit;Deferred Admit','','','','','','','Spring 2023;Spring 2024;Spring 2025','','','','','Spring - UG Admit (UGTR)','','UGTRPreDepositAdmit','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-301','Active','','','','','','ApplicationPortal','System Admin','','','','','','','','','','','','Application List (UGTRCAM)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','List of Applications','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-302','Active','','','','<p style="text-align: center;"><strong style="font-size: 18px; color: rgb(109, 54, 150);">Loading your Transfer Common App</strong></p><p><br></p><p>Thank you for your patience as we load your Transfer Common App application to the University of St. Thomas. During this time, your portal may look a little different and you may lose access to existing applications for a short period of time.</p><p><br></p><p>Once we&#39;ve loaded all of your information, you&#39;ll receive an email confirming the submission of your Transfer Common App application to St. Thomas and your portal will return to normal.</p><p><br></p><p>If you have any questions, please feel free to contact us at <a href="mailto:admissions@stthomas.edu" target="_blank">admissions@stthomas.edu</a></p>','','ApplicationPortal','Started App','','','','','','','','','','','','Loading TR Common App (UGTRCAM)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-303','Active','','','','<p style="text-align: center;"><strong style="font-size: 15pt; color: rgb(109, 54, 150);">Congratulations on your acceptance to </strong></p><p style="text-align: center;"><strong style="font-size: 15pt; color: rgb(109, 54, 150);">the University of St. Thomas!</strong><span style="font-size: 15pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px;">We are very pleased to welcome you to our community. You will be receiving an email containing your official admission letter and detailed instructions about your next steps.</span></p><p><span style="font-size: 16px;"> </span></p><p><span style="background-color: rgb(255, 255, 255); font-size: 16px;">Your </span><strong style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="background-color: rgb(255, 255, 255); font-size: 16px;"> </strong><span style="background-color: rgb(255, 255, 255); font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Confirming Deposit</strong><span style="color: rgb(109, 54, 150); font-size: 16px;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px; color: rgb(33, 33, 33);">spring</strong><strong style="font-size: 16px;"> 2025</strong><span style="font-size: 16px;">, a $200 confirming deposit reserves your spot in the class. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255);">An additional $200 deposit puts you on the list for on-campus housing. To submit your deposit(s) you will need your St. Thomas ID.</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);"> </span></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);"> </span></p><p><span style="font-size: 16px; background-color: white;">Deposits for spring term are refundable until </span><strong style="font-size: 16px; background-color: white;">January 31</strong><strong style="font-size: 16px;">, 2025</strong><span style="font-size: 16px;">.  </span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Depositing from outside the U.S.? </strong></p><p><span style="font-size: 16px; background-color: white;">If you are submitting your deposit from outside the U.S., </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">please submit your deposit</a><span style="font-size: 16px;"> through </span><a href="https://payment.flywire.com/pay/payment" target="_blank" style="font-size: 16px;">Flywire.com</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; background-color: white;">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; background-color: white;">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/international-students/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: white;">documentation of financial support</a><span style="font-size: 16px; background-color: white;">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">Qualify for your I-20 here</a><span style="font-size: 16px;">.</span></p><p><span style="font-size: 10pt;"> </span></p><p><span style="font-size: 16px;">If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Claim Your St. Thomas online account</strong></p><p><span style="font-size: 16px;">To claim your account, please visit </span><a href="https://accountclaim.stthomas.edu/" target="_blank" style="font-size: 16px;">Account Claim</a><span style="font-size: 16px;">. Be sure to set a strong password and set up two factor authentication using the Microsoft Authenticator App. </span><strong style="font-size: 16px;">Text message authentication WILL NOT work outside of the US.</strong><span style="font-size: 16px;"> Instructions to setting up two factor authentication can be found in the </span><a href="https://services.stthomas.edu/TDClient/1898/ClientPortal/KB/ArticleDet?ID=97640" target="_blank" style="font-size: 16px;">ITS Knowledge Base</a><span style="font-size: 16px;">.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Course Registration</strong><span style="color: rgb(109, 54, 150); font-size: 16px;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Spring registration will open for new transfer students on November 26, 2024. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes. </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="font-size: 16px; background-color: white;">Also feel free to reach out to one of our </span><a href="https://stthomas.edu/admissions/international-students/student-ambassadors/index.html#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="font-size: 16px; background-color: white;">International Student Ambassadors</a><span style="font-size: 16px; background-color: white;"> to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','Spring 2025','','','','','Spring: UG Admit INTL (UGTR)','','UGAdmitINTLUGTR','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-304','Active','','','','','','ApplicationRegistration','','','','','','','','','','','','','Common App returning Sign in (UGCA)','','','','','','','Right','Central Daylight Time (America/Chicago)','User Info Login/Logout','Application_Control__c-23');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-305','Active','','','','','','ApplicationPortal','Started App','','','','','','','','','','','','Pre-Checklist Text BETA (Francis) (GSOE)','','Pre-Checklist','<div class="animated-text" style="text-align:left;">INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-306','Active','','','','','','ApplicationPortal','Started App','','','','','','','','','','','','Pre-Checklist Text BETA (Francis) (GSON)','','Pre-Checklist','<div class="animated-text" style="text-align:left;">INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-307','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">Continue to watch your email for more information. In the meantime, please don’t hesitate to contact your transfer counselor with any questions you may have.</span></p><p><br></p><p><span style="font-size: 16px;">Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Course Registration</strong></p><p><span style="font-size: 16px;">Fall registration will open for new Transition DFC students in April. Information will be sent via email from Academic Counseling regarding this process.</span></p><p style="text-align: center;"><br></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! We’re so happy you&#39;ve chosen to continue your educational journey at</strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">St. Thomas!</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','','','','','','Graphic: UG Confirmed (UGTRDFC)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-308','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact College of Arts &amp; Sciences </strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif;">MA in Diversity Leadership</span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">Phone: (651) 962-6001</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">diversityleadership@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','AS_DV_MA|MADL','','','','','','','','Contact Grad MADL (GCAS)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-309','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations on your acceptance to the </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">University of St. Thomas!</strong><span style="color: rgb(109, 54, 150);"> </span></p><p style="text-align: center;"><span style="color: rgb(131, 72, 173);"> </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Interested in Enrolling? </strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie! </span><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">﻿Your</span><span style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);"> </span><strong style="font-size: 16px; color: rgb(255, 108, 0); background-color: rgb(255, 255, 255);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);"> </strong><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">is {{Banner_Id}}.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">All students are required to submit a $400 deposit to reserve their place in the class. </strong><span style="font-size: 16px; color: rgb(0, 0, 0);"> </span></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Since</span><span style="font-size: 16px;"> </span><a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank" style="font-size: 16px;">all first-year students are required to live on campus</a><span style="font-size: 16px;">, </span><span style="font-size: 16px; color: rgb(0, 0, 0);">this deposit also reserves your place in on-campus housing. The date you submit it is one of many factors that determine your housing placement.  </span></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Half ($200) of the deposit will be applied to your housing bill at the beginning of the term. If you’re allowed an exception from our on-campus living requirement, it will instead be applied to your tuition charges. The remaining $200 will be applied to other student fees.  </span></p><p><br></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">﻿Deposits for fall term are refundable until </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">January 31, 2025</strong><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">.  </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Depositing from outside the U.S.? </strong></p><p><span style="color: rgb(0, 0, 0); font-size: 16px; background-color: rgb(255, 255, 255);">If you are submitting your deposit from outside the U.S., please</span><span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);"> s</span><a href="http://stthomas.flywire.com/" target="_blank" style="font-size: 16px;">ubmit your deposit</a> <span style="color: rgb(0, 0, 0); font-size: 16px; background-color: rgb(255, 255, 255);">through</span><span style="color: rgb(68, 68, 68); font-size: 16px; background-color: rgb(255, 255, 255);"> </span><a href="https://flywire.com/" target="_blank" style="font-size: 16px;">Flywire.com</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Required Documents</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">After submitting your deposit, you can request your </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">I-20 immigration document</strong><span style="font-size: 16px; color: rgb(0, 0, 0);">. This is </span><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">necessary to obtain a student visa. </span><span style="font-size: 16px; color: rgb(0, 0, 0);">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">documentation of financial support</a><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">, </span><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">and in some cases, additional items may be required.</span><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/admitted-students/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Qualify for your I-20 here</a><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);"> If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><span style="color: rgb(0, 0, 0);">﻿</span></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">If your visa is denied after the deadline, contact international@stthomas.edu regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank" style="font-size: 16px;">website</a> <span style="font-size: 16px;">for admitted international students to </span><span style="font-size: 16px; color: rgb(0, 0, 0);">answer your questions, provide important dates and walk through all the appropriate next steps. </span></p><p><br></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">Also feel free to reach out to one of our</span><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> </span><a href="https://www.stthomas.edu/oiss/firststeps/ambassadors/#_ga=2.67596946.2018286306.1606749321-1377687405.1583181377" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">International Student Ambassadors</a><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> </span><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);">to learn their perspectives of life at St. Thomas. </span></p>','International','ApplicationHome','Admit','','','','','','','Spring 2025','','','','','Graphic: UG Spring Admit INTL (UGFR)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-310','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Documents Missing</strong></p><p><em style="color: rgb(5, 5, 5); font-size: 14px;">Please note: It may take a few days for your document(s) to be processed and your application to reflect that we’ve received it.</em></p><p><em style="color: rgb(5, 5, 5); font-size: 14px;">If no items are listed below, all application requirements are received.</em></p><p><span style="color: rgb(0, 0, 0);">{{documents_missing}}</span></p>','','ApplicationHome','Submitted App;Pending;Admit;File Hold;Committee','','','','','','','','','','','','Documents Missing Submitted (GCAS)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-15');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-311','Active','','','','<p><span style="font-size: 16px;">Now that Fall 2023 classes have begun, please contact your admissions counselor if you have questions about enrollment.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','','','','','','Graphic: UG Post-Term Start Admit (UGFRCA)','','UGFRPreDepositAdmit','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-312','Active','','','','<p><span style="font-size: 16px;">Now that Fall 2024 classes have begun, please contact your admissions counselor if you have questions about enrollment.</span></p>','','ApplicationHome','Admit','','','','','','','Fall 2024','','','','','Graphic: UG Post-Term Start Admit (UGFR)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-313','Active','','','','<p style="text-align: center;"><strong style="color: rgb(112, 48, 160); font-size: 20px;">Welcome to the DFC Pre-STEM Concentration Application!</strong></p><p><br></p><p><span style="font-size: 16px;">In order to start your application, please click the &quot;Sign In&quot; button under </span><strong style="font-size: 16px;">Account</strong><span style="font-size: 16px;"> to log in using your existing St. Thomas admissions account.</span></p><p><br></p><p><em style="color: rgb(43, 43, 43); font-size: 16px;">Questions? </em><span style="color: rgb(43, 43, 43); font-size: 16px;">Contact the DFC Pre-STEM Concentration program at </span><a href="mailto:DFC-PreSTEM@stthomas.edu" target="_blank" style="font-size: 16px;">DFC-PreSTEM@stthomas.edu</a>.</p>','','ApplicationRegistration','','','','','','','','','','','','','Login Instructions (DFCSTEM)','','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-314','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Office of International Students and Scholars</strong></p>','International','ApplicationHome','Started App;Submitted App;Complete App;File Hold','','','','','','','','','','','','Graduate OISS (GOCB)','','','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-315','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Contact for Non-Degree Enrollment</strong></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); font-size: 14px;">Office of Student Data and Registrar</span></p><p><a href="mailto:registrar@stthomas.edu" target="_blank">registrar@stthomas.edu</a></p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Admissions w/ Social Links (UGNDO)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-316','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Thank you for submitting your non-degree enrollment form to St. Thomas!</strong></p><p><br></p><p>We are excited you are here! Be sure to provide additional information we need in order to complete your form.</p><ul><li><span style="color: rgb(68, 68, 68);">Send unofficial or official transcript from the most recent institution you attended or are currently attending to </span><a href="mailto:registrar@stthomas.edu" target="_blank" style="color: rgb(68, 68, 68);">registrar@stthomas.edu</a><span style="color: rgb(68, 68, 68);">.</span></li><li><span style="color: rgb(68, 68, 68);">If you are in high school, the School Administrator Statement of Support (if you haven&#39;t already submitted it).</span></li><li><span style="color: rgb(68, 68, 68);">If you are under 18, the Parent Consent Form (if you haven&#39;t already submitted it).</span></li></ul>','','ApplicationHome','Submitted App','','','','','','','','','','','','UG Submitted App (UGNDO)','','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-317','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your</span><span style="font-size: 16px; color: rgb(0, 0, 0);"> </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68);"> </strong><span style="font-size: 16px; color: rgb(68, 68, 68);">is</span><strong style="font-size: 16px; color: rgb(68, 68, 68);"> {{Banner ID}}</strong><strong style="font-size: 16px;">.</strong><span style="font-size: 16px;"> Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">If you would like to be considered for need-based financial aid, please make sure to complete the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a> <span style="font-size: 16px;">if you have not yet done so.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Spring Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2025;Spring 2026','','','','','Enrollment Checklist Spring (UGFR)','','EnrollmentChecklistUGFR','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-318','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Fall Transition Timeline</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Started App;Submitted App;Complete App;Pending;Admit;Confirmed;File Hold;Second Review;Committee','','','','','','','','','','','','Admissions Decisions Dates-NoSlide (UGTRDFCR)','','','<style>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-319','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on your acceptance to the </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">University of St. Thomas!</strong><span style="color: rgb(109, 54, 150);"> </span></p><p style="text-align: center;"><span style="color: rgb(131, 72, 173);"> </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Interested in Enrolling? </strong></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><br></p><p><strong style="font-size: 16px;">All students are required to submit a $400 deposit to reserve their place in the class. </strong><span style="font-size: 16px;"> </span></p><p><br></p><p><span style="font-size: 16px;">Since </span><a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank" style="font-size: 16px;">all first-year students are required to live on campus</a><span style="font-size: 16px;">, this deposit also reserves your place in on-campus housing. The date you submit it is one of many factors that determine your housing placement.  </span></p><p><br></p><p><span style="font-size: 16px;">Half ($200) of the deposit will be applied to your housing bill at the beginning of the term. If you’re allowed an exception from our on-campus living requirement, it will instead be applied to your tuition charges. The remaining $200 will be applied to other student fees.  </span></p><p><br></p><p><span style="font-size: 16px;">Deposits for spring term are refundable until </span><strong style="font-size: 16px;">February 2, 2024</strong><span style="font-size: 16px;">.  </span></p><p><br></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;">﻿Your </span><strong style="color: rgb(255, 108, 0); background-color: rgb(255, 255, 255); font-size: 16px;">St. Thomas ID</strong><strong style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;"> </strong><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;">is {{Banner_Id}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Scholarship and Financial Aid</strong></p><p><span style="font-size: 16px;">Watch your mail for information about your </span><a href="https://www.stthomas.edu/admissions/undergraduate/financial-aid/scholarships/future-students/index.html" target="_blank" style="font-size: 16px;">St. Thomas scholarship</a><span style="font-size: 16px;">. Students who completed the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or the </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a><span style="font-size: 16px;"> will receive a comprehensive financial aid package. If you have any questions or concerns, please contact the Financial Aid Office at (651) 962-6550.</span></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);"> </strong></p><p><strong style="color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/freshman/admitted-students/" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;"> for admitted students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Spring 2024','','','','','Spring UG Pre-Deposit Admit-CA (UGFRCA)','','UGFRPreDepositAdmit','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-320','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on your acceptance to the </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">University of St. Thomas!</strong><span style="color: rgb(109, 54, 150);"> </span></p><p style="text-align: center;"><span style="color: rgb(131, 72, 173);"> </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Interested in Enrolling? </strong></p><p><span style="font-size: 16px;">Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><br></p><p><strong style="font-size: 16px;">All students are required to submit a $400 deposit to reserve their place in the class. </strong><span style="font-size: 16px;"> </span></p><p><br></p><p><span style="font-size: 16px;">Since </span><a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank" style="font-size: 16px;">all first-year students are required to live on campus</a><span style="font-size: 16px;">, this deposit also reserves your place in on-campus housing. The date you submit it is one of many factors that determine your housing placement.  </span></p><p><br></p><p><span style="font-size: 16px;">Half ($200) of the deposit will be applied to your housing bill at the beginning of the term. If you’re allowed an exception from our on-campus living requirement, it will instead be applied to your tuition charges. The remaining $200 will be applied to other student fees.  </span></p><p><br></p><p><span style="font-size: 16px;">Deposits for spring term are refundable until </span><strong style="font-size: 16px;">January 31, 2025</strong><span style="font-size: 16px;">.  </span></p><p><br></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;">﻿Your </span><strong style="color: rgb(255, 108, 0); background-color: rgb(255, 255, 255); font-size: 16px;">St. Thomas ID</strong><strong style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;"> </strong><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;">is {{Banner_Id}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Scholarship and Financial Aid</strong></p><p><span style="font-size: 16px;">Watch your mail for information about your </span><a href="https://www.stthomas.edu/admissions/undergraduate/financial-aid/scholarships/future-students/index.html" target="_blank" style="font-size: 16px;">St. Thomas scholarship</a><span style="font-size: 16px;">. Students who completed the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or the </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a><span style="font-size: 16px;"> will receive a comprehensive financial aid package. If you have any questions or concerns, please contact the Financial Aid Office at (651) 962-6550.</span></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);"> </strong></p><p><strong style="color: rgb(109, 54, 150);">Admitted Student Website</strong></p><p><span style="font-size: 16px;">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/freshman/admitted-students/" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;"> for admitted students to answer your questions, provide important dates and walk through all the appropriate next steps. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Spring 2025;Spring 2026','','','','','Spring UG Pre-Deposit Admit (UGFR)','','UGFRPreDepositAdmit','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-321','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact College of Arts &amp; Sciences</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif;">Graduate Programs in Catholic Studies</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif;">Phone: (651) 962-5713</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204); font-family: truenolight, Arial, sans-serif; background-color: rgb(255, 255, 255);">gradcath@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','AS_CS_MA|CATH;AS_CS_NDO|NDCS;AS_CS_CER|MCCE','','','','','','','','Contact Grad Cath Studies (GCAS)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-322','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Contact College of Arts &amp; Sciences </strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; color: rgb(33, 33, 33); font-size: 16px;">Graduate Programs in Art History</span></p><p><span style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(33, 33, 33);">Phone: (651) 962-5560</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255); color: rgb(29, 117, 204); font-family: truenolight, Arial, sans-serif; font-size: 16px;">arthistory@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','AS_AH_MA|ARTH;AS_AH_NDO|NDAH;AS_AH_CER|AHCT;AS_AH_CER|MSCT','','','','','','','','Contact Grad Art Hist & Museum  (GCAS)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-323','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Contact College of Arts &amp; Sciences </strong></p><p><br></p><p><span style="color: rgb(33, 33, 33); font-size: 16px;">Graduate Programs in English</span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Phone: (651) 962-5628</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255); color: rgb(29, 117, 204); font-family: truenolight, Arial, sans-serif; font-size: 16px;">gradenglish@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','AS_EN_MA|ENGL;AS_EN_MA|GECW;AS_EN_NDO|GECW;AS_EN_NDO|NDEN;AS_EN_CER|ENCT','','','','','','','','Contact Grad English  (GCAS)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-324','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Contact College of Arts &amp; Sciences </strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; color: rgb(33, 33, 33); font-size: 16px;">Graduate Programs in Music</span></p><p><span style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(33, 33, 33);">Phone: (651) 962-5850</span></p><p><a href="mailto:gra