INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-363','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">DFC Pre-STEM Concentration Timeline</strong></p><p><br></p><ul><li><strong style="font-size: 16px;">August 12:</strong><span style="font-size: 16px;"> Application deadline </span></li><li><strong style="font-size: 16px;">Early August</strong><span style="font-size: 16px;">: Program acceptance decision shared with students </span></li><li><strong style="font-size: 16px;">Late August:</strong><span style="font-size: 16px;"> Student confirmation of Pre-STEM Concentration participation ﻿</span></li></ul>','','ApplicationHome','','','','','','','','','','','','','Application Timeline (DFCSTEM)','','','','11.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-364','Active','','','Status: Submitted-Action Required','<p style="text-align: center;"><strong style="color: rgb(112, 48, 160); font-size: 20px;">Complete required online Math Assessment</strong></p><p><br></p><p><span style="color: rgb(43, 43, 43); font-size: 16px;">Thank you for submitting your DFC Pre-STEM Concentration application. Your application </span><em style="color: rgb(43, 43, 43); font-size: 16px;">will not </em><span style="color: rgb(43, 43, 43); font-size: 16px;">be considered Complete</span><span style="font-size: 16px;"> and ready for review until you have also completed the required Math Assessment.</span></p><p><br></p><p><span style="font-size: 16px;">More information about preparing for your math assessment can be found in the &quot;</span><a href="/Admissions/applicationrequirement?at=DFCSTEM&amp;requirementId=a2gHq00000AWDGuIAP" target="_blank" style="font-size: 16px;">Required: Math Assessment</a><span style="font-size: 16px;">&quot; link in your application below.</span></p><p><br></p><p><em style="color: rgb(43, 43, 43); font-size: 16px;">Questions?</em><span style="color: rgb(43, 43, 43); font-size: 16px;"> Contact the DFC Pre-STEM Concentration program at </span><a href="mailto:DFC-PreSTEM@stthomas.edu" target="_blank" style="font-size: 16px;">DFC-PreSTEM@stthomas.edu</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Submitted App','','','','','','','','','','','','Submitted App Action Required (DFCSTEM)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-365','Active','','','','','','ApplicationHome','Admit','','','','','','','','','','','','Admit Confetti Message with BUTTON (DFCSTEM)','','','<div class="animation"><center>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-366','Active','','','','<p><strong style="background-color: rgb(255, 255, 255); color: rgb(109, 54, 150); font-size: 18px;">Congratulations on your acceptance into the Susan S. Morrison School of Nursing at the University of St. Thomas! </strong></p><p><br></p><p><span style="font-size: 14px;">This is an exciting milestone in your journey to becoming a nurse, and we are thrilled to welcome you to our community as part of the fall 2025 freshman class. </span><span style="font-size: 11pt;">To confirm you</span><span style="font-size: 14px;">r place in t</span><span style="font-size: 11pt;">he nursing cohort, simply submit your deposit to officially join the St. Thomas Class of 2029. Once your deposit is received, your direct admission to the nursing program will be fully confirmed.</span></p>','','ApplicationHome','Admit','','','','','','','Fall 2025','','','Direct Admit - Admit','','Nursing Direct Admit - Admit w/ Admit Status (UGFR)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-367','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150); background-color: rgb(255, 255, 255);">Thank you for applying Direct Admission to the Susan S. Morrison School of Nursing at the University of St. Thomas.</strong></p><p><br></p><p>While your application did not meet the criteria for Direct Admission into the BSN program, we’re thrilled to welcome you as a fully admitted student to St. Thomas, where you’ll begin your academic journey in fall 2025.</p><p><br></p><p>You may apply to the BSN program through the General Admission Pathway after completion of your first semester at St. Thomas.</p>','','ApplicationHome','Admit;Confirmed','','','','','','','Fall 2025','','','Direct Admit - Denied','','Nursing Direct Admit - Denied (UGFR)','','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-368','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Deadline has passed</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Thanks for your interest! However, the application deadline for fall 2025 admission to the Doctorate in Counseling Psychology program has passed. If you are interested in applying for fall 2026 admission, the application will open on October 15, 2025.</span></p>','','ApplicationPortal;ApplicationHome','Started App','','','','PS_GR_PSD|CPSY','','','Fall 2025','','','','','Started: Fall 2025 PsyD Missed Deadline (GSPP)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-17');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-369','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Deadline has passed</strong></p><p><br></p><p><span style="color: rgb(0, 0, 0); font-size: 16px;">Thanks for your interest! </span><span style="color: rgb(0, 0, 0); font-size: 16px;">However, the application deadline for fall 2025 admission to the Master of Arts with Direct Admission to the Doctorate in Counseling Psychology program has passed. If you are interested in applying for fall 2026 admission, the application will open on October 15, 2025. *Applications for fall 2025 admission are still open for the </span><strong style="color: rgb(0, 0, 0); font-size: 16px;">Master of Arts in Counseling Psychology </strong><span style="color: rgb(0, 0, 0); font-size: 16px;">(due February 5, 2025). If you would like to be considered for the MA in Counseling Psychology for fall 2025, please contact: </span><a href="mailto:gradpsych@stthomas.edu" target="_blank" style="color: rgb(0, 120, 215); font-size: 16px;">gradpsych@stthomas.edu</a><span style="color: rgb(0, 0, 0); font-size: 16px;">.</span></p>','','ApplicationPortal;ApplicationHome','Started App','','','','PS_DA_MA|CPSY','','','Fall 2025','','','','','Started: Fall 2025 MA DA Missed Deadline (GSPP)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-17');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-370','Active','','','','<p><strong style="color: rgb(125, 4, 166); font-size: 18px;">Unofficial Transcript Upload</strong></p>','','ApplicationHome','Started App;Submitted App;Complete App;Pending','','','','','','','','','','','','Unofficial Transcript Upload (UGTR)','','UGTRTranscriptUpload','<div class="line"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-371','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact </strong></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">School of Nursing</strong></p><p><br></p><p><span style="color: rgb(43, 43, 43);">If you would like assistance in completing your application, please contact the School of Nursing at </span><a href="mailto:nursing@stthomas.edu" target="_blank">nursing@stthomas.edu</a>.</p>','','ApplicationCreate;ApplicationPortal;ApplicationRegistration;ApplicationHome','','','','','','','','','','','','','Contact School of Nursing (UGBSN)','','','','21.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-372','Active','Current Student','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">BSN Admissions Timeline</strong></p><ul><li><strong>Oct 1, 2024: </strong>Application opens</li><li><strong>Feb. 1, 2025:</strong> Application deadline</li><li><strong>End of March:</strong> <span style="font-family: inherit; color: inherit;">Admission decision sent</span></li></ul>','','ApplicationHome','','','','','','','','','','','','','Timeline Text: General BSN Admissions (UGBSN)','','','','22.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-373','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Missing Documents</strong></p><p><span style="font-family: inherit; font-size: 10.5pt;">Your application is almost complete, but we are still missing some materials. You can submit your missing documents to </span><a href="mailto:admissons@stthomas.edu" target="_blank" style="font-family: inherit; font-size: 10.5pt; color: rgb(1, 118, 211);">admissions@stthomas.edu</a><span style="font-family: inherit; font-size: 10.5pt;">.</span></p><p><em style="font-family: inherit; font-size: 10.5pt;">Please note:</em><span style="font-family: inherit; font-size: 10.5pt;"> it may take a few weeks for your document(s) to be processed and your portal to reflect that we&#39;ve received it.</span></p><p><br></p><p><span style="color: rgb(0, 0, 0);">{{documents_missing}}</span></p><p><em style="font-size: 10.5pt; background-color: rgb(255, 255, 255); font-family: inherit;">﻿If no items are listed, all application requirements are received.</em></p>','','ApplicationHome','Submitted App','','','','','','','','','','','','Documents Missing (DFC)','','','','3.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-374','Active','','','','<p>In order to log into your University of St. Thomas Admissions Portal to view your Common App submission, you must <strong>provide the following information <em>exactly </em>as it appears in your Common App account:</strong></p><ul><li>First Name</li><li>Last Name</li><li>Email</li><li>Common App ID</li></ul><p>If any of the information you provide is different than what you provided in your Common App, we will not be able to locate your University of St. Thomas Common App submission.</p><p><br></p><p><em>If you have an existing St. Thomas Application or have accessed your Admissions Portal befor</em>e, access your portal &amp; application(s) through the <a href="https://uofstthomasmn.my.site.com/Admissions/ApplicationLogin" target="_blank">Returning Applicants login</a>.</p><p><br></p><p>If you experience any issues claiming or accessing your Common App St. Thomas Portal, please contact us at admissions@stthomas.edu or call (651) 962-6150.</p>','','ApplicationRegistration','','','','','','','','','','','','','Common App Login Instructions (UGCA)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-23');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-375','Active','','','Schedule your writing assessment today!','<p><span style="color: rgb(36, 36, 36); font-size: 14.6667px;">The next step in your application to Dougherty Family College is to complete a brief writing assessment with our literacy specialist, Dr. Carla Gonzalez. This assessment is used to ensure that we have the support services in place that you may need to be successful at Dougherty Family College. </span></p><p><br></p><p><strong style="color: rgb(36, 36, 36); font-size: 14.6667px;">How to schedule</strong><span style="color: rgb(36, 36, 36); font-size: 14.6667px;">: Email Dr. Gonzalez at </span><a href="mailto:cjgonzalez@stthomas.edu" target="_blank" style="font-size: 14.6667px; background-color: rgb(255, 255, 255);">cjgonzalez@stthomas.edu</a>.</p><p><br></p><p><strong style="color: rgb(36, 36, 36); font-size: 14.6667px;"><em>Please note:</em></strong><span style="color: rgb(36, 36, 36); font-size: 14.6667px;"> you will NOT receive a decision on your application until you have completed this writing assessment, so it is important that you schedule your assessment as soon as possible.</span></p>','','ApplicationHome','File Hold','Writing Assessment','','','','','','','','','','','File Hold: Writing Assessment (DFC)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-376','Active','','','','<p><strong style="font-size: 14px; color: rgb(81, 12, 118);">Congratulations on your acceptance to the Bachelor’s program!</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">We are excited to have you continue your educational journey at St. Thomas. There’s a lot of information we’d like to share with you, but below are the most important items to note moving forward.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">Confirming Deposit</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">To guarantee your place in the class you must submit a $50 confirming deposit, which allows you to register for classes when the time comes.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">On-Campus Housing</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">If you plan to live on campus, you must submit a $50 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. Your enrollment guide provides detailed information on how to complete the enrollment process online.</span></p><p><br></p><p><strong style="font-size: 14px;">Deposits for the spring term are refundable until February 2, 2024.  </strong></p><p><br></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">Your </span><strong style="font-size: 14px; color: rgb(255, 108, 0);">St. Thomas ID</strong><span style="font-size: 14px;"> is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 14px; color: rgb(81, 12, 118);">Scholarship and Financial Aid</strong></p><p><span style="font-size: 14px; color: rgb(0, 0, 0);">Watch your mail for information about your St. Thomas scholarship. Students who complete the</span><strong style="font-size: 14px; color: rgb(109, 54, 150);"> </strong><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 14px;">Free Application for Federal Student Aid (FAFSA)</a><span style="font-size: 14px;"> or the </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 14px;">MN Dream Act</a><span style="font-size: 14px;"> will receive a comprehensive financial aid package. If you have any questions or concerns, please contact the Financial Aid Office at (651) 962-6550.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Admit','','','','','','','Spring 2024','','','','','Spring- UG Pre-Deposit Admit (UGTRDFC)','','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-6');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-377','Active','','','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">We have received your deposit. </strong></p><p><br></p><p><span style="font-size: 16px;">Continue to watch your personal email and St. Thomas email for more information. In the meantime, please don’t hesitate to contact your transfer counselor with any questions you may have.</span></p><p><br></p><p><span style="font-size: 16px;">Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px;"> </strong><span style="font-size: 16px;">is {{Banner ID}}. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Course Registration</strong></p><p><span style="font-size: 16px;">Spring registration is currently open. Information is sent via email from Academic Counseling regarding the registration process.</span></p><p style="text-align: center;"><br></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! We’re so happy you&#39;ve chosen to continue your education at</strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">St. Thomas!</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Spring- UG Confirmed (UGTRDFC)','','','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-378','Active','','','','<p><span style="font-size: 16px;">Now that Fall 2024 classes have begun, please contact your admissions counselor if you have questions about enrollment.</span></p>','','ApplicationHome','Admit','','','','','','','Fall 2024','','','','','Graphic: UG Post-Term Start Admit (UGTR)','','UGFRPreDepositAdmit','<div class="USTLine"></div>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-379','Active','Common App','','','<p><strong>Let me apply with the St. Thomas Application</strong></p><p> </p><p>You already have a started Common App application. </p><p><br></p><p>If you would like to apply with a St. Thomas application instead of the Common App, please complete this short <a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_8hNkRtnvKwg3NLU?AID={{Application_ID}}&amp;CID={{Contact_Id}}" target="_blank"><strong>form</strong></a>.</p>','','ApplicationHome','Started App','','','','','','','','','','','','Switch from CA to UST App Qualtrics (UGFR)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-380','Active','Transfer','','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">BSN Admissions Timeline</strong></p><ul><li><strong>Oct 1, 2024: </strong>Application opens</li><li><strong>March 1, 2025:</strong> Application deadline</li><li><strong>End of April:</strong> <span style="color: inherit; font-family: inherit;">Admission decision sent</span></li></ul>','','ApplicationHome','','','','','','','','','','','','','Timeline Text: Transfer BSN Admissions (UGBSN)','','','','22.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-381','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Graduate School of Engineering &amp; Software </span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">Phone: (651) 962-5500</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">gradengineering@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Engineering (GSOE)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-382','Active','','','Additional information required for your application!','<p><span style="color: rgb(43, 43, 43);">Our admissions committee has requested some additional academic information from you before they are able to review your application to Dougherty Family College. You should have received an email from our Associate Director of Admissions, Erica Embury, with more information on what you need to provide. Please review the email and respond directly to the email if you have any questions.</span></p><p><br></p><p><strong style="color: rgb(43, 43, 43);"><em>Please note:</em></strong><em style="color: rgb(43, 43, 43);"> </em><span style="color: rgb(43, 43, 43);">You will NOT receive an admission decision until you have submitted the requested additional academic information, so it is important that you submit it as soon as you have it.</span></p><p><br></p><p><span style="color: rgb(43, 43, 43);">If you have any questions, please contact Erica Embury at </span><a href="mailto:erica.embury@stthomas.edu" target="_blank" style="color: rgb(43, 43, 43);">erica.embury@stthomas.edu</a><span style="color: rgb(43, 43, 43);">.</span></p>','','ApplicationHome','File Hold','Grades','','','','','','','','','','','File Hold: Grades (DFC)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-4');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-383','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">School of Social Work</span></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Phone: (651) 962-6190</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">socialwork@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Social Work(GSSW)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-384','Active','UST App','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Application Checklist</strong></p>','','ApplicationHome','','','','','','','','Spring 2024;Fall 2024;Spring 2025;Fall 2025;Spring 2026;Fall 2026','','','','','Application Checklist for App Page (UGTR)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Application Checklist','Application_Control__c-2');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-385','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">The Graduate School of Professional Psychology</span></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Phone: (651) 962-6190</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">gradpsych@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Prof. Psych (GSPP)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-386','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Susan S. Morrison School of Nursing</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">nursing@stthomas.edu</a></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">﻿Phone: (651) 962-6190</span></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Nursing (GSON)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-387','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Graduate School of Law </span></p><p><span style="color: rgb(33, 33, 33); font-family: truenolight, Arial, sans-serif; font-size: 16px;">Phone: (651) 962-4895</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">lawschool@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Law (GLAW)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-388','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Business Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Opus College of Business</span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">ocbgradadmissions@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad OCB (GOCB)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-389','Active','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Contact Graduate Admissions</strong></p><p><br></p><p><span style="font-family: truenolight, Arial, sans-serif; font-size: 16px; color: rgb(33, 33, 33);">Graduate School of Education </span></p><p><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; font-family: truenolight, Arial, sans-serif; color: rgb(29, 117, 204); background-color: rgb(255, 255, 255);">soed-admissions@stthomas.edu</a></p>','','ApplicationRequirement;ApplicationHome','','','','','','','','','','','','','Contact Grad Education (GSOEd)','','','<body>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-390','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> </strong><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">is</span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> {{Banner ID}}</strong><span style="font-size: 16px;">. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; color: rgb(68, 68, 68);">necessary to obtain </span><span style="font-size: 16px; color: rgb(0, 0, 0);">a student visa. Further instructions will be provided after your deposit is received. You will be required to submit</span><span style="font-size: 16px; color: rgb(68, 68, 68);"> </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">documentation of financial support</a><span style="font-size: 16px; color: rgb(68, 68, 68);">, </span><span style="font-size: 16px; color: rgb(0, 0, 0);">and in some cases may require additional items.</span><span style="font-size: 16px; color: rgb(68, 68, 68);"> </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/admitted-students/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Qualify for your I-20 here</a><span style="font-size: 16px; color: rgb(68, 68, 68);">.</span></p><p><br></p><p><span style="font-size: 16px;"> If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><br></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px;">international@stthomas.edu</a><span style="font-size: 16px;"> </span><span style="font-size: 16px; color: rgb(0, 0, 0);">regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Enrollment Checklist</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">Please complete the items in order from top to bottom.</strong></p>','International','ApplicationHome','Confirmed','','','','','','','Spring 2025','','','','','Enrollment Checklist Spring INTL (UGFR)','','','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-391','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> is {{Banner ID}}</strong><span style="font-size: 16px;">. Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Required Documents</strong></p><p><span style="font-size: 16px;">After submitting your deposit, you can request your </span><strong style="font-size: 16px;">I-20 immigration document</strong><span style="font-size: 16px;">. This is </span><span style="font-size: 16px; color: rgb(68, 68, 68);">necessary to obtain a student visa. </span><span style="font-size: 16px;">Further instructions will be provided after your deposit is received. Y</span><span style="font-size: 16px; color: rgb(68, 68, 68);">ou will be required to submit </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/financial-requirements/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">documentation of financial support</a><span style="font-size: 16px; color: rgb(68, 68, 68);">, and in some cases may require additional items. </span><a href="https://www.stthomas.edu/admissions/undergraduate/international/admitted-students/index.html" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">Qualify for your I-20 here</a><span style="font-size: 16px; color: rgb(68, 68, 68);">.</span></p><p><br></p><p><span style="font-size: 16px;"> If you are not an F-1 student, please contact us to discuss your situation. </span></p><p><br></p><p><span style="font-size: 16px;">If your visa is denied after the deadline, contact </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px;">international@stthomas.edu</a><span style="font-size: 16px;"> regarding a refund. </span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','International','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Enrollment Checklist Spring INTL (UGTR)','','','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-392','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68);"> </strong><span style="font-size: 16px; color: rgb(68, 68, 68);">is </span><strong style="font-size: 16px; color: rgb(68, 68, 68);">{{Banner ID}}</strong><strong style="font-size: 16px;">.</strong><span style="font-size: 16px;"> Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">If you would like to be considered for need-based financial aid, please make sure to complete the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a> <span style="font-size: 16px;">if you have not yet done so.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Spring Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Enrollment Checklist Spring (UGTR)','','','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-393','Active','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">We have received your deposit. </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 22px;">﻿Welcome to the St. Thomas community!</strong></p><p><br></p><p><span style="font-size: 16px;">﻿Your</span><span style="font-size: 16px; color: rgb(0, 0, 0);"> </span><strong style="font-size: 16px; color: rgb(255, 108, 0);">St. Thomas ID</strong><strong style="font-size: 16px; color: rgb(68, 68, 68);"> </strong><span style="font-size: 16px; color: rgb(68, 68, 68);">is</span><strong style="font-size: 16px; color: rgb(68, 68, 68);"> {{Banner ID}}</strong><strong style="font-size: 16px;">.</strong><span style="font-size: 16px;"> Be sure to make note of your ID, as you will need to use it in the future.</span></p><p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Financial Aid</strong></p><p><span style="font-size: 16px;">If you would like to be considered for need-based financial aid, please make sure to complete the </span><a href="https://studentaid.gov/h/apply-for-aid/fafsa" target="_blank" style="font-size: 16px;">Free Application for Federal Student Aid</a><span style="font-size: 16px;"> (FAFSA) or </span><a href="https://www.ohe.state.mn.us/mPg.cfm?pageID=2065" target="_blank" style="font-size: 16px;">MN Dream Act</a> <span style="font-size: 16px;">if you have not yet done so.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Spring Enrollment Checklist</strong></p><p><span style="font-size: 16px;">Here are important steps you are required to complete as you prepare for fall semester at St. Thomas. Use the list below to track your progress. </span><strong style="font-size: 16px;">Please complete the items in order from top to bottom.</strong></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Confirmed','','','','','','','Spring 2024','','','','','Enrollment Checklist Spring (UGFR)','','EnrollmentChecklistUGFR','<head>INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-394','Active','','','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Your enrollment form is complete!</strong></p><p><br></p><p><span style="font-size: 14px; background-color: rgb(255, 255, 255);">Keep an eye on your email inbox, as you will be receiving an email regarding registration.</span></p>','','ApplicationHome','Complete App;Admit','','','','','','','','','','','','UG Complete and Admit (UGNDO)','','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
