INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-403','Active','','','Application review complete','<p><span style="font-size: 16px; color: rgb(43, 43, 43);">Thank you for your application to the DFC Pre-STEM Concentration. The program committee has completed its review of your application. Please check your email for your program decision.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(43, 43, 43);">If you have any questions, or if you have not received your decision, please contact the DFC Pre-STEM Concentration program at </span><a href="mailto:DFC-PreSTEM@stthomas.edu" target="_blank" style="font-size: 16px;">DFC-PreSTEM@stthomas.edu</a><span style="font-size: 16px;">.</span></p>','','ApplicationHome','Denied','','','','','','','','','','','','Denied App Program Decision (DFCSTEM)','','','','1.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-404','Active','','','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete!</strong></p><p> </p><p>St. Thomas accepts transfer students on a rolling basis. Fall application review traditionally begins in early January. </p><p> </p><p>Questions? Contact your <a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor" target="_blank">admissions counselor</a>. They’d love to hear from you!</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationHome','Complete App;Pending;File Hold;Second Review;Committee','','','','','','','Fall 2025','','','','','Fall: UG Complete (UGTR)','','UGTRGraphicUGComplete','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-2');
