INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-408','Active','','','','<p><strong style="background-color: rgb(255, 255, 255); color: rgb(109, 54, 150); font-size: 18px;">Congratulations on your acceptance into the Susan S. Morrison School of Nursing at the University of St. Thomas! </strong></p><p><br></p><p><span style="font-size: 14px;">This is an exciting milestone in your journey to becoming a nurse, and we are thrilled to welcome you to our community as part of the fall 2025 freshman class. </span><span style="font-size: 14.6667px;">Because you have already submitted your deposit, your direct admission to the nursing program is fully confirmed! Congratulations! </span></p>','','ApplicationHome','Confirmed','','','','','','','Fall 2025','','','Direct Admit - Admit;Direct Admit - Confirmed','','Nursing Direct Admit - Admit in Confirm Status (UGFR)','','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-5');
