INSERT INTO "Question__c" VALUES('Question__c-433','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent Text (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>I have reviewed each page of my application; I certify the information I have provided on this application and all other admission materials is complete, accurate and true to the best of my knowledge. <span style="color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-627');
