INSERT INTO "Question__c" VALUES('Question__c-625','true','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Changes Consent Text (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">I understand that once my application has been submitted it may not be altered; I will need to contact the Office of Undergraduate Admissions via email at </span><a href="mailto:admissions@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255);">admissions@stthomas.edu</a><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> to provide additional information or make changes (ex. address change). </span><span style="background-color: rgb(255, 255, 255); color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-682');
INSERT INTO "Question__c" VALUES('Question__c-626','true','','','','Started App;Submitted App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent (DFC)','Name','false','','','','','I Agree','','0124P0000003S9NQAU','','Started App','','','','','','','Requirement_Item__c-682');
INSERT INTO "Question__c" VALUES('Question__c-627','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent Text (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><br></p><p>I have reviewed each page of my application; I certify the information I have provided on this application and all other admission materials are complete, accurate and true to the best of my knowledge. <span style="color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-682');
INSERT INTO "Question__c" VALUES('Question__c-628','true','','','','Started App;Submitted App','','','','false','','','','','10.0','false','true','Started App','false','','','','','','','','','','','false','','','','','EOE Statement (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><br></p><p><br></p><p><strong style="color: rgb(81, 35, 115);">The University of St. Thomas is an equal opportunity educator and employer. St. Thomas does not unlawfully discriminate, in any of its programs or activities, on the basis of race, color, creed, religion, national origin, sex, sexual orientation, family status, disability, age, marital status, status with regard to public assistance, membership or activity in a local commission, genetic information or any other characteristic protected by applicable law. </strong><a href="http://www.stthomas.edu/eostatement" target="_blank"><strong>http://www.stthomas.edu/eostatement</strong></a></p><p><br></p><p><strong style="color: rgb(81, 35, 115);">The University of St. Thomas is registered with the Minnesota Office of Higher Education pursuant to sections 136A.61 to 136A.71. Registration is not an endorsement of the institution. Credits earned at the institution may not transfer to all other institutions. Contact information for the Minnesota Office of Higher Education is: 1450 Energy Park Drive, Suite 350 St. Paul, MN 55108-5227 Phone: (651) 642-0567 Toll Free: (800) 657-3866 Fax: (651) 642-0675 </strong><a href="https://www.ohe.state.mn.us/" target="_blank"><strong>https://www.ohe.state.mn.us/</strong></a></p>','','','','Requirement_Item__c-682');
INSERT INTO "Question__c" VALUES('Question__c-629','true','','','','Started App;Submitted App','','','','false','','','','','20.0','false','true','Started App','false','','','','','','','','','','Please type your name in the space above.','false','Student Signature','','','','Student Signature (DFC)','Name','false','','','','','','Full Name','0124P0000003S9RQAU','','Started App','','','','','','','Requirement_Item__c-682');
INSERT INTO "Question__c" VALUES('Question__c-630','true','','','','','','','','false','','','','','5.0','false','true','','false','','','','','','','','','','','false','Offer of Admission Consent','','','','Offer of Admission Consent Static (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="color: rgb(43, 43, 43);">I understand that an offer of admission from the University of St. Thomas is contingent upon successful completion of all secondary school coursework and/or college level coursework at a level similar to the work evidenced in the application, successfully clearing a prior discipline and criminal/delinquency history review (if required) and the applicant continuing to meet admission standards and expectations, as determined by St. Thomas in its sole discretion. In addition, applicants are expected to comply with the St. Thomas Student Conduct Code, Convictions, and other applicable St. Thomas policies governing student conduct. St. Thomas may rescind its offer of admission or take other action if an applicant or admitted student fails to meet the aforementioned conditions and/or engages in conduct inconsistent with these expectations. Admitted students must update St. Thomas regarding any material changes in the information submitted during the application process, including academic standing and/or disciplinary history, and must submit a final copy of their secondary school (if required) and/or post-secondary transcript for approval prior to registering for their second semester of courses at St. Thomas.</span></p>','','','','Requirement_Item__c-682');
