INSERT INTO "Question__c" VALUES('Question__c-1067','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Dean''s Scholarship Static (GOCB)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(107, 54, 150); font-size: 16px;">Dean&#39;s Scholarship</strong></p><p><br></p><p>Merit-based scholarships are available to select candidates with strong applications. All applicants are automatically considered for the Dean’s Scholarship. No separate essay is required.</p>','','','','Requirement_Item__c-559');
