INSERT INTO "Question__c" VALUES('Question__c-1537','true','','','','Started App;Submitted App','','','','false','Doctoral','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','Scholarship Information','','','','Scholarship Information (GSSW)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">Barbara W. Shank Scholarship</strong></p><p><br></p><p>Please indicate if you would like to be reviewed for the Barbara W. Shank scholarship based on the criteria outlined below.</p><p><br></p><p>Meet one or more of the following three criteria, with preference given to students who meet all criteria:</p><p><br></p><ul><li>Have experience living in a community with a majority North American Indigenous population.</li></ul><p><br></p><ul><li>Have a demonstrated knowledge of the history, culture or language of one or more North American Indigenous nations.</li></ul><p><br></p><ul><li>Have demonstrated experience in or commitment to working with North American Indigenous peoples.</li></ul>','','','','Requirement_Item__c-479');
INSERT INTO "Question__c" VALUES('Question__c-1538','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','Non-Degree MSW Info (GSSW)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="color: #000000;">In order to enroll in a Master of Social Work course as a <strong>non-degree student</strong> </span><span style="color: #000000;">for credit, the following application is required. Once it is submitted and required transcripts are received, and if space is available, you will be registered. Confirmation of your enrollment, as well as information regarding campus maps, student services, where to buy books, parking permits and how to obtain a student ID card will be sent after you are registered in a course. An account will be assigned, which will allow access to the student information system at the University of St. Thomas where you can obtain class schedules, grades, and billing information via Murphy Online.</span></p>
