INSERT INTO "Question__c" VALUES('Question__c-2071','true','','','','Started App;Submitted App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','','','','','GPME Scholarship (GCAS)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><br></p><p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Graduate Programs in Music Education Scholarship</strong></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">For Graduate Programs in Music Education scholarship information, please </span><a href="https://cas.stthomas.edu/departments/areas-of-study/music/" target="_blank" style="font-size: 16px; color: rgb(0, 0, 0);">click here</a><span style="font-size: 16px; color: rgb(0, 0, 0);"> to visit our website. Completed applications are due on or before </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">April 1</strong><span style="font-size: 16px; color: rgb(0, 0, 0);"> of the current year. Notifications will be processed by </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">May 1</strong><span style="font-size: 16px; color: rgb(0, 0, 0);">.  </span></p>','','','','Requirement_Item__c-765');
INSERT INTO "Question__c" VALUES('Question__c-2072','true','','','','Started App;Submitted App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','','','','','FAFSA (GCAS)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">FAFSA </strong></p><p><br></p><p><span style="color: rgb(0, 0, 0); font-size: 16px; background-color: rgb(255, 255, 255);">The first step to receiving financial aid is to complete a Free Application for Federal Student Aid (FAFSA). The FAFSA collects information required to determine whether you qualify for financial aid and how much you are eligible to receive. </span><a href="https://www.stthomas.edu/financialaid/graduate/" target="_blank" style="color: rgb(64, 156, 218); font-size: 16px; background-color: rgb(255, 255, 255);"><u>Click here</u></a><span style="color: rgb(0, 0, 0); font-size: 16px; background-color: rgb(255, 255, 255);"> to visit Graduate Financial Services for details.</span></p>','','','','Requirement_Item__c-765');
