INSERT INTO "Question__c" VALUES('Question__c-2967','true','','','','','','','','false','','','','','0.0','false','true','','false','LW_GR_LLM|LACO;LW_GR_MSL|LMCO;LW_GR_MSLO|LMCO','','','','','','','','','','false','Did you learn about the University of St. Thomas from any of the following sources or individuals? Check all that apply.','','','','Source (GLAW)','Name','false','','','','','GoogleINSERT INTO "Question__c" VALUES('Question__c-2968','true','','','','','','','','false','','','','','1.0','false','true','','false','LW_GR_LLM|LACO;LW_GR_MSL|LMCO;LW_GR_MSLO|LMCO','','','','','','','','','','false','Other source','','','','Other source (GLAW)','Name','false','','','','','','','0124P0000003S9RQAU','','','','','','','','','Requirement_Item__c-122');
INSERT INTO "Question__c" VALUES('Question__c-2969','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','Non-Degree Applicants (SPSSD)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Non-degree-seeking students: Please select &quot;divinity&quot; as the program you are applying to.</p>','','','','Requirement_Item__c-198');
INSERT INTO "Question__c" VALUES('Question__c-2970','true','','','','','','','','false','','','','','23.0','false','true','','false','','','','','','','','','','','false','','','','','Static Instruct (GSSW)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><br></p><p><span style="font-size: 14px;">Thanks for answering the questions above. Please attach a separate letter providing feedback regarding the applicant&#39;s academic, professional, and personal characteristics including:</span></p><p><br></p><ul><li><span style="font-size: 14px;">Circumstances in which you are familiar with the applicant’s work, and the nature of the work that they performed</span></li><li><span style="font-size: 14px;">Applicant’s ability and demonstration for self-reflection, engagement, empathy, and respect for others</span></li><li><span style="font-size: 14px;">Their engagement as a learner and preparation for graduate education (if applicable)</span></li><li><span style="font-size: 14px;">And personal, professional, or educational-related experiences that will prepare the applicant for advanced social work practice; demonstrated experiences and examples are encouraged as they will help in determining the applicant’s fit with our program.</span></li></ul><p>Your letter is a critical component in the individual’s application package and will be used to help the admissions committee determine their fit with our MSW program and with the social work profession. We appreciate your sharing your experiences and impressions of this applicant with us. </p><p><br></p><p>File must be a MS Word (.doc or .docx), Rich Text Format (.rtf), Text (.txt) or PDF (.pdf) document, and not exceed 4 MB. Please be advised, PDF file format uploads are strongly recommended as other file formats may be altered during the upload process.</p><p><br></p>','','','','Requirement_Item__c-571');
