INSERT INTO "Question__c" VALUES('Question__c-3021','true','','','','Started App;Submitted App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','','','','','Message (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p style="text-align: center;"><strong style="font-size: 24px; color: rgb(109, 54, 150);">IMPORTANT NOTICE</strong></p><p><br></p><p><strong style="font-size: 18px; color: rgb(109, 54, 150);">If you chose to <em><u>Apply without Standardized Test</u></em> in the &quot;Testing (Optional)&quot; section, please click &quot;Save and Continue&quot; to complete this section, and move on to the next section.</strong></p><p><br></p><p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Otherwise, please click &quot;Next&quot; (If applicable) to self-report your ACT/SAT scores. </strong></p><p><br></p><p><br></p><p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Note: <em>You do not have to self-report your scores if you have not taken the ACT/SAT, but are planning to in the future. If this is the case, please add &quot;N/A&quot; on the record.</em></strong></p>','','','','Requirement_Item__c-89');
