INSERT INTO "Question__c" VALUES('Question__c-3247','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Confirming Deposit Question (DFC)','Name','false','','First_Year_Undergraduate_Deposit','DFC Confirming Deposit','Program Application Fee Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-152');
INSERT INTO "Question__c" VALUES('Question__c-3248','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Confirmation Deposit Enticement (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Take your next step to becoming a Tommie!</p><p><br></p><p><em style="color: rgb(43, 43, 43);">To reserve your place in the class you must submit a $50 confirming deposit as soon as possible. Space in the class is limited and will be awarded on a first come, first served basis. Deposits are refundable if requested in writing by May 1, 2025.</em></p><p><br></p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct expectations and fulfill admission obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li></ul>','','','','Requirement_Item__c-152');
INSERT INTO "Question__c" VALUES('Question__c-3249','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','Confirmation Deposit Received','','','','Confirmation Deposit Received (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="background-color: rgb(255, 255, 255); font-size: 14.6667px; color: rgb(36, 36, 36);">We’re excited to have you join our community of scholars and move one step closer to accomplishing your goals! We promise to be a community that welcomes, appreciates, supports, empowers and challenges you to be a morally responsible leader who thinks critically, acts wisely and works skillfully to advance the common good.</span></p>','','','','Requirement_Item__c-152');
