INSERT INTO "Question__c" VALUES('Question__c-3292','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Deposit Confirming (UGFR)','Name','false','400.0','First_Year_Undergraduate_Deposit','Confirming Deposit','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-157');
INSERT INTO "Question__c" VALUES('Question__c-3293','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Confirmation Deposit Enticement (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To reserve your place in the class and request your space in our residence halls you must submit a $400 confirming deposit.</em></p><p><em> </em></p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct expectations and fulfill admission obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>By submitting your $400 deposit, you are agreeing to the terms outlined in the Student Residence Agreement. This agreement can be found on the <a href="https://www.stthomas.edu/residence-life/policies-resources/index.html" target="_blank">Residence Life Website</a>.</li></ul><p>International students depositing from outside the U.S.?</p><ul><li>If you are submitting your deposit from outside the U.S., please <a href="https://pay.flywire.com/?utm_source=www&amp;utm_medium=referral&amp;utm_campaign=redirectio" target="_blank">submit your deposit</a> through Flywire.com and choose the University of St. Thomas (Minnesota).</li></ul>','','','','Requirement_Item__c-157');
INSERT INTO "Question__c" VALUES('Question__c-3294','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Confirmation Deposit Received (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas!</p>','','','','Requirement_Item__c-157');
INSERT INTO "Question__c" VALUES('Question__c-3295','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Deposit Confirming (Common App)','Name','false','400.0','First_Year_Undergraduate_Deposit','Confirming Deposit','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-158');
INSERT INTO "Question__c" VALUES('Question__c-3296','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Confirmation Deposit Enticement (Common App)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To reserve your place in the class and request your space in our residence halls you must submit a $400 confirming deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul>','','','','Requirement_Item__c-158');
INSERT INTO "Question__c" VALUES('Question__c-3297','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Confirmation Deposit Received (Common App)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas!</p>','','','','Requirement_Item__c-158');
INSERT INTO "Question__c" VALUES('Question__c-3298','true','','','','','','','','false','','','','','0.0','false','true','','false','','','','','','','','','','','false','','','','','Murray Institute Scholarship static (GSOEd)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 18px;">Murray Institute Scholarship</strong></p><p><br></p><p>The Murray Institute for Catholic Education is a collaboration between the University of St. Thomas and the Archdiocese of Saint Paul and Minneapolis. The Murray Institute’s mission is to support and sustain the educational ministries of the Archdiocese by providing graduate education for benefits-eligible educators of Catholic schools and parishes within the Archdiocese of Saint Paul and Minneapolis.</p><p><br></p><p>The Murray Institute supports graduate education for Murray-approved degrees at University of St. Thomas. The Murray Institute also supports Non-Degree Seeking applicants who wish to enroll in University of St. Thomas individual graduate courses not within a specific degree program.</p><p><br></p><p><strong style="font-family: truenoregular, Arial, sans-serif;">Eligibility</strong></p><p>To be eligible for Murray Institute funding, applicants shall:</p><ul><li>Employed through the Archdiocese of St. Paul and Minneapolis in educational ministries <em>(no minimum years of service required)</em>.</li><li>Hold a B.A. or B.S. degree from an accredited academic institution.</li><li>Undergraduate cumulative grade point average (GPA) of 3.0 (on a 4.0 scale).</li><li>Submit ALL official transcript(s) of all academic work, both undergraduate, transfer credits and graduate, if applicable.</li><li>Submit 2-3 letters of recommendation, depending on the program requirements, attesting to the applicant&#39;s ability to enter this program. (1) letter of recommendation must come from the applicant’s principal or pastor.</li><li>Commit to working within the Archdiocese of St. Paul and Minneapolis for the duration of the program and up to 3 years upon completion of the program. </li></ul><p><br></p>','','','','Requirement_Item__c-159');
INSERT INTO "Question__c" VALUES('Question__c-3299','true','','','Generic_Filter_3__c','Started App;Submitted App','','','','false','','','','','2.0','true','true','Started App','false','','','','','','','','','','','false','Do you confirm that you meet the eligibility criteria for the Murray Institute Scholarship?','','','','Confirm Eligibility (GSOEd)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-3300','true','','','','Started App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','','','','','Murray Institute Sch Message (GSOEd)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 24px;">IMPORTANT NOTICE</strong></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 18px;">If you chose &quot;no&quot; in the Murray Institute scholarship eligibility option, please click &quot;Save and Continue&quot; to complete this section, and move on to the next section.</strong></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Otherwise, please click &quot;Next&quot; (If applicable) to upload your required documents for the Murray Institute scholarship.</strong></p>','','','','Requirement_Item__c-160');
INSERT INTO "Question__c" VALUES('Question__c-3301','true','','','','','','','','false','','','','','0.0','false','true','','false','','','','','','','','','','','false','','','','','Murray Institute Scholarship static (SPSSD)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 18px;">Murray Institute Scholarship</strong></p><p><br></p><p>The Murray Institute for Catholic Education is a collaboration between the University of St. Thomas and the Archdiocese of Saint Paul and Minneapolis. The Murray Institute’s mission is to support and sustain the educational ministries of the Archdiocese by providing graduate education for benefits-eligible educators of Catholic schools and parishes within the Archdiocese of Saint Paul and Minneapolis.</p><p><br></p><p>The Murray Institute supports graduate education for Murray-approved degrees at University of St. Thomas. The Murray Institute also supports Non-Degree Seeking applicants who wish to enroll in University of St. Thomas individual graduate courses not within a specific degree program.</p><p><br></p><p><strong style="font-family: truenoregular, Arial, sans-serif;">Eligibility</strong></p><p>To be eligible for Murray Institute funding, applicants shall:</p><ul><li>Employed through the Archdiocese of St. Paul and Minneapolis in educational ministries <em>(no minimum years of service required)</em>.</li><li>Hold a B.A. or B.S. degree from an accredited academic institution.</li><li>Undergraduate cumulative grade point average (GPA) of 3.0 (on a 4.0 scale).</li><li>Submit ALL official transcript(s) of all academic work, both undergraduate, transfer credits and graduate, if applicable.</li><li>Submit 2-3 letters of recommendation, depending on the program requirements, attesting to the applicant&#39;s ability to enter this program. (1) letter of recommendation must come from the applicant’s principal or pastor.</li><li>Commit to working within the Archdiocese of St. Paul and Minneapolis for the duration of the program and up to 3 years upon completion of the program. </li></ul><p><br></p>','','','','Requirement_Item__c-161');
