INSERT INTO "Question__c" VALUES('Question__c-3345','true','','','','Started App;Submitted App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Request letter of Eligibility confirmation (GSOEd)','Name','false','','','','','','','0124P0000003S9SQAU','','Started App','','','','','','','Requirement_Item__c-214');
INSERT INTO "Question__c" VALUES('Question__c-3346','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Request letter of Eligibility form link (GSOEd)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">The Archdiocese of Saint Paul and Minneapolis and the University of St. Thomas are pleased to partner together to provide opportunities for advanced study to teachers serving in Catholic schools through the Murray Institute. Murray Institute programming is funded by generous donors to support quality and excellence in Catholic education in the Archdiocese of Saint Paul and Minneapolis. </span></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">To help ensure that Murray funds are used according to donor intent to support the needs of the Archdiocese of Saint Paul and Minneapolis, you must request a letter of eligibility</span><span style="font-size: 14px; background-color: rgb(255, 255, 255);"> &lt;</span><a href="https://catholiceducation.iad1.qualtrics.com/jfe/form/SV_1FjtcDT4AOPb8SF" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">REQUEST FORM HERE</a><span style="font-size: 14px; background-color: rgb(255, 255, 255);">&gt;</span><span style="font-size: 16px; background-color: rgb(255, 255, 255);"> from the Archdiocese of St. Paul and Minneapolis. In order to submit this application, please type &quot;Complete&quot; in the box below to confirm your request. </span><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-214');
INSERT INTO "Question__c" VALUES('Question__c-3347','true','','','Murray_Scholarship_Signature__c','Started App;Submitted App','','','','false','','','','','4.0','false','true','Started App','false','','','','','','','','','','','false','By initialing here, you agree to the above statement.','','','','Completion Statement Initials (GSOEd)','Name','false','','','','','','','0124P0000003S9RQAU','','Started App','','','','','','','Requirement_Item__c-214');
INSERT INTO "Question__c" VALUES('Question__c-3348','true','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Completion Static (GSOEd)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p>Murray Institute programs offer personal and professional growth through higher education at the University of St. Thomas for individual educators employed within the Archdiocese of St. Paul and Minneapolis. The education you receive is then, in turn, intended to enhance the communities you serve within Archdiocesan schools and parishes.</p><p>The Murray Institute requires applicants to maintain employment within the Archdiocese throughout the duration of the program and also requires a 3-year commitment working within a Catholic school or parish within the Archdiocese of St. Paul and Minneapolis upon completion of a Murray Institute program.</p><p><br></p><p>I agree to the above statement.</p>','','','','Requirement_Item__c-214');
INSERT INTO "Question__c" VALUES('Question__c-3349','true','','','Citizenship__c','','','','','false','','','','','1.0','true','true','','false','','','','','','','','','','','false','Please select the type of citizenship you currently hold:','','','','Citizenship (UGTRDFC)','Name','false','','','','','U.S. CitizenINSERT INTO "Question__c" VALUES('Question__c-3350','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Other Citizenship Confirm (UGTRDFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 14px;">You have selected Other as your citizenship status. </span><em style="font-size: 14px;">If you are coming to the US with a non-immigrant visa, including F-1 Student Visa, please update your response to International.</em></p>','','','','Requirement_Item__c-215');
INSERT INTO "Question__c" VALUES('Question__c-3351','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','Other Citizenship Static Text (UGTRDFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 14px;">Please share additional information in the field below. If you have DACA or Dreamer status, please specify. Note: All information shared will be treated as confidential and will be maintained separately from the application.</span></p>','','','','Requirement_Item__c-215');
INSERT INTO "Question__c" VALUES('Question__c-3352','true','','','','','','','','false','','','','','4.0','false','true','','false','','','','','','','','','','','false','Other Citizenship Information','','','','Other Citizenship Information (UGTRDFC)','Name','false','','','','','','','0124P0000003S9RQAU','','','','','','','','','Requirement_Item__c-215');
INSERT INTO "Question__c" VALUES('Question__c-3353','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Link to UG Apps (UGTRDFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(81, 12, 118); font-size: 16px;">You are applying to the University of St. Thomas&#39; Bachelor&#39;s Degree Program as a Dougherty Family College (DFC) Transition applicant.</strong></p><p> </p><p>DFC students are guaranteed admission to the bachelor’s degree program at the University of St. Thomas if they meet the eligibility requirements listed below: </p><p><br></p><p><strong style="color: rgb(255, 108, 0);">Admissions Eligibility Requirements:</strong></p><ul><li>Must have and maintain a minimum cumulative DFC GPA of 2.50</li><li>Must have a satisfactory disciplinary record with the university</li><li>Must earn their Associate of Arts degree from the DFC the spring prior to enrolling in the bachelor’s degree program at the University of St. Thomas</li></ul><p> </p><p><span style="color: rgb(68, 68, 68);">Click next to create your password and create your application.</span></p>','','','','Requirement_Item__c-216');
