INSERT INTO "Question__c" VALUES('Question__c-3465','false','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Challenging Situation Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 16px;">(1) Describe a challenging situation that required ingenuity or creativity to serve someone in need. How did you demonstrate resilience and a willingness to learn through the challenge?</span></p>','','','','Requirement_Item__c-270');
INSERT INTO "Question__c" VALUES('Question__c-3466','true','','','','Started App;Submitted App','','','','false','','','','','5.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Different Culture or Worldview Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p>Nursing is a person-centered profession that requires care, compassion, and engagement with people who are different from you. Please describe an experience with someone from a different culture, background, or social status who challenged you, and describe what you learned about yourself from this experience. </p>','','','','Requirement_Item__c-270');
