INSERT INTO "Question__c" VALUES('Question__c-3475','true','','','','Started App;Submitted App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','Have you already completed the above prerequisite courses with a grade of C- or higher and/or are currently enrolled in the course(s) for the Spring semester?','','','','Prerequisites Confirmation (UGBSN)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-3476','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent Text (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><br></p><p>I have reviewed each page of my application; I certify the information I have provided on this application and all other admission materials is complete, accurate and true to the best of my knowledge. <span style="color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-304');
INSERT INTO "Question__c" VALUES('Question__c-3477','true','','','','Started App;Submitted App','','','','false','','','','','10.0','false','true','Started App','false','','','','','','','','','','','false','','','','','EOE Statement (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><br></p><p><br></p><p><strong style="color: rgb(81, 35, 115);">The University of St. Thomas is an equal opportunity educator and employer. St. Thomas does not unlawfully discriminate, in any of its programs or activities, on the basis of race, color, creed, religion, national origin, sex, sexual orientation, family status, disability, age, marital status, status with regard to public assistance, membership or activity in a local commission, genetic information or any other characteristic protected by applicable law. </strong><a href="http://www.stthomas.edu/eostatement" target="_blank"><strong>http://www.stthomas.edu/eostatement</strong></a></p><p><br></p><p><strong style="color: rgb(81, 35, 115);">The University of St. Thomas is registered with the Minnesota Office of Higher Education pursuant to sections 136A.61 to 136A.71. Registration is not an endorsement of the institution. Credits earned at the institution may not transfer to all other institutions. Contact information for the Minnesota Office of Higher Education is: 1450 Energy Park Drive, Suite 350 St. Paul, MN 55108-5227 Phone: (651) 642-0567 Toll Free: (800) 657-3866 Fax: (651) 642-0675 </strong><a href="https://www.ohe.state.mn.us/" target="_blank"><strong>https://www.ohe.state.mn.us/</strong></a></p>','','','','Requirement_Item__c-304');
INSERT INTO "Question__c" VALUES('Question__c-3478','true','','','','Started App;Submitted App','','','','false','','','','','20.0','false','true','Started App','false','','','','','','','','','','Please type your name in the space above.','false','Student Signature','','','','Student Signature (UGBSN)','Name','false','','','','','','Full Name','0124P0000003S9RQAU','','Started App','','','','','','','Requirement_Item__c-304');
INSERT INTO "Question__c" VALUES('Question__c-3479','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Environmental Justice & Planetary Health Scholarship (GSSW))','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(0, 0, 0); font-size: 16px;">Environmental Justice &amp; Planetary Health Scholarship</strong></p><p><br></p><p><span style="color: rgb(10, 10, 10); font-size: 16.32px;">Please indicate if you would like to be reviewed for the Environmental Justice &amp; Planetary Health scholarship based on the criteria outlined below.</span></p><p><br></p><p><span style="font-size: 16px;">This grant will support students whose dissertation will focus on environmental justice and/or planetary health topics that intersect with social work education, or program/curriculum development or practice at any system level. This can include but is not limited to: environmental racism, Indigenous environmental practices or ways of knowing (sustainable communities, addressing Solastalgia, connection to the land), access to natural resources needed for survival, or other related environmental justice issues in which some communities are disproportionately impacted by environmental policy, degradation, hazards, or disasters.  </span></p>','','','','Requirement_Item__c-305');
