INSERT INTO "Question__c" VALUES('Question__c-3482','true','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','EJ Scholarship Static topic 400 words (GSSW)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px;">In no more than 400 words, identify the general topic you’re interested in pertaining to environmental justice and/or planetary health and why this is important. What question(s) might you seek to answer through your research? How does this relate to social work practice and/or social work education? </span></p>','','','','Requirement_Item__c-305');
