INSERT INTO "Question__c" VALUES('Question__c-3521','true','','','','Started App;Submitted App','','','','false','','','','','5.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Mentor RN Agreement Static','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px;">I understand that in order to serve as a volunteer mentor in the Susan S. Morrison School of Nursing, I must be a licensed RN. Should my license be temporarily suspended, revoked, or expire while serving as a mentor, I will contact the Student Success Director as soon as possible to determine if it is appropriate for me to continue to serve as a volunteer mentor. </span><span style="font-size: 16px; color: rgb(234, 0, 30);">*</span></p>','','','','Requirement_Item__c-350');
