INSERT INTO "Question__c" VALUES('Question__c-3543','true','','','','Started App;Submitted App','','','','false','','','','','4.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Changes Consent Text (UGNDO)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p>I understand that once my application has been submitted it may not be altered; I will need to contact the Office of Student Data and Registrar via email at <strong>registrar@stthomas.edu</strong> to provide additional information or make changes (ex. address change). <span style="color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-352');
