INSERT INTO "Question__c" VALUES('Question__c-3695','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','AP','','false','','','','','Self-report Score Option AP (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','hed__Test_Type__c','','','','<ol><li><span style="font-size: 16px;">Find the AP exam in the list, enter AP score and date of the exam, and then click “Add Record.” </span></li><li><span style="font-size: 16px;">Click “New Record” and repeat directions above until all AP scores have been entered.  </span></li><li><span style="font-size: 16px;">Click “Save and Continue” only after all AP exam scores have been entered. </span></li></ol><p><span style="font-size: 16px;">Important reminders:</span></p><ul><li><span style="font-size: 16px;">You will be prompted to report any pending AP scores in the Course Preference Form.  </span></li><li><span style="font-size: 16px;">Please remember to submit your official AP score to St. Thomas through the College Board. </span></li></ul><p><br></p>','','','','Requirement_Item__c-456');
