INSERT INTO "Question__c" VALUES('Question__c-3708','false','','','','Started App;Submitted App','','','','false','','','','','46.0','false','true','Started App','false','','','','','','','','','','','false','Based on the list of accepted options on our website listed above, which one did you already qualified for?','','','','English Proficiency answer (UGTR)','Name','false','','','','','From an Exempted Country (list above)INSERT INTO "Question__c" VALUES('Question__c-3709','true','','','','Started App;Submitted App','','','','false','','','','','2.0','false','true','Started App;Submitted App','false','','','','','','','','','','','false','School Administrator Statement of Support','','','','School Administrator Statement of Support (UGNDO)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 14px;">If you are in High School, please submit </span><a href="https://www.stthomas.edu/media/registrar/forms/Nondegree_SchoolAdmin_SupportStatement.pdf" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">Non-Degree School Administrator Statement of Support</a><span style="font-size: 14px;">. If you do not upload file now, you will be able to upload it after submitting the application.</span></p>','','','','Requirement_Item__c-398');
INSERT INTO "Question__c" VALUES('Question__c-3710','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','Applicant Parent Consent Form','','','','Non-Degree Applicant Parent Consent Form (UGNDO)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 14px;">If you are under 18 of age, please submit </span><a href="https://www.stthomas.edu/media/registrar/forms/Nondegree_ParentConsent.pdf" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">Non-Degree Parent Consent Form</a><span style="font-size: 14px;">.</span></p>','','','','Requirement_Item__c-400');
INSERT INTO "Question__c" VALUES('Question__c-3711','true','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Work and Learn/Residency Static (GSOEd)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 16px; font-family: Calibri, sans-serif; color: rgb(33, 33, 33);">If you are pursuing our Work and Learn program, or our Residency program (SUTR, Minneapolis Teacher Residency (MSTR), or Charter School Teacher Residency (ChTR), you have selected the wrong department and need to go back to the previous question and select “Work and Learn/Residency” as your department. That will then take you to the correct application for your specific program.</span></p>','','','','Requirement_Item__c-249');
INSERT INTO "Question__c" VALUES('Question__c-3712','true','','','','Started App;Submitted App','','','','false','','','','','4.0','false','true','','false','','','','','','','','','','','false','','','','','Music NDO Static (GCAS)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em style="color: rgb(0, 0, 0); font-family: Calibri, Arial, Helvetica, sans-serif; font-size: 16px;">If you wish to pursue the Kodály and/or Orff Schulwerk certificates, please select &quot;Non-Degree.&quot;</em></p><p><br></p><p><em style="color: rgb(0, 0, 0); font-family: Calibri, Helvetica, sans-serif; font-size: 16px;">To obtain graduate credit for workshops, please select &quot;Non-Degree.&quot;</em></p>','','','','Requirement_Item__c-373');
INSERT INTO "Question__c" VALUES('Question__c-3713','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','PreApp Static (GMSWA)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px;">Junior BSW students who meet the following eligibility requirements may apply for the early admission to the MSW program:</span></p><ul><li><span style="font-size: 16px;">Admitted to the BSW major without conditions</span></li><li><span style="font-size: 16px;">Cumulative GPA of 3.0 and Social Work GPA of 3.5, documented with a degree evaluation</span></li><li><span style="font-size: 16px;">In good academic and professional standing (see the Professional Standards in the BSW Handbook) in the BSW program (as confirmed by the BSW Program Director)</span></li><li><span style="font-size: 16px;">Completion of undergraduate degree in May of the following year</span></li></ul><p><br></p>','','','','Requirement_Item__c-407');
