INSERT INTO "Question__c" VALUES('Question__c-3748','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','HS Transcript Static Text (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','An official high school transcript is required to complete your application. Please contact <a href="mailto:admissions@stthomas.edu?subject=Transcript%20Question" target="_blank">admission</a>s if you have any questions or need more information. ','','','','Requirement_Item__c-634');
INSERT INTO "Question__c" VALUES('Question__c-3749','true','','','','','','','','false','','','','','1.0','false','true','','false','','','Select Deposit Type','','','','','','','','false','','','','','Confirmation Deposit Enticement (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To reserve your place in the class and request your space in our residence halls you must submit a confirming and housing deposit.</em></p><p><em> </em></p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct expectations and fulfill admission obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>By submitting your housing deposit, you are agreeing to the terms outlined in the Student Residence Agreement. This agreement can be found on the <a href="https://www.stthomas.edu/residence-life/policies-resources/index.html" target="_blank">Residence Life Website</a>.</li></ul><p>International students depositing from outside the U.S.?</p><ul><li>If you are submitting your deposit from outside the U.S., please <a href="https://pay.flywire.com/?utm_source=www&amp;utm_medium=referral&amp;utm_campaign=redirectio" target="_blank">submit your deposit</a> through <a href="https://flywire.com/" target="_blank">Flywire.com</a> and choose the University of St. Thomas (Minnesota).</li></ul>','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3750','true','','','','Admit','','','','false','','','','','6.0','false','true','','false','','','Select Deposit Type','','','','','','','','false','Click the Submit Deposit button below to proceed to our payment processing system.','','','','Deposit Confirming and Housing (UGTR)','Name','false','400.0','First_Year_Undergraduate_Deposit','ConfirmingHousing Deposit','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3751','true','','','','Admit','','','','false','','','','','3.0','true','true','','false','','','Select Deposit Type','','','','','','','','false','Please select the type of payment you''d like to make today.','','','','Payment Option Selection','Name','false','','','','','$200 Confirming DepositINSERT INTO "Question__c" VALUES('Question__c-3752','true','','','','Confirmed','','','','false','','','','','7.0','false','true','','false','','','Both Deposits Paid','','','','','','','','false','','','','','Confirmation Confirmation and Housing Deposit Received (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirmation and housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas!</p>','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3753','true','','','','Admit','','','','false','','','','','11.0','false','true','','false','','','Select Deposit Type','','','','','','','','false','Click the Submit Deposit button below to proceed to our payment processing system.','','','','Deposit Confirming Only (UGTR)','Name','false','200.0','First_Year_Undergraduate_Deposit','Confirming Deposit','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3754','true','','','','Admit','','','','false','','','','','23.0','false','true','','false','','','Housing Deposit Paid','','','','','','','','false','','','','','Housing Only Deposit Received (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your confirming deposit to lock in your spot!</p>','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3755','true','','','','Confirmed','','','','false','','','','','13.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Confirming Only Deposit Received (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirming deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your housing deposit if you plan to live on campus!</p>','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3756','true','','','','Admit','','','','false','','','','','21.0','false','true','','false','','','Select Deposit Type','','','','','','','','false','Click the Submit Deposit button below to proceed to our payment processing system.','','','','Deposit Housing Only (UGTR)','Name','false','200.0','First_Year_Undergraduate_Deposit','Housing Deposit','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-446');
INSERT INTO "Question__c" VALUES('Question__c-3757','true','','','','Confirmed','','','','false','','','','','1.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Second Deposit Housing Only Enticement (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To request your space in our residence halls you must submit a housing deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul><p>Click the Submit Deposit button below to proceed to our payment processing system.</p>','','','','Requirement_Item__c-447');
INSERT INTO "Question__c" VALUES('Question__c-3758','true','','','','Confirmed','','','','false','','','','','2.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Deposit Housing Only AFTER Confirming Deposit (UGTR)','Name','false','200.0','First_Year_Undergraduate_Deposit','2nd Deposit Housing','Custom Amount','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-447');
INSERT INTO "Question__c" VALUES('Question__c-3759','true','','','','Confirmed','','','','false','','','','','30.0','false','true','','false','','','Second Deposit Paid - Housing','','','','','','','','false','','','','','Second Deposit - Housing Only Deposit Received (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your housing deposit and requesting a spot in our residence halls!</p>','','','','Requirement_Item__c-447');
INSERT INTO "Question__c" VALUES('Question__c-3760','true','','','','Confirmed','','','','false','','','','','','false','true','','false','','','Second Deposit Paid - Confirming','','','','','','','','false','','','','','Second Deposit - Confirming Only Deposit Received (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your confirming deposit and reserving your spot at St. Thomas!</p>','','','','Requirement_Item__c-448');
INSERT INTO "Question__c" VALUES('Question__c-3761','true','','','','Admit','','','','false','','','','','1.0','false','true','','false','','','Both Deposits Paid','','','','','','','','false','','','','','Second Deposit Confirming Only Enticement (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>Thanks for you hosing deposit earlier. To reserve a spot in our upcoming class, you must submit a confirming deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul><p>Click the Submit Deposit button below to proceed to our payment processing system.</p>','','','','Requirement_Item__c-448');
