INSERT INTO "Question__c" VALUES('Question__c-3864','true','','','','Started App;Submitted App','','','','false','','','','','7.0','false','true','Started App','false','','','','','','','','','','','false','Have you completed a master''s level practicum or are you currently completing one?','','','','Previous Practicum (GSPP)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-3865','true','','','','','','','','false','','','','','8.0','false','true','','false','','','','','','','','','','','false','Please state the agency for which you will be completing (or have completed) your master’s level practicum:','','','','Previous Practicum- Yes (GSPP)','Name','false','','','','','','','0124P0000003S9RQAU','','','','','','','','','Requirement_Item__c-715');
INSERT INTO "Question__c" VALUES('Question__c-3866','true','','','','','','','','false','','','','','6.0','false','true','','false','','','','','','','','','','','false','','','','','Previous Degree- No (GSPP)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px; color: rgb(244, 8, 8);">You are not eligible to apply to a doctoral level program if you have not completed or are not currently completing a master&#39;s level degree in Counseling Psychology or a related field. Additional questions? Please contact Christina Holmgren at </span><a href="mailto:walk7281@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(241, 3, 3);">walk7281@stthomas.edu</a><span style="font-size: 16px; color: rgb(241, 3, 3);">.</span></p>','','','','Requirement_Item__c-715');
INSERT INTO "Question__c" VALUES('Question__c-3867','true','','','','','','','','false','','','','','9.0','false','true','','false','','','','','','','','','','','false','','','','','Previous Practicum- No (GSPP)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="color: rgb(244, 8, 8);">You are not eligible to apply to a doctoral level program if you have not completed or are not currently completing a master&#39;s level practicum. Additional questions? Please contact Christina Holmgren at walk7281@stthomas.edu. </span></p>','','','','Requirement_Item__c-715');
INSERT INTO "Question__c" VALUES('Question__c-3868','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','Visa Language Static (GCAS)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px; color: rgb(244, 7, 7);">Please note: International students will not qualify for F-1 status while pursuing the Masters in Diversity Leadership because the program is conducted entirely online. </span></p>','','','','Requirement_Item__c-373');
INSERT INTO "Question__c" VALUES('Question__c-3869','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','Prior UST Courses (GCAS)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em style="font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif; color: rgb(241, 3, 3);">If you have taken Graduate Music courses at St. Thomas within the past three years you do not need to complete this application. Please contact </em><a href="mailto:music@stthomas.edu" target="_blank" style="font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif; color: rgb(241, 3, 3);"><em>music@stthomas.edu</em></a><em style="font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif; color: rgb(241, 3, 3);"> for assistance registering for courses.</em></p>','','','','Requirement_Item__c-373');
