INSERT INTO "Question__c" VALUES('Question__c-3878','true','','','','Started App;Submitted App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Educational Withdrawal Explanation Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 14px;">Please list the institution(s) and briefly explain the circumstances surrounding your departure from the program. (Please note a previous withdrawal or dismissal will not exclude you from consideration for admissions.) If your dismissal was due to an academic performance issue, please describe how you will ensure future success in our nursing program.</span><span style="font-size: 14px; color: rgb(240, 2, 2);"> *</span></p>','','','','Requirement_Item__c-653');
