INSERT INTO "Question__c" VALUES('Question__c-3931','false','','','','Started App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Student Referral Eligibility Static (GSOE)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="color: rgb(68, 68, 68);">You are eligible for our Student Referral Program. Please provide the name and the St. Thomas email address of the current student or alumni who referred you if you would like to be considered for the referral bonus. For additional information and criteria, you can learn more about the program </span><a href="https://engineering.stthomas.edu/info-for/alumni/graduate-referral-program/index.html" target="_blank" style="background-color: rgb(255, 255, 255);">HERE</a><span style="color: rgb(68, 68, 68);">.</span></p>','','','','Requirement_Item__c-801');
