INSERT INTO "Question__c" VALUES('Question__c-3935','true','','','','Started App;Submitted App','','','','false','','','','OR','35.0','true','true','Started App','false','','','','','','','','','','','false','Are you interested in pursing a Bachelors of Nursing (BSN) at St. Thomas?','','','','BSN Program Interest (UGTR)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-3936','true','','','','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','','','','','Nursing Program App (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 16px;">BSN Program Application</strong></p><p><br></p><p><span style="color: inherit; font-size: 16px;">If you are interested in the Bachelor of Science in Nursing (BSN) at St. Thomas, please note that you must complete </span><strong style="color: inherit; font-size: 16px;">both applications:</strong></p><ol><li><span style="color: inherit; font-size: 16px;">this</span><strong style="color: inherit; font-size: 16px;"> transfer admissions application,</strong><span style="color: inherit; font-size: 16px;"> </span><em style="color: inherit; font-size: 16px;">and </em></li><li><span style="color: inherit; font-size: 16px;">the</span><em style="color: inherit; font-size: 16px;"> additional </em><a href="https://uofstthomasmn.my.site.com/Admissions/ApplicationRegistration?at=UGBSN" target="_blank" style="color: rgb(131, 72, 173); font-size: 16px; background-color: rgb(255, 255, 255);"><strong>BSN program application.</strong></a></li></ol><p><span style="color: rgb(0, 0, 0); font-size: 16px;">You are required to have completed the following pre-requisites (or their equivalencies) with a C- or higher before you start the BSN program at St. Thomas:</span></p><ul><li><a href="https://www.stthomas.edu/catalog/current/biol/" target="_blank" style="font-size: 16px;"><strong>BIOL </strong></a><strong style="font-size: 16px;">105 </strong><span style="font-size: 16px;">- Human Biology </span><strong style="font-size: 16px;">or </strong><a href="https://www.stthomas.edu/catalog/current/biol/" target="_blank" style="font-size: 16px;"><strong>BIOL </strong></a><strong style="font-size: 16px;">207</strong><span style="font-size: 16px;"> - Genetics Ecology Evolution</span></li><li><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH</strong></a> <strong style="font-size: 16px;">100</strong><span style="font-size: 16px;"> - Mathematical Sampler, </span><strong style="font-size: 16px;">or </strong><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH</strong></a><strong style="font-size: 16px;"> 101 </strong><span style="font-size: 16px;">- Finite Mathematics, </span><strong style="font-size: 16px;">or placement in </strong><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH </strong></a><strong style="font-size: 16px;">108</strong><span style="font-size: 16px;"> Calculus with Review I or higher</span></li><li><a href="https://www.stthomas.edu/catalog/current/chem/" target="_blank" style="font-size: 16px;"><strong>CHEM </strong></a><strong style="font-size: 16px;">108 </strong><span style="font-size: 16px;">- Nursing Chemistry (</span><a href="https://www.stthomas.edu/catalog/current/chem/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>CHEM </strong></a><strong style="font-size: 16px;">111</strong><span style="font-size: 16px;"> - General Chemistry I is an acceptable alternative)  </span></li><li><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px;"><strong>PSYC</strong></a><strong style="font-size: 16px;"> 111</strong><span style="font-size: 16px;"> - General Psychology</span></li><li><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>PSYC</strong></a><strong style="font-size: 16px;"> 102 </strong><span style="font-size: 16px;">- Lifespan Psychology for Nursing (</span><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>PSYC</strong></a><strong style="font-size: 16px;"> 202</strong><span style="font-size: 16px;"> - Lifespan Psychology is an acceptable alternative)</span></li></ul><p><br></p><p><span style="color: inherit; font-size: 16px;">Please contact </span><a href="mailto:nursing@stthomas.edu" target="_blank" style="font-size: 16px;"><strong>nursing@stthomas.edu</strong></a><strong style="font-size: 16px; color: inherit;"> </strong><span style="font-size: 16px; color: inherit;">if you have questions about transfer course equivalencies for nursing.</span></p>','','','','Requirement_Item__c-2');
INSERT INTO "Question__c" VALUES('Question__c-3937','false','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Why a Nurse Static Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(0, 0, 0);">(1) Describe why you want to become a nurse. Discuss experiences you&#39;ve had that will support your success in nursing school and later as a professional nurse. </span></p>','','','','Requirement_Item__c-270');
