INSERT INTO "Question__c" VALUES('Question__c-3939','false','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Personal Qualities Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 16px; color: rgb(0, 0, 0);">(2) After reviewing the</span><strong style="font-size: 16px; color: rgb(131, 72, 173);"><u> </u></strong><a href="https://health.stthomas.edu/nursing/index.html" target="_blank" style="font-size: 16px; color: rgb(131, 72, 173); background-color: rgb(255, 255, 255);"><strong><u>vision and mission of the School of Nursing</u></strong></a><span style="font-size: 16px; color: rgb(0, 0, 0);">, describe any personal qualities you have that align with our vision and mission. How do these personal qualities manifest themselves in your life? </span></p>','','','','Requirement_Item__c-270');
INSERT INTO "Question__c" VALUES('Question__c-3940','false','','','','Started App;Submitted App','','','','false','','','','','4.0','false','true','Started App','false','','','','','','','','','','','false','','','','','2. Personal Qualities (UGBSN)','Name','false','','','','','','','0124P0000003S9IQAU','','Started App','','','','','','','Requirement_Item__c-270');
INSERT INTO "Question__c" VALUES('Question__c-3941','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Prerequisite Requirements (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p style="text-align: center;"><strong style="font-size: 18px; color: rgb(109, 54, 150);">Prerequisite Requirements</strong></p><p><br></p><p><span style="color: rgb(0, 0, 0); font-size: 16px;">Students accepted into the fall BSN program cohort must complete the following courses with a C- or better by the time the fall semester begins:</span></p><p><br></p><p><span style="font-size: 16px;">Must be completed:</span></p><ul><li><a href="https://www.stthomas.edu/catalog/current/biol/" target="_blank" style="font-size: 16px;"><strong>BIOL </strong></a><strong style="font-size: 16px;">105 </strong><span style="font-size: 16px;">- Human Biology </span><strong style="font-size: 16px;">or </strong><a href="https://www.stthomas.edu/catalog/current/biol/" target="_blank" style="font-size: 16px;"><strong>BIOL </strong></a><strong style="font-size: 16px;">207</strong><span style="font-size: 16px;"> - Genetics Ecology Evolution</span></li><li><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH</strong></a> <strong style="font-size: 16px;">100</strong><span style="font-size: 16px;"> - Mathematical Sampler, </span><strong style="font-size: 16px;">or </strong><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH</strong></a><strong style="font-size: 16px;"> 101 </strong><span style="font-size: 16px;">- Finite Mathematics, </span><strong style="font-size: 16px;">or placement in </strong><a href="https://www.stthomas.edu/catalog/current/math/" target="_blank" style="font-size: 16px;"><strong>MATH </strong></a><strong style="font-size: 16px;">108</strong><span style="font-size: 16px;"> Calculus with Review I or higher</span></li><li><a href="https://www.stthomas.edu/catalog/current/chem/" target="_blank" style="font-size: 16px;"><strong>CHEM </strong></a><strong style="font-size: 16px;">108 </strong><span style="font-size: 16px;">- Nursing Chemistry (</span><a href="https://www.stthomas.edu/catalog/current/chem/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>CHEM </strong></a><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">111</strong><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> - General Chemistry I is an acceptable alternative)</span><span style="font-size: 16px;">  </span></li><li><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px;"><strong>PSYC</strong></a><strong style="font-size: 16px;"> 111</strong><span style="font-size: 16px;"> - General Psychology</span></li><li><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>PSYC</strong></a><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> 102 </strong><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">- Lifespan Psychology for Nursing (</span><a href="https://www.stthomas.edu/catalog/current/psychology/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);"><strong>PSYC</strong></a><strong style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> 202</strong><span style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);"> - Lifespan Psychology is an acceptable alternative)</span></li></ul><p><br></p><p><span style="color: rgb(0, 0, 0); font-size: 16px;">Additionally, students must have a </span><strong style="color: rgb(0, 0, 0); font-size: 16px;">cumulative GPA of a 2.75 or higher when they apply</strong><span style="color: rgb(0, 0, 0); font-size: 16px;">.</span></p>','','','','Requirement_Item__c-303');
