INSERT INTO "Question__c" VALUES('Question__c-4022','true','','','','Confirmed','','','','false','','','','','7.0','false','true','','false','','','Both Deposits Paid','','','','','','','','false','','','','','Confirmation Confirmation and Housing Deposit Received (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirmation and housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas!</p>','','','','Requirement_Item__c-855');
INSERT INTO "Question__c" VALUES('Question__c-4023','true','','','','','','','','false','','','','','1.0','false','true','','false','','','Select Deposit Type','','','','','','','','false','','','','','Confirmation Deposit Enticement (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To reserve your place in the class and request your space in our residence halls you must submit a confirming and housing deposit.</em></p><p><em> </em></p><p><em>Please note:</em></p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct expectations and fulfill admission obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>By submitting your housing deposit, you are agreeing to the terms outlined in the Student Residence Agreement. This agreement can be found on the <a href="https://www.stthomas.edu/residence-life/policies-resources/index.html" target="_blank">Residence Life Website</a>.</li></ul><p>International students depositing from outside the U.S.?</p><ul><li>If you are submitting your deposit from outside the U.S., please <a href="https://pay.flywire.com/?utm_source=www&amp;utm_medium=referral&amp;utm_campaign=redirectio" target="_blank">submit your deposit</a> through <a href="https://flywire.com/" target="_blank">Flywire.com</a> and choose the University of St. Thomas (Minnesota).</li></ul>','','','','Requirement_Item__c-855');
INSERT INTO "Question__c" VALUES('Question__c-4024','true','','','','Confirmed','','','','false','','','','','13.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Confirming Only Deposit Received (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirming deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your housing deposit if you plan to live on campus!</p>','','','','Requirement_Item__c-855');
