INSERT INTO "Question__c" VALUES('Question__c-4028','true','','','','Admit','','','','false','','','','','23.0','false','true','','false','','','Housing Deposit Paid','','','','','','','','false','','','','','Housing Only Deposit Received (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your confirming deposit to lock in your spot!</p>','','','','Requirement_Item__c-855');
INSERT INTO "Question__c" VALUES('Question__c-4029','false','','','','Started App;Submitted App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Changes Consent Text (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><br></p><p>I understand that once my application has been submitted it may not be altered; I will need to contact the Office of Undergraduate Admissions via email at <strong>admissions@stthomas.edu</strong> to provide additional information or make changes (ex. address change). <span style="color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-856');
