INSERT INTO "Question__c" VALUES('Question__c-4135','true','','','','Confirmed','','','','false','','','','','','false','true','','false','','','Second Deposit Paid - Confirming','','','','','','','','false','','','','','Second Deposit - Confirming Only Deposit Received (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your confirming deposit and reserving your spot at St. Thomas!</p>','','','','Requirement_Item__c-882');
INSERT INTO "Question__c" VALUES('Question__c-4136','true','','','','Admit','','','','false','','','','','1.0','false','true','','false','','','Both Deposits Paid','','','','','','','','false','','','','','Second Deposit Confirming Only Enticement (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>Thanks for you hosing deposit earlier. To reserve a spot in our upcoming class, you must submit a confirming deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul><p>Click the Submit Deposit button below to proceed to our payment processing system.</p>','','','','Requirement_Item__c-882');
INSERT INTO "Question__c" VALUES('Question__c-4137','true','','','','Confirmed','','','','false','','','','','2.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Deposit Housing Only AFTER Confirming Deposit (UGTRCAM)','Name','false','','','','','','','0124P0000003SJ2QAM','','','','','','','','','Requirement_Item__c-885');
INSERT INTO "Question__c" VALUES('Question__c-4138','true','','','','Confirmed','','','','false','','','','','30.0','false','true','','false','','','Second Deposit Paid - Housing','','','','','','','','false','','','','','Second Deposit - Housing Only Deposit Received (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Deposit Received</strong></p><p><br></p><p>Thanks for submitting your housing deposit and requesting a spot in our residence halls!</p>','','','','Requirement_Item__c-885');
INSERT INTO "Question__c" VALUES('Question__c-4139','true','','','','Confirmed','','','','false','','','','','1.0','false','true','','false','','','Confirming Deposit Paid','','','','','','','','false','','','','','Second Deposit Housing Only Enticement (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><em>To request your space in our residence halls you must submit a housing deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul><p>Click the Submit Deposit button below to proceed to our payment processing system.</p>','','','','Requirement_Item__c-885');
