INSERT INTO "Question__c" VALUES('Question__c-4219','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','BSN Eligibility Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px;">The Bachelor of Science in Nursing (BSN) application for Fall 2025 is only open to</span><span style="font-size: 16px; color: rgb(0, 0, 0);"> </span><strong style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">new Undergraduate Transfer applicants</strong><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);"> and</span><span style="font-size: 16px; color: rgb(0, 0, 0);"> </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">currently enrolled University </strong><strong style="font-size: 16px;">of St. Thomas students.</strong></p>','','','','Requirement_Item__c-787');
