INSERT INTO "Question__c" VALUES('Question__c-4227','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','Transfer Common App Affirmation Statements','','','','TR CA Affirmation Statements Static (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="color: rgb(0, 0, 0); font-size: 16px;">The student has responded to all the Transfer Common App: Affirmation Statements with an &quot;I affirm&quot; and provided their signature.</span><span style="color: rgb(68, 68, 68); font-size: 16px;"> </span><span style="color: rgb(254, 3, 3); font-size: 16px;">*</span></p>','','','','Requirement_Item__c-856');
