INSERT INTO "Question__c" VALUES('Question__c-4230','true','','','Generic_Filter_3__c','Started App','','','','false','','','','','7.0','false','true','Started App','false','','','','','','','','','','','false','Previous UST degree in the past 3 years','','','','Previous UST degree Picklist (GSOEd)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4231','true','','','','Confirmed','','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','','false','','','','','1.0','false','true','','false','','','','','','ENGL Placement Required','','','','','false','','','','','English Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 11pt;">English Placement Assessment</strong></p><ul><li><span style="font-size: 11pt;">Grounded in our convictions of personal attention and academic excellence, the English placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.  </span></li><li><span style="font-size: 11pt;">You are required to take the English Placement assessment so that English faculty members can assess your writing needs and determine whether you should be placed in ENGL 110: Intensive Writing, or ENGL 121: Critical Thinking: Reading and Writing.  </span></li><li><span style="font-size: 11pt;">This is an essay assessment with a prompt; students taking this assessment usually complete it in one hour or less. </span></li><li><span style="font-size: 11pt;">If you are bringing in PSEO, College in the Schools, the AP Literature &amp; Composition test with a score of 4 or 5, or IB higher with a score of 4 or more, please indicate that on the first page of the assessment; you will not need to complete the essay.</span></li></ul><p><span style="font-size: 11pt;"> </span></p><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_6Vxq8B6Cb4h5zM2?CID={{Contact_ID}}&amp;BID={{Banner_ID}}&amp;sffirstName={{First_Name}}&amp;sflastName={{Last_Name}}&amp;sfEmail={{Portal_University_email}}" target="_blank" style="font-size: 11pt;">Click Here to Start the English Placement Assessment</a><span style="font-size: 11pt;"> </span></p>','','','','Requirement_Item__c-817');
INSERT INTO "Question__c" VALUES('Question__c-4232','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Math Placement Assessment - Optional','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Calibri, sans-serif;">Math Placement Assessment</strong></p><p><span style="font-family: Calibri, sans-serif;">Grounded in our convictions of personal attention and academic excellence, the Math placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">If you are interested in studying a STEM major at St. Thomas (Science, Technology, Engineering, Mathematics) you may (or may not!) need to complete the Math Placement Assessment. Please read these directions provided by the St. Thomas Mathematics Department for specific directions and next steps: </span><a href="https://www.stthomas.edu/_media-library/_documents/new-students/math-placement-assessment-instructions-2024.pdf" target="_blank" style="font-family: Calibri, sans-serif;">Math Placement Assessment Instructions</a></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">Please complete the Math Placement Assessment by </span><strong style="font-family: Calibri, sans-serif;">Wednesday, June 5, 2024</strong><span style="font-family: Calibri, sans-serif;">.</span></p>','','','','Requirement_Item__c-808');
INSERT INTO "Question__c" VALUES('Question__c-4233','true','','','','Confirmed','','','','false','','','','','1.0','false','true','','false','','','','','','MATH Placement Required','','','','','false','','','','','Math Placement Test','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Calibri, sans-serif;">Math Placement Assessment</strong></p><p><span style="font-family: Calibri, sans-serif;">Grounded in our convictions of personal attention and academic excellence, the Math placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">If you are interested in studying a STEM major at St. Thomas (Science, Technology, Engineering, Mathematics) you may (or may not!) need to complete the Math Placement Assessment. Please read these directions provided by the St. Thomas Mathematics Department for specific directions and next steps: </span><a href="https://www.stthomas.edu/_media-library/_documents/new-students/math-placement-assessment-instructions-2024.pdf" target="_blank" style="font-family: Calibri, sans-serif;">Math Placement Assessment Instructions</a></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">Please complete the Math Placement Assessment by </span><strong style="font-family: Calibri, sans-serif;">Wednesday, June 5, 2024</strong><span style="font-family: Calibri, sans-serif;">.</span></p>','','','','Requirement_Item__c-805');
