INSERT INTO "Question__c" VALUES('Question__c-4235','true','','','Student_Type__c','','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','','false','Please select the appropriate department.','','','','Department - Student Type Intl. (GSOEd)','Name','false','','','','','Educational LeadershipINSERT INTO "Question__c" VALUES('Question__c-4236','true','','','Degree_Type__c','','','','','false','','','','','8.0','false','true','','false','','','','','','','','','','','false','Intended degree level you''re pursuing?','','','','Degree Type Edu Lead Intl. (GSOEd)','Name','false','','','','','DoctoralINSERT INTO "Question__c" VALUES('Question__c-4237','true','','','','Confirmed','','','','false','','','','','9.0','false','true','','false','','','','','Finance;Non-STEM','','','','','','false','','','','','Chemistry Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 11pt; font-family: Calibri, sans-serif;">Chemistry Placement Assessment</strong></p><p><br></p><p><span style="font-family: Calibri, sans-serif;">Grounded in our convictions of personal attention and academic excellence, the placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">The chemistry placement assessment is </span><u style="font-family: Calibri, sans-serif;">required</u><span style="font-family: Calibri, sans-serif;"> if you are considering a major that requires chemistry (e.g. biology, biochemistry, environmental science, exercise science, geology, neuroscience, nutrition), or have aspirations in the health professions (chiropractic, dentistry, medicine, optometry, pharmacy, physical therapy, physician assistant, veterinary medicine). </span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">You are encouraged to take the chemistry placement assessment if your major and/or career interests are not among those listed above. Please consult with Academic Counseling (651-962-6300) for guidance about the chemistry placement assessment.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif; color: black;">This assessment will assess your preparedness for chemistry and place you into one of three categories prior to registration: </span></p><ul><li><span style="font-family: Calibri, sans-serif; color: black;">CHEM 115 – Accelerated General Chemistry – This course blends the essentials of General Chemistry into one accelerated semester. </span></li><li><span style="font-family: Calibri, sans-serif; color: black;">CHEM 111/112 – General Chemistry I and II – The traditional two-semester sequence of General Chemistry.  </span></li><li><span style="font-family: Calibri, sans-serif; color: black;">CHEM 110 – Introduction to Chemistry – This course is a 1-credit online course to provide foundational chemistry skills to students so that they are better prepared to succeed in CHEM 111. CHEM 110 is available Summer Session II for students wishing to start CHEM 111 in Fall and in January Term for students wishing to start CHEM 111 in Spring.</span></li></ul><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_br9Mx2J4Pmi7jRI?StudentId={{Contact_ID}}" target="_blank">Click Here to Start the Chemistry Placement Assessment</a></p>','','','','Requirement_Item__c-818');
INSERT INTO "Question__c" VALUES('Question__c-4238','true','','','','Confirmed','','','','false','','','','','','false','true','','false','','','','','','CHEM Placement Required','','','','','false','','','','','Chemistry Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Calibri, sans-serif; font-size: 11pt;">Chemistry Placement Assessment</strong></p><p><br></p><p><span style="font-family: Calibri, sans-serif;">Grounded in our convictions of personal attention and academic excellence, the placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">The chemistry placement assessment is </span><u style="font-family: Calibri, sans-serif;">required</u><span style="font-family: Calibri, sans-serif;"> if you are considering a major that requires chemistry (e.g. biology, biochemistry, environmental science, exercise science, geology, neuroscience, nutrition), or have aspirations in the health professions (chiropractic, dentistry, medicine, optometry, pharmacy, physical therapy, physician assistant, veterinary medicine). </span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">You are encouraged to take the chemistry placement assessment if your major and/or career interests are not among those listed above. Please consult with Academic Counseling (651-962-6300) for guidance about the chemistry placement assessment.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="color: black; font-family: Calibri, sans-serif;">This assessment will assess your preparedness for chemistry and place you into one of three categories prior to registration: </span></p><ul><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 115 – Accelerated General Chemistry – This course blends the essentials of General Chemistry into one accelerated semester. </span></li><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 111/112 – General Chemistry I and II – The traditional two-semester sequence of General Chemistry.  </span></li><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 110 – Introduction to Chemistry – This course is a 1-credit online course to provide foundational chemistry skills to students so that they are better prepared to succeed in CHEM 111. CHEM 110 is available Summer Session II for students wishing to start CHEM 111 in Fall and in January Term for students wishing to start CHEM 111 in Spring.  </span></li></ul><p><span style="font-family: Calibri, sans-serif; font-size: 11pt;"> </span></p><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_br9Mx2J4Pmi7jRI?StudentId={{Contact_ID}}" target="_blank">Click Here to Start the Chemistry Placement Assessment</a></p>','','','','Requirement_Item__c-819');
INSERT INTO "Question__c" VALUES('Question__c-4239','true','','','','Confirmed','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Chinese Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong><u>Chinese Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p>If you place into 212, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete CHIN 212. The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The Chinese assessment is intended to assess your level of competency in Chinese. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Each question must be answered before you can proceed to the next question. It is to your advantage to use your knowledge of this language rather than take a wild guess. Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>. The assessment is available between the hours of 1:00 a.m. and 11:00 p.m. (CST) daily. No outside assistance should be used to complete the assessment.</p><p><br></p><p>DO NOT use the Back button on the browser.</p><p><br></p><p>Please note: The Chinese placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday,</strong> <strong>June 5, 2024.</strong></p><p><br></p><p><a href="https://usttrial99756.jitterbit.net/AW-PROD/startForLangPlcmtTestAtWCPrd?&amp;language=CH&amp;firstName={{First_Name}}&amp;lastName={{Last_Name}}&amp;ustEmail={{Portal_University_email}}&amp;uniqueId={{Banner_ID}}-3" target="_blank">Click Here to Start the Chinese Placement Assessment</a></p>','','','','Requirement_Item__c-806');
INSERT INTO "Question__c" VALUES('Question__c-4240','true','','','','Confirmed','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Latin Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Aptos, sans-serif; font-size: 11pt;"><u>Latin Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p><br></p><p>If you place into 212, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete LATN 212. The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The Latin assessment is intended to assess your level of competency in Latin. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>.</p><p><br></p><p>Please note: The Latin placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday,</strong> <strong>June 5, 2024.</strong></p><p><br></p><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_bfR5M79n5NGbGQe?StudentId={{Contact_ID}}" target="_blank">Click Here to Start the Latin Placement Assessment</a></p>','','','','Requirement_Item__c-820');
INSERT INTO "Question__c" VALUES('Question__c-4241','true','','','','Confirmed','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','','','','','French Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong><u>French Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p>300      Introductory course for a major/minor in the language</p><p>If you place into 212 or higher, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete the course you tested into (212 or higher). The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The French assessment is intended to assess your level of competency in French. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Each question must be answered before you can proceed to the next question. It is to your advantage to use your knowledge of this language rather than take a wild guess. Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>. The assessment is available between the hours of 1:00 a.m. and 11:00 p.m. (CST) daily. No outside assistance should be used to complete the assessment.</p><p><br></p><p>DO NOT use the Back button on the browser.</p><p><br></p><p>Please note: The French placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday,</strong> <strong>June 5, 2024.</strong></p><p><br></p><p><a href="https://usttrial99756.jitterbit.net/AW-PROD/startForLangPlcmtTestAtWCPrd?&amp;language=FR&amp;firstName={{First_Name}}&amp;lastName={{Last_Name}}&amp;ustEmail={{Portal_University_email}}&amp;uniqueId={{Banner_ID}}-1" target="_blank">Click Here to Start the French Placement Assessment</a></p>','','','','Requirement_Item__c-814');
INSERT INTO "Question__c" VALUES('Question__c-4242','true','','','','Confirmed','','','','false','','','','','5.0','false','true','','false','','','','','','','','','','','false','','','','','German Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Aptos, sans-serif; font-size: 11pt;"><u>German Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p>300      Introductory course for a major/minor in the language</p><p>If you place into 212 or higher, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete the course you tested into (212 or higher). The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The German assessment is intended to assess your level of competency in German. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Each question must be answered before you can proceed to the next question. It is to your advantage to use your knowledge of this language rather than take a wild guess. Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>. The assessment is available between the hours of 1:00 a.m. and 11:00 p.m. (CST) daily. No outside assistance should be used to complete the assessment.</p><p><br></p><p>DO NOT use the Back button on the browser.</p><p><br></p><p>Please note: The German placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday, June 5, 2024.</strong></p><p><br></p><p><a href="https://usttrial99756.jitterbit.net/AW-PROD/startForLangPlcmtTestAtWCPrd?&amp;language=GR&amp;firstName={{First_Name}}&amp;lastName={{Last_Name}}&amp;ustEmail={{Portal_University_email}}&amp;uniqueId={{Banner_ID}}-2" target="_blank">Click Here to Start the German Placement Assessment</a></p>','','','','Requirement_Item__c-815');
INSERT INTO "Question__c" VALUES('Question__c-4243','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Italian Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Aptos, sans-serif; font-size: 11pt;"><u>Italian Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p><br></p><p>If you place into 212, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete ITAL 212. The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The Italian assessment is intended to assess your level of competency in Italian. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>.</p><p><br></p><p>Please note: The Italian placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday,</strong> <strong>June 5, 2024.</strong></p><p><br></p><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_3qojFGPQ9DKnORg?StudentId={{Contact_ID}}" target="_blank">Click Here to Start the Italian Placement Assessment</a></p>','','','','Requirement_Item__c-809');
INSERT INTO "Question__c" VALUES('Question__c-4244','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','Spanish Language Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong><u>Spanish Placement Assessment</u></strong></p><p><br></p><p>You are required to take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have completed two (2) or more years of the language in high school;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are taking a language in an International Baccalaureate program;</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have taken the Advanced Placement (AP) language exam and received a score of 2 or lower.</p><p><br></p><p>Please <strong>do not</strong> take a language placement assessment if you:</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Are transferring academic credit in a language from a college or university, including College in Schools (CIS), Post-Secondary Enrollment Option (PSEO), etc.</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have received an AP score of 3 or higher in the language or are awaiting your AP scores*</p><p><span style="font-family: Symbol;">·</span><span style="font-size: 7pt;">      </span>Have not previously taken any classes in the language.</p><p>*If you receive a 3 or above on an AP language exam, that score will determine your language placement. Depending on the score, you should enroll in the next sequential course above the course for which you received credit. Please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> if you have questions.</p><p><br></p><p><strong>Placement Levels</strong></p><p>Upon completion of the placement assessment, you will place into one of the following levels:</p><p>111      Elementary I</p><p>122      Elementary II with Review</p><p>112      Elementary II</p><p>211      Intermediate I</p><p>212      Intermediate II</p><p>300      Introductory course for a major/minor in the language</p><p>If you place into 212 or higher, you have two options to complete the language and culture core requirement. One is to enroll in and successfully complete the course you tested into (212 or higher). The other is to take a second, proctored proficiency test. To schedule this second examination, please contact <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a>.</p><p><br></p><p><strong>Placement Assessment Instructions</strong></p><p><br></p><p>The Spanish assessment is intended to assess your level of competency in Spanish. All of the questions are multiple choice. <strong>There is only one correct answer for each question.</strong> Each question must be answered before you can proceed to the next question. It is to your advantage to use your knowledge of this language rather than take a wild guess. Please allow approximately one hour to take the assessment in one sitting. If you experience a technical difficulty during the assessment, please contact <a href="mailto:techdesk@stthomas.edu" target="_blank">techdesk@stthomas.edu</a>. The assessment is available between the hours of 1:00 a.m. and 11:00 p.m. (CST) daily. No outside assistance should be used to complete the assessment.</p><p><br></p><p>DO NOT use the Back button on the browser.</p><p><br></p><p>Please note: The Spanish placement assessment can only be taken once, so if you are not prepared or do not have time to take the placement assessment at this time, do NOT click on the link to start the assessment. If English is not your primary language, please contact the Modern &amp; Classical Language department at <a href="mailto:mcl@stthomas.edu" target="_blank">mcl@stthomas.edu</a> for information about the language proficiency verification.</p><p><br></p><p>Please complete the placement assessment by <strong>Wednesday,</strong> <strong>June 5, 2024.</strong></p><p><br></p><p><a href="https://usttrial99756.jitterbit.net/AW-PROD/startForLangPlcmtTestAtWCPrd?&amp;language=SP&amp;firstName={{First_Name}}&amp;lastName={{Last_Name}}&amp;ustEmail={{Portal_University_email}}&amp;uniqueId={{Banner_ID}}-0" target="_blank">Click Here to Start the Spanish Placement Assessment</a></p>','','','','Requirement_Item__c-810');
INSERT INTO "Question__c" VALUES('Question__c-4245','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','Welcome (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(43, 43, 43);">Thank you for your interest in the Dougherty Family College (DFC) Associate of Arts (AA) in Liberal Arts with a Pre-STEM Concentration!</strong></p><p><br></p><p><span style="color: rgb(43, 43, 43);">This selective program will offer a cohort of students the opportunity to earn up to 16 transferrable math or science credits and to take some classes on the St. Paul campus.</span></p><p><br></p><p><span style="color: rgb(43, 43, 43);">Students interested in applying to this program must complete the following application and take a required math placement assessment to be considered for the program.</span></p><p><br></p><p><em style="color: rgb(43, 43, 43);">﻿Students will be notified in early August whether or not they’ve been accepted into the Pre-STEM Concentration program.</em></p>','','','','Requirement_Item__c-906');
INSERT INTO "Question__c" VALUES('Question__c-4246','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','Have you been admitted to Dougherty Family College?','','','','Eligibility (DFCSTEM)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4247','true','','','','Started App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','Why do you want to participate in the AA with Pre-STEM Concentration program (250 words max)?','','','','STEM Interest','Name','false','','','','','','','0124P0000003S9IQAU','','Started App','','','','','','','Requirement_Item__c-807');
INSERT INTO "Question__c" VALUES('Question__c-4248','true','','','','','','','','false','','','','','4.0','false','true','','false','','','','','','','','','','','false','','','','','Ineligible (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(247, 1, 1);">STOP:</strong><span style="color: rgb(43, 43, 43);"> Admission to Dougherty Family College is required</span><em style="color: rgb(43, 43, 43);"> prior to</em><span style="color: rgb(43, 43, 43);"> applying for the AA in Liberal Arts with a Pre-STEM Concentration program.</span></p><p><br></p><p><span style="color: rgb(43, 43, 43);">Please contact </span><a href="mailto:admissons@stthomas.edu" target="_blank" style="color: rgb(43, 43, 43);">Admissions</a><span style="color: rgb(43, 43, 43);"> about your Dougherty Family College application status.</span></p>','','','','Requirement_Item__c-906');
INSERT INTO "Question__c" VALUES('Question__c-4249','true','','','','Admit;Confirmed','','','','false','','','','','1.0','false','true','Admit','false','','','','','','','','','','','false','','','','','Admission Confirmation (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','Admit','','','<dl><dd style="text-align: center;"><strong style="color: rgb(43, 43, 43); background-color: rgb(255, 255, 255); font-size: 16px;">﻿Congratulations!</strong></dd><dd><span style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(43, 43, 43);">﻿You’ve been accepted to the DFC AA with Pre-STEM Concentration program! </span><strong style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(43, 43, 43);">You will need to confirm your participation in order to complete your enrollment in the program.</strong></dd><dd><br></dd><dd><em style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(43, 43, 43);">By confirming your participation you are committing to:</em></dd></dl><ul><li><span style="font-size: 16px; color: rgb(43, 43, 43);">taking up to 16 STEM-specific credits over the next two years on the St. Paul campus.</span></li><li><span style="font-size: 16px; color: rgb(43, 43, 43);">accessing support resources as appropriate</span></li><li><span style="font-size: 16px; color: rgb(43, 43, 43);">meeting regularly with your mentor to discuss your progress, successes, and challenges in the program</span></li></ul>','','','','Requirement_Item__c-816');
INSERT INTO "Question__c" VALUES('Question__c-4250','true','','','','Confirmed','','','','false','','','','','2.0','false','true','Confirmed','false','','','','','','','','','','','false','','','','','Participation Confirmed Static (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 16px; color: rgb(43, 43, 43);">Thank you for confirming your participation in the AA with Pre-STEM Concentration!</strong></p>','','','','Requirement_Item__c-816');
INSERT INTO "Question__c" VALUES('Question__c-4251','true','','','','Started App','','','','false','','','','','4.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Science/Math Course','Name','false','','','','','','','0124P0000003S9IQAU','','Started App','','','','','','','Requirement_Item__c-905');
INSERT INTO "Question__c" VALUES('Question__c-4252','true','','','','Admit','','','','false','','','','','2.0','true','true','Admit','false','','','','','','','','','','If you are no longer interested in the STEM Concentration, you will continue in the DFC AA in Liberal Arts track.','false','Do you confirm your participation in the AA with Pre-STEM Concentration?','','','','Confirmation of Participation (DFCSTEM)','Name','false','','','','','Yes, I confirm my participationINSERT INTO "Question__c" VALUES('Question__c-4253','true','','','','Started App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','STEM Activities Static','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong>What kinds of STEM experiences or activities have you had? </strong></p><p><br></p><p><em style="color: rgb(43, 43, 43);">These activities can be formal (science fair, robotic competitions, jobs or internships, etc) or informal (fixing electronics or engines, learning a computer language on your own, etc). Please include types of activities and estimated dates of participation.</em></p>','','','','Requirement_Item__c-905');
INSERT INTO "Question__c" VALUES('Question__c-4254','true','','','','Started App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','','','','','STEM Activities','Name','false','','','','','','','0124P0000003S9IQAU','','Started App','','','','','','','Requirement_Item__c-905');
INSERT INTO "Question__c" VALUES('Question__c-4255','true','','','','Submitted App','','','','false','','','','','3.0','false','true','Submitted App;Complete App','false','','','','','','','','','','Your score will be verified as part of the application review process.','false','Please submit the score you received on your ALEKS Math Assessment:','','','','Math Assessment Score','Name','false','','','','','','','0124P0000003S9RQAU','','Submitted App','','','<p><span style="font-size: 14px; color: rgb(43, 43, 43);">Please submit the score you received on your ALEKS Math Assessment:</span></p>','','','','Requirement_Item__c-812');
INSERT INTO "Question__c" VALUES('Question__c-4256','true','','','','Started App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Science/Math Course Static','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong style="color: rgb(43, 43, 43);">Tell us a bit about any science and math courses you’ve taken in high school.</strong></p><p><br></p><p><em style="color: rgb(43, 43, 43);">﻿Please include the name of the course, the year/semester you took the course and your final course grade. Please feel free to add any comments about your experience in the course or the grade you received in the course.</em></p>','','','','Requirement_Item__c-905');
INSERT INTO "Question__c" VALUES('Question__c-4257','true','','','','Submitted App;Complete App','','','','false','','','','','1.0','false','true','Submitted App','false','','','','','','','','','','','false','','','','','Math Assessment Instructions (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','Submitted App','','','<p><span style="font-size: 16px;">In order for your DFC Pre-STEM Concentration application to be reviewed, you must first complete the required ALEKS Math Assessment.  </span></p><p><br></p><p><span style="font-size: 16px;">The official math assessment will be given on </span><strong style="font-size: 16px; color: rgb(253, 2, 2);">August 21</strong><span style="font-size: 16px;"> at 3:30 pm on the Minneapolis campus. Please mark this date in your calendar.  </span></p><p><br></p><p><span style="font-size: 16px;">To become familiar with the assessment and to get some practice before the assessment date, please set up your ALEKS account. To get the most out of your practice, we recommend getting started with ALEKS at least two weeks before the assessment date. </span></p><p><br></p><p><strong style="background-color: rgb(255, 255, 255); font-size: 16px;">How to sign up for and practice for your ALEKS<em> </em>Math Assessment:</strong></p><ol><li><span style="font-size: 16px;">Go to: </span><a href="https://aleks.com/" target="_blank" style="font-size: 16px;">ALEKS.com</a><span style="font-size: 16px;"> </span></li><li><span style="font-size: 16px;">Click the Sign Up link in the top right corner. </span></li><li><span style="font-size: 16px; background-color: rgb(255, 255, 255);">Enter the course code: </span><strong style="font-size: 16px; color: rgb(0, 0, 0);">RDAQW-P93JC</strong></li><li><span style="font-size: 16px;">Select &quot;I have never used ALEKS before&quot; and complete the Student Information. You do not need to enter your student ID. </span></li><li><span style="font-size: 16px;">Write down your Login Name (this is generated for you and displayed on the next screen). </span></li><li><span style="font-size: 16px;">You’ll take a quick Tools Tutorial to help you familiarize yourself with the online tools available and, generally, how to use the program. This should only take about 5 minutes.</span></li><li><span style="font-size: 16px;">Take the practice Math Assessment. Once you start the assessment, you’ll have 2 hours to complete it. </span></li></ol><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">Once you’ve completed the initial, practice assessment, ALEKS will place you in a Prep and Learning module especially designed for you to help you practice the skills and concepts you struggled with on the assessment.</span></p>','','','','Requirement_Item__c-811');
INSERT INTO "Question__c" VALUES('Question__c-4258','true','','','','Submitted App;Complete App','','','','false','','','','','2.0','false','true','Submitted App','false','','','','','','','','','','','false','','','','','Math Assessment Reminders','Name','false','','','','','','','0124P0000003S9QQAU','','Submitted App','','','<p><strong style="font-size: 16px;">Helpful Reminders</strong></p><p><span style="font-size: 16px;">Do your best work. You&#39;ll be given roughly 25-30 questions. The questions are adaptive, which means your next question depends on how you answered the last question--the program is helping you identify your math strengths and areas for improvement. To get the most accurate results you&#39;ll need to YOUR best work, not your friend&#39;s or neighbor&#39;s best work...not some AI site’s best work...your work. </span></p><p><br></p><p><span style="font-size: 16px;">There is a calculator provided in the program for certain problems so you will not need, nor be allowed, to use your personal calculator or cell phone. </span></p><p><br></p><p><span style="font-size: 16px;">You will only be allowed use paper and a pencil/pen…so have some handy! </span></p>','','','','Requirement_Item__c-811');
INSERT INTO "Question__c" VALUES('Question__c-4259','true','','','','Submitted App;Complete App','','','','false','','','','','1.0','false','true','Submitted App','false','','','','','','','','','','','false','','','','','Math Assessment Completion Static','Name','false','','','','','','','0124P0000003S9QQAU','','Submitted App','','','<p><span style="color: rgb(43, 43, 43);">Completion of the online ALEKS Math Assessment is required in order for your DFC Pre-STEM Concentration program application to be considered complete and reviewed for admission.</span></p><p><br></p><p><strong style="color: rgb(43, 43, 43);">﻿Once you have completed your assessment,</strong><span style="color: rgb(43, 43, 43);"> please enter the following information:</span></p>','','','','Requirement_Item__c-812');
