INSERT INTO "Question__c" VALUES('Question__c-4263','true','','','','Started App','','','','false','','','','','5.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Enrollment Consent Static (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="color: rgb(43, 43, 43); font-size: 16px;">I understand that completion of these materials does not enroll me in the Pre-STEM Concentration program. I understand I</span><span style="font-size: 16px;"> will be contacted in August to find out if I have been admitted into the Pre-STEM concentration. <span class="ql-cursor">﻿</span>If I am not selected for the Pre-STEM Concentration, I understand I will continue to be enrolled in the traditional DFC Liberal Arts AA degree. </span><span style="font-size: 14px; color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-910');
