INSERT INTO "Question__c" VALUES('Question__c-4265','true','','','','Started App','','','','false','','','','','1.0','true','true','Started App','false','','','','','','','','','','<i>While an ACT/SAT score is not required for acceptance into the program, if you have completed one or more of these exams, please enter your math sub-score.</i>','false','Have you taken the ACT and/or the SAT exam?','','','','Math Test Score','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4266','true','','','','Started App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','ACT/SAT Math Sub-score','4.0','','','ACT/SAT Math Sub-score','Name','false','','','','','','','0124P0000003S9KQAU','','','','','','','','','Requirement_Item__c-907');
INSERT INTO "Question__c" VALUES('Question__c-4267','true','','','','Started App','','','','false','','','','','1.0','true','true','Started App','false','','','','','','','','','','','false','As of now, what area/degree are you most interested in pursuing once you transfer into a bachelor''s degree program?','','','','STEM Degree Interest','Name','false','','','','','Biology, Pre-Health, Geology, Environmental ScienceINSERT INTO "Question__c" VALUES('Question__c-4268','true','','','','Started App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','Please share any other information or thoughts you would like us to consider in reviewing your application.','','','','Additional Information','Name','false','','','','','','','0124P0000003S9IQAU','','','','','','','','','Requirement_Item__c-909');
