INSERT INTO "Question__c" VALUES('Question__c-4271','true','','','','Started App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Changes Consent Static (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">I understand that once my application has been submitted it may not be altered; I will need to contact the Pre-STEM program via email at </span><a href="mailto:DFC-PreSTEM@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255);">DFC-PreSTEM@stthomas.edu </a><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">to provide additional information or make changes.</span><span style="color: rgb(255, 0, 0); font-size: 14px; background-color: rgb(255, 255, 255);">*</span></p>','','','','Requirement_Item__c-910');
INSERT INTO "Question__c" VALUES('Question__c-4272','true','','','','Started App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent (DFCSTEM)','Name','false','','','','','I Agree','','0124P0000003S9NQAU','','Started App','','','','','','','Requirement_Item__c-910');
INSERT INTO "Question__c" VALUES('Question__c-4273','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Application Materials Consent Static (DFCSTEM)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="font-size: 16px;">I have reviewed each page of my application. I certify the information I have provided on this application and all other admission materials is complete, accurate and true to the best of my knowledge. </span><span style="font-size: 16px; color: rgb(255, 0, 0);">*</span></p>','','','','Requirement_Item__c-910');
INSERT INTO "Question__c" VALUES('Question__c-4274','true','','','','Confirmed','','','','false','','','','','9.0','false','true','','false','','','','','STEM','CHEM Placement Optional','','','','','false','','','','','Chemistry Placement Assessment','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-family: Calibri, sans-serif; font-size: 11pt;">Chemistry Placement Assessment</strong></p><p><br></p><p><span style="font-family: Calibri, sans-serif;">Grounded in our convictions of personal attention and academic excellence, the placement process is designed to help assess your academic preparation and ensure that your enrollment in your first semester sets you up for success.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">The chemistry placement assessment is </span><u style="font-family: Calibri, sans-serif;">required</u><span style="font-family: Calibri, sans-serif;"> if you are considering a major that requires chemistry (e.g. biology, biochemistry, environmental science, exercise science, geology, neuroscience, nutrition), or have aspirations in the health professions (chiropractic, dentistry, medicine, optometry, pharmacy, physical therapy, physician assistant, veterinary medicine). </span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="font-family: Calibri, sans-serif;">You are encouraged to take the chemistry placement assessment if your major and/or career interests are not among those listed above. Please consult with Academic Counseling (651-962-6300) for guidance about the chemistry placement assessment.</span></p><p><span style="font-family: Calibri, sans-serif;"> </span></p><p><span style="color: black; font-family: Calibri, sans-serif;">This assessment will assess your preparedness for chemistry and place you into one of three categories prior to registration: </span></p><ul><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 115 – Accelerated General Chemistry – This course blends the essentials of General Chemistry into one accelerated semester. </span></li><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 111/112 – General Chemistry I and II – The traditional two-semester sequence of General Chemistry.  </span></li><li><span style="color: black; font-family: Calibri, sans-serif;">CHEM 110 – Introduction to Chemistry – This course is a 1-credit online course to provide foundational chemistry skills to students so that they are better prepared to succeed in CHEM 111. CHEM 110 is available Summer Session II for students wishing to start CHEM 111 in Fall and in January Term for students wishing to start CHEM 111 in Spring.</span></li></ul><p><a href="https://stthomas.az1.qualtrics.com/jfe/form/SV_br9Mx2J4Pmi7jRI?StudentId={{Contact_ID}}" target="_blank">Click Here to Start the Chemistry Placement Assessment</a></p>','','','','Requirement_Item__c-912');
INSERT INTO "Question__c" VALUES('Question__c-4275','true','','','Pre_Professional_Program__c','Started App;Submitted App','','','','false','','','','','10.0','true','true','Started App','false','','','','','','','','','','','false','','','Program__c','(RecordTypeId = ''0124P0000003S97'' AND Program_Type__c INCLUDES (''Pre-Professional''))','Pre-Professional Program Interest (UGTR)','Name','false','','','','','','','0124P0000003S9PQAU','','','','','','','','','Requirement_Item__c-689');
