INSERT INTO "Question__c" VALUES('Question__c-4299','true','','','','','','','','false','','','','OR','1.0','false','true','','false','','','','','','','','','','','false','Select which scenario best describes your visa situation:','','','','Visa Information (UGFR)','Name','false','','','','','I have requested an I-20 from St. Thomas & am applying for an F-1 visaINSERT INTO "Question__c" VALUES('Question__c-4300','true','','','ACTC_tuition_benefit__c','Started App;Submitted App','','','','false','','','','','15.0','false','true','Started App','false','','','','','','','','','','<i>The <a href="https://www.stthomas.edu/catalog/undergradinfoandpolicies/bacinfoandpolicies/specialacademicprograms/associatedcollegesofthetwincitiesactc/" target="_blank">Associated Colleges of the Twin Cities (ACTC)</a> includes: Augsburg University, Hamline University, Macalester College, St. Catherine University, and the University of St. Thomas.</i>','false','Are you eligible for a tuition benefit based on your parent''s employment at the University of St. Thomas and/or one of the Associated Colleges of the Twin Cities (ACTC)?','','','','ACTC Tuition Eligibility (UGFR)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4301','true','','','','','','International','','false','','','','','0.0','false','true','','false','','','','','','','','','','','false','','','','','International Mailing Address Static (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Enter your current location (this should be the actual place of residence of the student at the time of the application).</p><p><br></p><p><em>Please do not enter the location of a relative, friend, agent, etc.</em></p>','','','','Requirement_Item__c-15');
INSERT INTO "Question__c" VALUES('Question__c-4302','true','','','','','','','','false','','','','','13.0','false','true','','false','','','','','','','','','','','false','Offer of Admission Consent','','','','Offer of Admission Consent Static (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="color: rgb(43, 43, 43);">I understand that an offer of admission from the University of St. Thomas is contingent upon successful completion of all secondary school coursework and/or college level coursework at a level similar to the work evidenced in the application, successfully clearing a prior discipline and criminal/delinquency history review (if required) and the applicant continuing to meet admission standards and expectations, as determined by St. Thomas in its sole discretion. In addition, applicants are expected to comply with the St. Thomas Student Conduct Code, Convictions, and other applicable St. Thomas policies governing student conduct. St. Thomas may rescind its offer of admission or take other action if an applicant or admitted student fails to meet the aforementioned conditions and/or engages in conduct inconsistent with these expectations. Admitted students must update St. Thomas regarding any material changes in the information submitted during the application process, including academic standing and/or disciplinary history, and must submit a final copy of their secondary school (if required) and/or post-secondary transcript for approval prior to registering for their second semester of courses at St. Thomas.</span></p>','','','','Requirement_Item__c-5');
