INSERT INTO "Question__c" VALUES('Question__c-4329','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','Relatives Attended UST Static (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 11pt;">Have any relatives ever attended the University of St. Thomas? (including the 4-year undergraduate, Dougherty Family College 2-year or graduate programs). </span><span style="font-size: 11pt; color: rgb(255, 0, 0);">*</span></p><p><br></p><p><em style="font-size: 11pt;">This information will not be visible to the admissions committee and is not considered during the University of St. Thomas application review.</em></p>','','','','Requirement_Item__c-692');
INSERT INTO "Question__c" VALUES('Question__c-4330','true','','','','','','','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','Pre-STEM Concentration Program','','','','DFC Pre-STEM Concentration Program Info Static (DFC)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">If you think you may be interested in science, technology, engineering, mathematics (STEM) and/or pre-health, then the new DFC Pre-STEM Concentration could be for you! You&#39;ll get the same great DFC experience plus the opportunity to take up to 4 math or science courses on the St. Paul campus. If gaining some extra exposure to STEM and/or pre-health sounds exciting to you, we will send you additional information on the program and how to apply.</span></p>','','','','Requirement_Item__c-685');
INSERT INTO "Question__c" VALUES('Question__c-4331','true','','','','','','','','false','','','','','4.0','false','true','','false','','','','','','','','','','','false','Are you interested in receiving more information about Dougherty Family College’s Pre-STEM Concentration program?','','','','DFC Pre-STEM Concentration Program Info (DFC)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4332','true','','','','Admit;Confirmed','','International','','false','','','','','','false','true','','false','','','','','','','','','','','false','Request your I-20','','','','Request your I-20 (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Request your I-20 by following the instructions below. These instructions are also included in your admission letter.</p><p><br></p><p>To request your I-20, you must first claim your St. Thomas account. If you have not already done so, follow the <a href="https://services.stthomas.edu/TDClient/1898/ClientPortal/KB/ArticleDet?ID=129977" target="_blank">step-by-step instructions</a> to claim your account; you will need your St. Thomas ID in order to claim your account.</p><p><br></p><p>Once you claim your account, log in to oiss.stthomas.edu with your St. Thomas email and password to request your I-20. You will need to upload your financial proof and your passport in order to request your I-20.</p><p><br></p><p>If you need additional assistance with claiming your I-20, read the instructions in your admission letter, watch our <a href="https://www.youtube.com/watch?v=SoPG-Ms4MS8" target="_blank">instructional video</a>, or contact your admissions counselor.</p><p><br></p><p>Use your I-20 to make your visa appointment; you can find visa appointment instructions on<a href="https://www.stthomas.edu/about/departments/oiss/visa-support-for-students/index.html" target="_blank"> our website</a>.</p><p><br></p><p><em>*If you are transferring your SEVIS record from another US institution, you will upload a copy of your I-20, complete the SEVIS transfer form at oiss.stthomas.edu and work with us to transfer your record.</em></p><p><em>**If you are studying on a dependent visa (H4, L2, etc.) you do not need to request an I-20. Please contact your admissions counselor if you have any questions.</em></p><p><br></p><p>You can find information on next steps for I-20, visa, deposit, and international student orientation outlined on <a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank">our website.</a></p>','','','','Requirement_Item__c-833');
INSERT INTO "Question__c" VALUES('Question__c-4333','true','','','','Admit;Confirmed','','International','','false','','','','OR','1.0','false','true','Admit;Confirmed','false','','','','','','','','','','','false','Select which scenario best describes your visa situation:','','','','Visa Information (UGTR)','Name','false','','','','','I have requested an I-20 from St. Thomas & am applying for an F-1 visaINSERT INTO "Question__c" VALUES('Question__c-4334','true','','','','Admit;Confirmed','','International','','false','','','','OR','2.0','false','true','Admit;Confirmed','false','','','','','','','','','','','false','Do you already have an F-1 visa?','','','','Visa Appointment (UGTR)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4335','true','','','','Admit;Confirmed','','International','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','Schedule your visa appointment','','','','Visa Information Static (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<dl><dd><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">Use your I-20 to make your visa appointment, you can find visa appointment instructions on </span><a href="https://www.stthomas.edu/about/departments/oiss/visa-support-for-students/index.html" target="_blank" style="background-color: rgb(255, 255, 255);">our website</a><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">.</span></dd></dl>','','','','Requirement_Item__c-834');
