INSERT INTO "Question__c" VALUES('Question__c-4352','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','','','','','Pre-Professional Program Interest Static (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 18px;">Pre-Professional Program Interest</strong></p><p><em>Optional: If you&#39;re interested in pursuing a pre-professional program, please indicate which program.</em></p>','','','','Requirement_Item__c-689');
INSERT INTO "Question__c" VALUES('Question__c-4353','true','','','','Started App;Submitted App','','','','false','','','','','8.0','false','true','Started App','false','','','','','','','','','','','false','Offer of Admission Consent','','','','Offer of Admission Consent Static (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="background-color: rgb(255, 255, 255); color: rgb(43, 43, 43);">I understand that an offer of admission from the University of St. Thomas is contingent upon successful completion of all secondary school coursework and/or college level coursework at a level similar to the work evidenced in the application, successfully clearing a prior discipline and criminal/delinquency history review (if required) and the applicant continuing to meet admission standards and expectations, as determined by St. Thomas in its sole discretion. In addition, applicants are expected to comply with the St. Thomas Student Conduct Code, Convictions, and other applicable St. Thomas policies governing student conduct. St. Thomas may rescind its offer of admission or take other action if an applicant or admitted student fails to meet the aforementioned conditions and/or engages in conduct inconsistent with these expectations. Admitted students must update St. Thomas regarding any material changes in the information submitted during the application process, including academic standing and/or disciplinary history, and must submit a final copy of their secondary school (if required) and/or post-secondary transcript for approval prior to registering for their second semester of courses at St. Thomas.</span></p>','','','','Requirement_Item__c-627');
INSERT INTO "Question__c" VALUES('Question__c-4354','true','','','','Started App;Submitted App','','','','false','','','','','9.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Offer of Admission Consent (UGTR)','Name','false','','','','','I Agree','','0124P0000003S9NQAU','','Started App','','','','','','','Requirement_Item__c-627');
INSERT INTO "Question__c" VALUES('Question__c-4355','true','','','','','','','','false','','','','','1.0','false','true','','false','','','','','','','','','','','false','Minnesota Transfer Curriculum','','','','Complete Minnesota Transfer Curriculum Static (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="color: rgb(68, 68, 68);">Completion of the </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/credit-transfer/index.html#mntc" target="_blank" style="background-color: rgb(255, 255, 255);">Minnesota Transfer Curriculum (MnTC)</a><span style="color: rgb(68, 68, 68);"> is not required for transfer admission to St. Thomas. </span><strong style="color: rgb(68, 68, 68);">MnTC is the basis for the general education requirements at institutions that are part of the Minnesota State system. </strong><span style="color: rgb(68, 68, 68);">Completion of the MnTC requires at least 40 credits and a specified number of courses or credits taken from each of the 10 MnTC goal areas. The MnTC must be completed with a minimum 2.0 GPA.</span></p>','','','','Requirement_Item__c-633');
INSERT INTO "Question__c" VALUES('Question__c-4356','true','','','','','','','','false','','','','','40.0','false','true','','false','','','','Spring 2025','','','','','','','false','','','','','Spring Term Nursing Program App Info (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 16px;">BSN Program Application</strong></p><p><br></p><p><span style="color: rgb(0, 0, 0);">The School of Nursing accepts applications for the fall term only. You can start at St. Thomas in the spring, but you will apply to the School of Nursing as a continuing St. Thomas student through the General Admission Pathway. Please visit the</span><u style="color: rgb(109, 54, 150);"> </u><a href="https://www.stthomas.edu/academics/undergraduate/nursing-major/index.html" target="_blank" style="color: rgb(109, 54, 150);"><u>School of Nursing website</u></a><span style="color: rgb(0, 0, 0);"> for more information.</span></p>','','','','Requirement_Item__c-690');
INSERT INTO "Question__c" VALUES('Question__c-4357','true','','','','','','','','false','','','','','40.0','false','true','','false','','','','Fall 2024;Fall 2025','','','','','','','false','','','','','Fall Term Nursing Program App Info (UGTR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="font-size: 16px;">BSN Program Application</strong></p><p><br></p><p><span style="font-size: inherit;">Transfer admission to the Bachelor&#39;s of Nursing (BSN) program is available for undergraduate students who wish to transfer from another college or university. It requires a secondary BSN application process after admission and enrollment at St. Thomas. Students that list Nursing as a possible major on the undergraduate transfer application will receive a separate communication from the Admissions office detailing how to access the BSN application when it opens.</span></p><p><br></p><p><strong style="font-size: inherit;"><u>Timeline</u></strong></p><ul><li><span style="font-size: inherit;">BSN Application </span>opens October 1 and closes March 1, 2025</li><li><span style="font-size: inherit;">Transfer BSN Admission Decision will be released on</span><span style="font-size: inherit; color: rgb(30, 83, 163);"> </span><span style="font-size: inherit;">April 1, 2025</span></li></ul><p><strong style="font-size: inherit;"><u>Requirements for transfer students</u></strong></p><ul><li><strong style="font-size: inherit;">Cumulative</strong><span style="font-size: inherit;"> GPA of 2.75* or higher</span></li><li><span style="font-size: inherit;">Application and acceptance to the University of St. Thomas</span></li><li><a href="https://www.stthomas.edu/academics/undergraduate/nursing-major/index.html" target="_blank" style="font-size: inherit;">Transfer students must have completed all required nursing prerequisites, or a transfer equivalent </a><span style="font-size: inherit;">before beginning nursing coursework. </span></li></ul><p><em>*Cumulative GPA is calculated using all college-level credits attempted at other colleges/universities, including Ds or Fs. PSEO, CIS, and other Dual Enrollment programs are included in the calculation of a student&#39;s cumulative GPA.</em></p><p><br></p><p>Contact your<a href="https://www.stthomas.edu/admissions/undergraduate/contact/index.html" target="_blank"> transfer counselor </a>with any questions you might have.</p>','','','','Requirement_Item__c-690');
INSERT INTO "Question__c" VALUES('Question__c-4358','true','','','','Started App;Submitted App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Essay Question 1 Static (GSSW)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><span style="background-color: rgb(255, 255, 255); font-size: 14px;">1. </span><span style="background-color: rgb(255, 255, 255); font-size: 14px; color: rgb(43, 43, 43);">What personal, educational, volunteer, or professional experiences led to your interest in pursuing a master&#39;s degree in social work at the University of St. Thomas? What are your professional goals, and how will a master&#39;s degree in social work help you to achieve them? (1000 words or less)</span></p>','','','','Requirement_Item__c-544');
