INSERT INTO "Question__c" VALUES('Question__c-4369','true','','','UST_employed_parent_guardian_spouse__c','Started App;Submitted App','','','','false','','','','','8.0','false','true','Started App','false','','','','','','','','','','','false','Is your parent(s), guardian(s), or spouse currently employed at the University of St. Thomas?','','','','Relative Currently Employed by UST (UGTRCAM)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4370','true','','','','Admit;Confirmed','','International','','false','','','','','','false','true','','false','','','','','','','','','','','false','Request your I-20','','','','Request your I-20 (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Request your I-20 by following the instructions below. These instructions are also included in your admission letter.</p><p><br></p><p>To request your I-20, you must first claim your St. Thomas account. If you have not already done so, follow the <a href="https://services.stthomas.edu/TDClient/1898/ClientPortal/KB/ArticleDet?ID=129977" target="_blank">step-by-step instructions</a> to claim your account; you will need your St. Thomas ID in order to claim your account.</p><p><br></p><p>Once you claim your account, log in to oiss.stthomas.edu with your St. Thomas email and password to request your I-20. You will need to upload your financial proof and your passport in order to request your I-20.</p><p><br></p><p>If you need additional assistance with claiming your I-20, read the instructions in your admission letter, watch our <a href="https://www.youtube.com/watch?v=SoPG-Ms4MS8" target="_blank">instructional video</a>, or contact your admissions counselor.</p><p><br></p><p>Use your I-20 to make your visa appointment; you can find visa appointment instructions on <a href="https://www.stthomas.edu/about/departments/oiss/visa-support-for-students/index.html" target="_blank">our website</a>.</p><p><br></p><p>*If you are transferring your SEVIS record from another US institution, you will upload a copy of your I-20, complete the SEVIS transfer form at oiss.stthomas.edu and work with us to transfer your record.</p><p>**If you are studying on a dependent visa (H4, L2, etc.) you do not need to request an I-20. Please contact your admissions counselor if you have any questions.</p><p><br></p><p>You can find information on next steps for I-20, visa, deposit, and international student orientation outlined on <a href="https://www.stthomas.edu/admissions/international-students/admitted-students/index.html" target="_blank">our website</a>.</p>','','','','Requirement_Item__c-890');
INSERT INTO "Question__c" VALUES('Question__c-4371','true','','','','Admit;Confirmed','','International','','false','','','','','3.0','false','true','','false','','','','','','','','','','','false','Schedule your visa appointment','','','','Visa Information Static (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Use your I-20 to make your visa appointment, you can find visa appointment instructions on <a href="https://www.stthomas.edu/about/departments/oiss/visa-support-for-students/index.html" target="_blank">our website</a>.</p>','','','','Requirement_Item__c-891');
