INSERT INTO "Question__c" VALUES('Question__c-4407','true','','','','','','','','false','','','','','0.0','false','true','','false','','','','','','','','','','','false','','','','','International Mailing Address Static (UGTRCAM)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p>Enter your current location (this should be the actual place of residence of the student at the time of the application). </p><p>Please do not enter the location of a relative, friend, agent, etc.</p>','','','','Requirement_Item__c-873');
