INSERT INTO "Question__c" VALUES('Question__c-4409','true','','','','Started App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Ryan Scholarship Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong style="font-size: 12pt; color: rgb(0, 0, 0);">Ryan Scholarship:</strong><span style="font-size: 12pt; color: rgb(0, 0, 0);"> The Ann and Pat Ryan Scholars program was established to improve workforce diversity in the field of nursing. The program provides assistance to students from backgrounds underrepresented in the field of nursing and/or historically excluded and marginalized populations (ex: first generation college student; black, indigenous, or person of color (BIPOC); male or non-binary; from a rural area (place with fewer than 5,000 people) or plan to practice in a rural location; low socioeconomic status, etc.). To be eligible, you must have a cumulative 2.5 GPA from your undergraduate degree-granting institution. </span></p>','','','','Requirement_Item__c-900');
INSERT INTO "Question__c" VALUES('Question__c-4410','true','','','','Started App','','','','false','','','','','3.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Dan and Ruth Haggerty Scholarship Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong style="color: rgb(0, 0, 0); font-size: 12pt;">Dan and Ruth Haggerty Scholarship:</strong><span style="color: rgb(0, 0, 0); font-size: 12pt;"> The Dan and Ruth Haggerty Nursing Scholars Fund provides financial assistance for students in the BSN or MSN programs in the Susan S. Morrison School of Nursing. The scholarship program is intended for students with financial need to help remove barriers to enrollment and completion of nursing programs at St. Thomas.  </span></p>','','','','Requirement_Item__c-900');
INSERT INTO "Question__c" VALUES('Question__c-4411','true','','','','Started App','','','','false','','','','','5.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Pathways Scholarship Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong style="font-size: 12pt; color: rgb(0, 0, 0);">Pathways Scholarship:</strong><span style="font-size: 12pt; color: rgb(0, 0, 0);"> The MSN Pathways Scholarship aims to support students who have experienced less-than-typical pathways to graduate school due to family obligations, dedication to public, volunteer, or military service, career change, financial challenges, or for some other reason. We value students with these diverse educational, professional, and lived experiences, and believe that they can be an asset to our program and profession. </span></p>','','','','Requirement_Item__c-900');
INSERT INTO "Question__c" VALUES('Question__c-4412','true','','','','Started App','','','','false','','','','','7.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Diversity Scholarship Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','Started App','','','<p><strong style="color: rgb(0, 0, 0); font-size: 12pt;">Diversity Scholarship:</strong><span style="color: rgb(0, 0, 0); font-size: 12pt;"> The purpose of the MSN Diversity Scholarship is to recruit, train, educate, and retain nursing students who represent the communities where nurses serve; meet the community’s and profession’s need for a more diverse workforce; and create inclusive and equitable learning environments that will assist in building cultural competence and awareness among the student body as a whole. </span></p>','','','','Requirement_Item__c-900');
INSERT INTO "Question__c" VALUES('Question__c-4413','true','','','','Started App','','','','false','','','','','2.0','false','true','Started App','false','','','','','','','','','','','false','Do you qualify for the Ryan Scholarship?','','','','Ryan Scholarship Eligibility (GSON)','Name','false','','','','','Yes, I qualify for the Ryan ScholarshipINSERT INTO "Question__c" VALUES('Question__c-4414','true','','','','Started App','','','','false','','','','','6.0','false','true','Started App','false','','','','','','','','','','','false','Do you qualify for the Pathways Scholarship?','','','','Pathways Scholarship Eligibility (GSON)','Name','false','','','','','Yes, I qualify for the Pathways ScholarshipINSERT INTO "Question__c" VALUES('Question__c-4415','true','','','','Started App','','','','false','','','','','1.0','false','true','Started App','false','','','','','','','','','','','false','','','','','Add''l. Scholarship Questions Static (GSON)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong><u>Demonstrating Financial Need:</u></strong></p><p>If you are <strong>not</strong> eligible for any scholarship options listed previously, please proceed forward to the other sections or your application. If you are eligible for any scholarship options listed previously, please answer the following questions:</p>','','','','Requirement_Item__c-794');
