INSERT INTO "Question__c" VALUES('Question__c-4426','true','','','Current_PTK_Member__c','Started App;Submitted App','','','','false','','','','','3.0','false','false','Started App','false','','','','','','','','','','','false','Are you a current Phi Theta Kappa (PTK) member?','','','','PTK Member (UGTR)','Name','false','','','','','YesINSERT INTO "Question__c" VALUES('Question__c-4427','true','','Transfer','','Started App','','','','false','','','','','','false','true','Started App','false','','','','','','','','','','','false','As a transfer applicant to the BSN program, I understand that I must also apply, and be admitted, to the University of St. Thomas as a transfer student for the fall (or prior spring) of the BSN cohort I am applying to.','','','','Transfer Statement of Understanding (UGBSN)','Name','false','','','','','I understand','','0124P0000003S9NQAU','','Started App','','','','','','','Requirement_Item__c-904');
INSERT INTO "Question__c" VALUES('Question__c-4428','true','','','Applicant_Type__c','Started App','','','','false','','','','','2.0','false','true','','false','','','','','','','','','','<i>If you are a transfer student who will begin taking classes in Spring 2025, please select "Transfer".</i>','false','Are you a new transfer student/applicant or a current student who is enrolled (taking classes) at the University of St. Thomas?','','','','UST Enrollment Status (UGBSN)','Name','false','','','','','TransferINSERT INTO "Question__c" VALUES('Question__c-4429','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','General Timeline & Requirements Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>BSN Application Timeline for currently enrolled St. Thomas Students </strong></p><p><br></p><p>The Bachelors of Science in Nursing (BSN) application for Fall 2025 cohort is open from<strong> October 1, 2024 through February 1, 2025.</strong></p><p><br></p><p>The BSN application for Fall 2025 will close on <em>February 1, 2025.</em> You will be unable to start a new BSN application, or complete or submit an existing application after the application close date.</p><p><br></p><p><em>If you have questions about the eligibility requirements or timeline for the BSN program, </em>please contact the School of Nursing at <a href="mailto:nursing@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255);">nursing@stthomas.edu</a>.</p>','','','','Requirement_Item__c-787');
INSERT INTO "Question__c" VALUES('Question__c-4430','true','','','','','','','','false','','','','','','false','true','','false','','','','','','','','','','','false','','','','','Transfer Timeline & Requirements Static (UGBSN)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong>BSN Application Timeline for new Transfer applicants </strong></p><p><br></p><p>The Bachelors of Science in Nursing (BSN) application for Fall 2025 cohort is open from <strong>October 1, 2024 through March 1, 2025.</strong></p><p><br></p><p>The BSN application for Fall 2025 will close on <em>March 1, 2025.</em> You will be unable to start a new BSN application, or complete or submit an existing application after the application close date.</p><p><br></p><p><strong>Transfer Requirement:</strong> All new Undergraduate Transfer applicants must complete and submit an <a href="https://www.stthomas.edu/application/index.html" target="_blank">Undergraduate Transfer application</a><em> in addition</em> to completing and submitting a BSN application.</p><p><br></p><p><em>If you have questions about the eligibility requirements or timeline for the BSN program, </em>please contact the School of Nursing at <a href="mailto:nursing@stthomas.edu" target="_blank" style="background-color: rgb(255, 255, 255);">nursing@stthomas.edu</a>.</p>','','','','Requirement_Item__c-787');
