INSERT INTO "Question__c" VALUES('Question__c-4449','false','','','','','','','','false','','','','OR','3.0','false','true','','false','','','','Fall 2025','','','','','','','false','','','','','Nursing Direct Admit Timeline (UGFR)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><strong style="color: rgb(43, 43, 43); font-size: 16px;"><u>Nursing Direct Admit Deadline – Dec. 1, 2024</u></strong></p><p><span style="color: rgb(43, 43, 43);">Please complete and submit this application for admission by </span><span style="color: rgb(255, 0, 0);">11:59 p.m. on Sunday, Dec. 1, 2024</span><span style="color: rgb(43, 43, 43);">, in order to be considered for Direct Admission to the Bachelor’s in Nursing program. Late applications for the Direct Admit program will not be accepted.</span></p>','','','','Requirement_Item__c-4');
INSERT INTO "Question__c" VALUES('Question__c-4450','true','','','','Started App','','','','false','','','','','0.0','false','false','','false','','','','','','','','','','','false','','','','','Licensure Static Text(GSPP)','Name','false','','','','','','','0124P0000003S9QQAU','','','','','<p><span style="font-size: 16px; color: rgb(0, 0, 0);">The Graduate School of Professional Psychology does not inquire nor consider criminal history in our admissions decisions. However, you will be required to submit a background check for future licensing board applications and may also be required to submit a background check for training opportunities during your time in the </span><span style="font-size: 16px; color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);">Graduate School of Professional Psychology.</span></p>','','','','Requirement_Item__c-768');
