BEGIN TRANSACTION;
CREATE TABLE "Academic_Term__c" (
	id VARCHAR(255) NOT NULL, 
	"Academic_Year_Code__c" VARCHAR(255), 
	"Activate_Application_Date__c" VARCHAR(255), 
	"Banner_Term_Code__c" VARCHAR(255), 
	"Early_Action_End_Date__c" VARCHAR(255), 
	"Early_Decision_End_Date__c" VARCHAR(255), 
	"Early_Decision_Start_Date__c" VARCHAR(255), 
	"End_Application_Date__c" VARCHAR(255), 
	"Financial_Aid_Processing_Year__c" VARCHAR(255), 
	"Housing_End_Date__c" VARCHAR(255), 
	"Housing_Start_Date__c" VARCHAR(255), 
	"Name" VARCHAR(255), 
	"Regular_Decision_End_Date__c" VARCHAR(255), 
	"Term_10th_Day__c" VARCHAR(255), 
	"Term_End_Date__c" VARCHAR(255), 
	"Term_Start_Date__c" VARCHAR(255), 
	"Term__c" VARCHAR(255), 
	PRIMARY KEY (id)
);
CREATE TABLE "Account" (
	id VARCHAR(255) NOT NULL, 
	"Banner_Code__c" VARCHAR(255), 
	"Banner_Key__c" VARCHAR(255), 
	"CEEB_Code__c" VARCHAR(255), 
	"CEEB_Integration_Code__c" VARCHAR(255), 
	"EASY_Validation_Record__c" VARCHAR(255), 
	"Inactive_School__c" VARCHAR(255), 
	"Name" VARCHAR(255), 
	"RecordTypeId" VARCHAR(255), 
	"Surrogate_ID__c" VARCHAR(255), 
	"hed__Billing_Address_Inactive__c" VARCHAR(255), 
	"hed__Billing_County__c" VARCHAR(255), 
	"hed__School_Code__c" VARCHAR(255), 
	"hed__Shipping_County__c" VARCHAR(255), 
	"School_College_Name__c" VARCHAR(255), 
	"ParentId" VARCHAR(255), 
	PRIMARY KEY (id)
);
CREATE TABLE "Account_rt_mapping" (
	record_type_id VARCHAR(18) NOT NULL, 
	developer_name VARCHAR(255), 
	is_person_type BOOLEAN, 
	PRIMARY KEY (record_type_id)
);
CREATE TABLE "Application_Control__c" (
	id VARCHAR(255) NOT NULL, 
	"Academic_Level__c" VARCHAR(255), 
	"Active__c" VARCHAR(255), 
	"Allow_Cancel_From__c" VARCHAR(255), 
	"Allow_Confirm_From__c" VARCHAR(255), 
	"Allow_Submit_From__c" VARCHAR(255), 
	"Allow_Withdraw_From__c" VARCHAR(255), 
	"Application_Start_Status__c" VARCHAR(255), 
	"Arrow_Color__c" VARCHAR(255), 
	"Button_Color__c" VARCHAR(255), 
	"Button_Text_Color__c" VARCHAR(255), 
	"Cancel_Status__c" VARCHAR(255), 
	"Default__c" VARCHAR(255), 
	"Degree_Levels__c" VARCHAR(255), 
	"Hide_Term_Program__c" VARCHAR(255), 
	"Line_Color__c" VARCHAR(255), 
	"Link_Color__c" VARCHAR(255), 
	"Logo_Static_Resource_Path__c" VARCHAR(255), 
	"Logo_Static_Resource__c" VARCHAR(255), 
	"Name" VARCHAR(255), 
	"School_College__c" VARCHAR(255), 
	"Show_on_App_Finder__c" VARCHAR(255), 
	"Submit_Status__c" VARCHAR(255), 
	"Template__c" VARCHAR(255), 
	"Text_Color__c" VARCHAR(255), 
	"URL_Parameter__c" VARCHAR(255), 
	"Withdraw_Status__c" VARCHAR(255), 
	PRIMARY KEY (id)
);

