}

@keyframes fadeIn{

0%{
opacity: 0;
transform: scale(0);
}

50%{
opacity: 1;
transform: scale(1);
}

0%{
opacity: 1;
transform: scale(0.5);
}

}


@keyframes secondspan{

0%{
transform: translateX(-100%);
}

60%{
transform: translateX(-100%);
}

100%{
transform: translateX(0%);
}

}



