            background-color: rgb(152, 153, 155);
        }
        
        .enrollmentCheckList, .dropdown {
            position: relative;
            display: inline-block;
        }
        
        .dropdown-content{
            display: none;
            background-color: #f1f1f1;
            max-width: 211px;
            overflow: auto;
            z-index: 0;
        }
        
        .dropdown-content a{
            color: black;
            padding: 15px 19px;
            text-decoration: none;
